window.songs=[{"order":2,"id":"02-einsamer-mann","title":"Einsamer Mann","titleZh":"孤独的人","lines":[{"id":"dracula-das-musical-02-001","lineIndex":1,"speaker":"","original":"Trannsylvanien ist nicht England","ipa":"/tɾˈanzʏlvˌɑnɪən ɪst nˈɪçt ˈɛŋlant/","en":"Transylvania is not England","zh":"特兰西瓦尼亚不是英格兰","note":"","sourceLineIndex":1},{"id":"dracula-das-musical-02-002","lineIndex":2,"speaker":"","original":"Meine Art ist nicht die Ihre","ipa":"/mˌaɪnə ˈɑːɾt ɪst nˈɪçt diː ˌiːrə/","en":"My way is not yours","zh":"我的作风和你们的也有所不同","note":"","sourceLineIndex":2},{"id":"dracula-das-musical-02-003","lineIndex":3,"speaker":"","original":"Hier getrennt von Freud und Leid","ipa":"/hˈiːɾ ɡətɾˈɛnt fɔn frˈɔøt ʊnt lˈaɪt/","en":"Here separated from joy and sorrow","zh":"在这儿我摆脱了痛苦和欢乐","note":"","sourceLineIndex":3},{"id":"dracula-das-musical-02-004","lineIndex":4,"speaker":"","original":"Vermeide ich das Licht","ipa":"/fɛɾmˈaɪdə ɪç das lˈɪçt/","en":"I avoid the light","zh":"躲避着阳光","note":"","sourceLineIndex":4},{"id":"dracula-das-musical-02-005","lineIndex":5,"speaker":"","original":"Und leb in Dunkelheit","ipa":"/ʊnt lˈeːp ɪn dˈʊnkəlhˌaɪt/","en":"And live in darkness","zh":"活在黑暗里","note":"","sourceLineIndex":5},{"id":"dracula-das-musical-02-006","lineIndex":6,"speaker":"","original":"Kalter Wind weht durch die Gänge","ipa":"/kˈaltɜ vˈɪnt vˈeːt dʊɐç diː ɡˈɛŋə/","en":"Cold wind blows through the corridors","zh":"冷风吹过长廊","note":"","sourceLineIndex":6},{"id":"dracula-das-musical-02-007","lineIndex":7,"speaker":"","original":"Und die Zinnen sind zerbrochen","ipa":"/ʊnt diː tsˈɪnən zɪnt tsɛɾbɾˈɔxən/","en":"And the battlements are broken","zh":"城垛已然破碎","note":"","sourceLineIndex":7},{"id":"dracula-das-musical-02-008","lineIndex":8,"speaker":"","original":"Ich blieb stehen in der Zeit","ipa":"/ɪç blˈiːp ʃtˈeːən ɪn dɛɾ tsˈaɪt/","en":"I stood still in time","zh":"我凝固在时间的长河中","note":"","sourceLineIndex":8},{"id":"dracula-das-musical-02-009","lineIndex":9,"speaker":"","original":"Ein Kind der alten Zeit","ipa":"/aɪn kˈɪnt dɛɾ ˈaltən tsˈaɪt/","en":"A child of old times","zh":"我来自旧时代","note":"","sourceLineIndex":9},{"id":"dracula-das-musical-02-010","lineIndex":10,"speaker":"","original":"In der das Schwert regiert","ipa":"/ɪn dɛɾ das ʃvˈeːɾt reːɡˈiːɾt/","en":"Where the sword reigns","zh":"那个由剑统治的时代","note":"","sourceLineIndex":10},{"id":"dracula-das-musical-02-011","lineIndex":11,"speaker":"","original":"Das ist vorbei","ipa":"/das ɪst foːɾbˈaɪ/","en":"This is over","zh":"这些都已经过去","note":"","sourceLineIndex":11},{"id":"dracula-das-musical-02-012","lineIndex":12,"speaker":"","original":"Und nun kommt etwas Neues","ipa":"/ʊnt nˈuːn kˈɔmt ˈɛtvɑːs nˈɔøəs/","en":"And now something new comes","zh":"新事物已经到来","note":"","sourceLineIndex":12},{"id":"dracula-das-musical-02-013","lineIndex":13,"speaker":"","original":"Ich bin bereit","ipa":"/ɪç bɪn bərˈaɪt/","en":"I'm ready","zh":"我已经准备好","note":"","sourceLineIndex":13},{"id":"dracula-das-musical-02-014","lineIndex":14,"speaker":"","original":"Befreit von alten Geistern","ipa":"/bəfrˈaɪt fɔn ˈaltən ɡˈaɪstɜn/","en":"Freed from old ghosts","zh":"脱离古老的灵魂","note":"","sourceLineIndex":14},{"id":"dracula-das-musical-02-015","lineIndex":15,"speaker":"","original":"Und meister die Zeichen der Zeit","ipa":"/ʊnt mˈaɪstɜ diː tsˈaɪçən dɛɾ tsˈaɪt/","en":"And master the signs of the times","zh":"主宰时间的印记","note":"","sourceLineIndex":15},{"id":"dracula-das-musical-02-016","lineIndex":16,"speaker":"","original":"Bald ist alles Hier vergessen","ipa":"/bˈalt ɪst ˈaləs hˈiːɾ fɛɾɡˈɛsən/","en":"Soon everything here will be forgotten","zh":"这儿的一切都会很快被遗忘","note":"","sourceLineIndex":16},{"id":"dracula-das-musical-02-017","lineIndex":17,"speaker":"","original":"Meine Zukunft liegt in England","ipa":"/mˌaɪnə tsuːkˈʊnft lˈiːkt ɪn ˈɛŋlant/","en":"My future lies in England","zh":"我的未来在英格兰","note":"","sourceLineIndex":17},{"id":"dracula-das-musical-02-018","lineIndex":18,"speaker":"","original":"Ich such nicht nach eitlen Glanz","ipa":"/ɪç zˈuːx nˈɪçt nɑːx ˈaɪtlən ɡlˈants/","en":"I'm not looking for vain gloss","zh":"我不再追寻空洞的荣光","note":"","sourceLineIndex":18},{"id":"dracula-das-musical-02-019","lineIndex":19,"speaker":"","original":"Ich bleibe auf Distanz","ipa":"/ɪç blˈaɪbə aʊf dˈɪstɑːnts/","en":"I keep my distance","zh":"我会和人保持距离","note":"","sourceLineIndex":19},{"id":"dracula-das-musical-02-020","lineIndex":20,"speaker":"","original":"Weil ich ein Einzelgänger bin","ipa":"/vˌaɪl ɪç aɪn ˈaɪntsˌɛlɡɛŋɜ bɪn/","en":"Because I'm a loner","zh":"因为我是独行者","note":"","sourceLineIndex":20},{"id":"dracula-das-musical-02-021","lineIndex":21,"speaker":"","original":"Ich geh und sag","ipa":"/ɪç ɡˈeː ʊnt zˈɑːk/","en":"I'll go and say","zh":"我即将离开","note":"","sourceLineIndex":21},{"id":"dracula-das-musical-02-022","lineIndex":22,"speaker":"","original":"Leb wohl trostlose Heimat","ipa":"/lˈeːp vˈoːl tɾˈɔstloːzə hˈaɪmɑːt/","en":"Farewell desolate homeland","zh":"这荒凉的家乡","note":"","sourceLineIndex":22},{"id":"dracula-das-musical-02-023","lineIndex":23,"speaker":"","original":"Mein Traum ist bald erfüllt","ipa":"/maɪn tɾˈaʊm ɪst bˈalt ɛɾfˈʏlt/","en":"My dream will soon be fulfilled","zh":"我的梦想","note":"","sourceLineIndex":23},{"id":"dracula-das-musical-02-024","lineIndex":24,"speaker":"","original":"In euerem London","ipa":"/ɪn ˈɔøərəm lˈɔndoːn/","en":"In your London","zh":"马上会在你们的伦敦实现","note":"","sourceLineIndex":24},{"id":"dracula-das-musical-02-025","lineIndex":25,"speaker":"","original":"Wird jedes Verlangen gestillt","ipa":"/vˌɪɾt jˈeːdəs fɛɾlˈaŋən ɡəʃtˈɪlt/","en":"Every desire is satisfied","zh":"一切渴望都将被满足","note":"","sourceLineIndex":25}],"sourceOrder":2,"displayOrder":1},{"order":3,"id":"03-whitby-bay","title":"Whitby Bay","titleZh":"惠特比湾","lines":[{"id":"dracula-das-musical-03-001","lineIndex":1,"speaker":"","original":"Draußen auf dem Meer jagt der Wind dunkle Wolken.","ipa":"/dɾˈaʊsən aʊf deːm mˈeːɾ jˈɑːkt dɛɾ vˈɪnt dˈʊŋklə vˈɔlkən/","en":"Out at sea the wind chases dark clouds.","zh":"外面的海面上风卷乌云","note":"","sourceLineIndex":1},{"id":"dracula-das-musical-03-003","lineIndex":2,"speaker":"","original":"Ich bin einsam hier wenn das Licht Schatten wirft über Whitby Bay.","ipa":"/ɪç bɪn ˈaɪnzˌɑːm hˈiːɾ vˌɛn das lˈɪçt ʃˈatən vˈɪɾft ˌyːbɜ vˈɪtbiː bˈɛɪ/","en":"I'm lonely here when the light casts shadows over Whitby Bay.","zh":"我在这儿如此的孤独灯光下将我的影子投在惠特比","note":"","sourceLineIndex":3},{"id":"dracula-das-musical-03-006","lineIndex":3,"speaker":"","original":"Weißt du noch den Weg","ipa":"/vˈaɪst duː nɔx deːn vˈeːk/","en":"Do you still know the way?","zh":"你是否还记得","note":"","sourceLineIndex":6},{"id":"dracula-das-musical-03-007","lineIndex":4,"speaker":"","original":"den wir Zwei heimlich fuhren.","ipa":"/deːn viːɾ tsvˈaɪ hˈaɪmlɪç fˈuːrən/","en":"which the two of us drove secretly.","zh":"我们一起悄悄驶过的那条路","note":"","sourceLineIndex":7},{"id":"dracula-das-musical-03-008","lineIndex":5,"speaker":"","original":"Runter an den Steg","ipa":"/rˈʊntɜ an deːn ʃtˈeːk/","en":"Down to the jetty","zh":"夏夜的漫天星光","note":"","sourceLineIndex":8},{"id":"dracula-das-musical-03-009","lineIndex":6,"speaker":"","original":"Sommernacht, Sternenlicht","ipa":"/zˈɔmɜnˌaxt ʃtˈɛɾnənlˌɪçt/","en":"Summer night, starlight","zh":"投在那条小路上","note":"","sourceLineIndex":9},{"id":"dracula-das-musical-03-010","lineIndex":7,"speaker":"","original":"Über Whitby Bay.","ipa":"/ˌyːbɜ vˈɪtbiː bˈɛɪ/","en":"About Whitby Bay.","zh":"就在惠特比","note":"","sourceLineIndex":10},{"id":"dracula-das-musical-03-011","lineIndex":8,"speaker":"","original":"Wir tanzten hinein in das Glück.","ipa":"/viːɾ tˈantstən hɪnˈaɪn ɪn das ɡlˈʏk/","en":"We danced into happiness.","zh":"我们在这儿欢乐的起舞","note":"","sourceLineIndex":11},{"id":"dracula-das-musical-03-012","lineIndex":9,"speaker":"","original":"Zu ferner Orchestermusik.","ipa":"/tsuː fˈɛɾnɜ ˈɔɾkɛstɜmuːzˌiːk/","en":"To distant orchestral music.","zh":"伴着远处的音乐","note":"","sourceLineIndex":12},{"id":"dracula-das-musical-03-013","lineIndex":10,"speaker":"","original":"Dann ein Kuss, zart und sacht.","ipa":"/dan aɪn kˈʊs tsˈaɾt ʊnt zˈaxt/","en":"Then a kiss, tender and gentle.","zh":"一个轻柔的吻","note":"","sourceLineIndex":13},{"id":"dracula-das-musical-03-014","lineIndex":11,"speaker":"","original":"Denke nun Tag und Nacht","ipa":"/dˈɛŋkə nˈuːn tˈɑːk ʊnt nˈaxt/","en":"Now think day and night","zh":"魂牵梦萦","note":"","sourceLineIndex":14},{"id":"dracula-das-musical-03-015","lineIndex":12,"speaker":"","original":"nur an Whitby Bay","ipa":"/nˈuːɾ an vˈɪtbiː bˈɛɪ/","en":"only at Whitby Bay","zh":"只在惠特比","note":"","sourceLineIndex":15},{"id":"dracula-das-musical-03-016","lineIndex":13,"speaker":"","original":"Komm und halt mich fest","ipa":"/kˈɔm ʊnt hˈalt mɪç fˈɛst/","en":"Come and hold me","zh":"快来抱紧我","note":"","sourceLineIndex":16},{"id":"dracula-das-musical-03-017","lineIndex":14,"speaker":"","original":"Kalt sind meine Hände.","ipa":"/kˈalt zɪnt mˌaɪnə hˈɛndə/","en":"My hands are cold.","zh":"我的手如此冰冷","note":"","sourceLineIndex":17},{"id":"dracula-das-musical-03-018","lineIndex":15,"speaker":"","original":"Warum ging ich fort und lies dich dort allein.","ipa":"/vɑːrˈʊm ɡˈɪŋ ɪç fˈɔɾt ʊnt lˈiːs dɪç dˈɔɾt alˈaɪn/","en":"Why did I leave and left you there alone.","zh":"我为什么要离开把你一个人留下","note":"","sourceLineIndex":18},{"id":"dracula-das-musical-03-020","lineIndex":16,"speaker":"","original":"Und stünde es in meiner Macht","ipa":"/ʊnt ʃtˈʏndə ɛs ɪn mˌaɪnɜ mˈaxt/","en":"And if it were in my power","zh":"这些都由不得我","note":"","sourceLineIndex":20},{"id":"dracula-das-musical-03-021","lineIndex":17,"speaker":"","original":"Dann wäre ich bei dir heute Nacht.","ipa":"/dan vˈɛːrə ɪç baɪ diːɾ hˈɔøtə nˈaxt/","en":"Then I would be with you tonight.","zh":"多希望今晚你能陪在我身边","note":"","sourceLineIndex":21},{"id":"dracula-das-musical-03-022","lineIndex":18,"speaker":"","original":"Wir warn so glücklich hier","ipa":"/viːɾ vˈaɾn zoː ɡlˈʏklɪç hˈiːɾ/","en":"We were so happy here","zh":"我们将多么快乐","note":"","sourceLineIndex":22},{"id":"dracula-das-musical-03-023","lineIndex":19,"speaker":"","original":"Ich sehn mich so nach dir.","ipa":"/ɪç zˈeːn mɪç zoː nɑːx dˈiːɾ/","en":"I'm so longing for you.","zh":"我是如此的渴望你","note":"","sourceLineIndex":23},{"id":"dracula-das-musical-03-024","lineIndex":20,"speaker":"","original":"Und nach Whitby Bay.","ipa":"/ʊnt nɑːx vˈɪtbiː bˈɛɪ/","en":"And to Whitby Bay.","zh":"想念着惠特比","note":"","sourceLineIndex":24},{"id":"dracula-das-musical-03-025","lineIndex":21,"speaker":"","original":"Einsam durch die Nacht","ipa":"/ˈaɪnzˌɑːm dʊɐç diː nˈaxt/","en":"Lonely through the night","zh":"孤独地度过长夜","note":"","sourceLineIndex":25},{"id":"dracula-das-musical-03-026","lineIndex":22,"speaker":"","original":"Trägt der Wind dunkle Wolken","ipa":"/tɾˈɛːkt dɛɾ vˈɪnt dˈʊŋklə vˈɔlkən/","en":"The wind carries dark clouds","zh":"风卷乌云","note":"","sourceLineIndex":26},{"id":"dracula-das-musical-03-027","lineIndex":23,"speaker":"","original":"Doch am Himmel wacht","ipa":"/dɔx am hˈɪməl vˈaxt/","en":"But the sky is watching","zh":"但是望向天空","note":"","sourceLineIndex":27},{"id":"dracula-das-musical-03-028","lineIndex":24,"speaker":"","original":"Hell ein Stern bringt dich heim.","ipa":"/hˈɛl aɪn ʃtˈɛɾn bɾˈɪŋt dɪç hˈaɪm/","en":"Bright a star brings you home.","zh":"那颗明亮的星会带你回家","note":"","sourceLineIndex":28},{"id":"dracula-das-musical-03-029","lineIndex":25,"speaker":"","original":"Heim nach Whitby Bay.","ipa":"/hˈaɪm nɑːx vˈɪtbiː bˈɛɪ/","en":"Home to Whitby Bay.","zh":"回到惠特比","note":"","sourceLineIndex":29},{"id":"dracula-das-musical-03-030","lineIndex":26,"speaker":"","original":"Mina","ipa":"/mˈiːnɑː/","en":"Mina","zh":"米娜","note":"","sourceLineIndex":30},{"id":"dracula-das-musical-03-031","lineIndex":27,"speaker":"","original":"Der Klang ist fremd","ipa":"/dɛɾ klˈaŋ ɪst frˈɛmt/","en":"The sound is strange","zh":"这声音虽陌生","note":"","sourceLineIndex":31},{"id":"dracula-das-musical-03-032","lineIndex":28,"speaker":"","original":"Und doch lockt dich mein Rufen","ipa":"/ʊnt dɔx lˈɔkt dɪç maɪn rˈuːfən/","en":"And yet my calling lures you","zh":"但你已听见我的呼唤","note":"","sourceLineIndex":32},{"id":"dracula-das-musical-03-033","lineIndex":29,"speaker":"","original":"Hab keine Angst","ipa":"/hˈɑːp kˈaɪnə ˈaŋst/","en":"Don't be afraid","zh":"别害怕","note":"","sourceLineIndex":33},{"id":"dracula-das-musical-03-034","lineIndex":30,"speaker":"","original":"schon bald werd ich bei dir sein","ipa":"/ʃˌoːn bˈalt vˈeːɾt ɪç baɪ diːɾ zaɪn/","en":"soon I will be with you","zh":"我很快会带着一份特殊的礼物","note":"","sourceLineIndex":34},{"id":"dracula-das-musical-03-035","lineIndex":31,"speaker":"","original":"mit einem besondren Geschenk","ipa":"/mɪt ˌaɪnəm bəzˈɔndɾən ɡəʃˈɛŋk/","en":"with a special gift","zh":"来和你在一起","note":"","sourceLineIndex":35}],"sourceOrder":3,"displayOrder":2},{"order":4,"id":"04-jonathans-schlafzimmer","title":"Jonathans Schlafzimmer","titleZh":"乔纳森的卧室","lines":[{"id":"dracula-das-musical-04-001","lineIndex":1,"speaker":"","original":"Jonathan, Jonathan, Jonathan","ipa":"/jˈoːnatˌɑːn jˈoːnatˌɑːn jˈoːnatˌɑːn/","en":"VAMPIRE GIRLS: Jonathan, Jonathan, Jonathan","zh":"乔纳森，乔纳森，乔纳森","note":"","sourceLineIndex":1},{"id":"dracula-das-musical-04-002","lineIndex":2,"speaker":"","original":"Ach Mina ich bin wie gefangen hier","ipa":"/ˈax mˈiːnɑː ɪç bɪn viː ɡəfˈaŋən hˈiːɾ/","en":"Oh Mina, I'm trapped here","zh":"米娜，我在这儿像个囚犯","note":"","sourceLineIndex":2},{"id":"dracula-das-musical-04-003","lineIndex":3,"speaker":"","original":"Man spielt ein schauerliches Spiel mit mir","ipa":"/man ʃpˈiːlt aɪn ʃˈaʊɜlˌɪçəs ʃpˈiːl mɪt mˈiːɾ/","en":"A horrible game is being played with me","zh":"有人在和我玩恐怖的游戏","note":"","sourceLineIndex":3},{"id":"dracula-das-musical-04-004","lineIndex":4,"speaker":"","original":"Ein Fluch liegt auf diesem Ort","ipa":"/aɪn flˈʊx lˈiːkt aʊf dˌiːzəm ˈɔɾt/","en":"There is a curse on this place","zh":"这个地方有诅咒","note":"","sourceLineIndex":4},{"id":"dracula-das-musical-04-005","lineIndex":5,"speaker":"","original":"Es steckt ein Tier in diesem irren Mann","ipa":"/ɛs ʃtˈɛkt aɪn tˈiːɾ ɪn dˌiːzəm ˈɪrən mˈan/","en":"There's an animal in this crazy man","zh":"我成了那个疯子手中的玩物","note":"","sourceLineIndex":5},{"id":"dracula-das-musical-04-006","lineIndex":6,"speaker":"","original":"Lässt er mich laufen oder greift er an","ipa":"/lˈɛst ɛɾ mɪç lˈaʊfən ˌoːdɜ ɡɾˈaɪft ɛɾ ˈan/","en":"Does he let me go or does he attack","zh":"他会让我跑还是转而攻击我","note":"","sourceLineIndex":6},{"id":"dracula-das-musical-04-007","lineIndex":7,"speaker":"","original":"Ein Ausweg – schon bin ich fort","ipa":"/aɪn ˈaʊsvˌeːk ʃˌoːn bɪn ɪç fˈɔɾt/","en":"One way out - I'm gone","zh":"如果能找到出口，我还能逃离","note":"","sourceLineIndex":7},{"id":"dracula-das-musical-04-008","lineIndex":8,"speaker":"","original":"Was soll ich tun","ipa":"/vˈas zˌɔl ɪç tˈuːn/","en":"What should I do?","zh":"我该怎么做","note":"","sourceLineIndex":8},{"id":"dracula-das-musical-04-009","lineIndex":9,"speaker":"","original":"Wo geht’s hier raus","ipa":"/vˌoː ɡˈeːts hˈiːɾ rˈaʊs/","en":"Where do you go from here?","zh":"从哪儿能出去","note":"","sourceLineIndex":9},{"id":"dracula-das-musical-04-010","lineIndex":10,"speaker":"","original":"Der Kragen wird mir eng","ipa":"/dɛɾ kɾˈɑːɡən vˌɪɾt miːɾ ˈɛŋ/","en":"My collar is getting tight","zh":"被链子紧紧缠住","note":"","sourceLineIndex":10},{"id":"dracula-das-musical-04-011","lineIndex":11,"speaker":"","original":"Ein Spinnennetz","ipa":"/aɪn ʃpˈɪnənˌɛts/","en":"A spider web","zh":"被挂在蜘蛛网中","note":"","sourceLineIndex":11},{"id":"dracula-das-musical-04-012","lineIndex":12,"speaker":"","original":"In dem ich wehrlos häng","ipa":"/ɪn deːm ɪç vˈeːɾloːs hˈɛŋ/","en":"In which I hang defenseless","zh":"我如此无助","note":"","sourceLineIndex":12},{"id":"dracula-das-musical-04-013","lineIndex":13,"speaker":"","original":"Jonathan","ipa":"/jˈoːnatˌɑːn/","en":"VAMPIRE GIRLS: Jonathan","zh":"乔纳森","note":"","sourceLineIndex":13},{"id":"dracula-das-musical-04-014","lineIndex":14,"speaker":"","original":"Ich höre Stimmen aus der Unterwelt","ipa":"/ɪç hˈøːrə ʃtˈɪmən ˌaʊs dɛɾ ˌʊntɜvˈɛlt/","en":"I hear voices from the underworld","zh":"我听到地狱传来的声音","note":"","sourceLineIndex":14},{"id":"dracula-das-musical-04-015","lineIndex":15,"speaker":"","original":"Man lacht als ob man mich zum Narren hält","ipa":"/man lˈaxt als ˌɔp man mɪç tsʊm nˈarən hˈɛlt/","en":"People laugh as if they were making a fool of me","zh":"他们把我当做傻瓜一样嘲笑","note":"","sourceLineIndex":15},{"id":"dracula-das-musical-04-016","lineIndex":16,"speaker":"","original":"Es klingt wie schwarze Magie","ipa":"/ɛs klˈɪŋt viː ʃvˈaɾtsə maɡˈiː/","en":"It sounds like black magic","zh":"听着像是黑魔法","note":"","sourceLineIndex":16},{"id":"dracula-das-musical-04-017","lineIndex":17,"speaker":"","original":"Jonathan","ipa":"/jˈoːnatˌɑːn/","en":"VAMPIRE GIRLS: Jonathan","zh":"乔纳森","note":"","sourceLineIndex":17},{"id":"dracula-das-musical-04-018","lineIndex":18,"speaker":"","original":"Auf deine Antwort wart ich tagelang","ipa":"/aʊf dˌaɪnə ˈantvɔɾt vɑːɾt ɪç tˈɑɡəlˌaŋ/","en":"I waited for your answer for days","zh":"几天来我在等着你的回信","note":"","sourceLineIndex":18},{"id":"dracula-das-musical-04-019","lineIndex":19,"speaker":"","original":"Ob hier ein Brief von mir nach Außen drang","ipa":"/ˌɔp hˈiːɾ aɪn bɾˈiːf fɔn miːɾ nɑːx ˈaʊsən dɾˈaŋ/","en":"Whether a letter from me leaked out here","zh":"但这信也许已被扣下","note":"","sourceLineIndex":19},{"id":"dracula-das-musical-04-020","lineIndex":20,"speaker":"","original":"Erfahr ich am Ende nie","ipa":"/ɛɾfˈɑːɾ ɪç am ˈɛndə nˈiː/","en":"I'll never find out in the end","zh":"我不知道这一切何时结束","note":"","sourceLineIndex":20},{"id":"dracula-das-musical-04-021","lineIndex":21,"speaker":"","original":"Jonathan","ipa":"/jˈoːnatˌɑːn/","en":"VAMPIRE GIRLS: Jonathan","zh":"乔纳森","note":"","sourceLineIndex":21},{"id":"dracula-das-musical-04-022","lineIndex":22,"speaker":"","original":"Jonathan","ipa":"/jˈoːnatˌɑːn/","en":"Jonathan","zh":"乔纳森","note":"","sourceLineIndex":22},{"id":"dracula-das-musical-04-023","lineIndex":23,"speaker":"","original":"Jonathan","ipa":"/jˈoːnatˌɑːn/","en":"Jonathan","zh":"乔纳森","note":"","sourceLineIndex":23},{"id":"dracula-das-musical-04-024","lineIndex":24,"speaker":"","original":"Jonathan","ipa":"/jˈoːnatˌɑːn/","en":"Jonathan","zh":"乔纳森","note":"","sourceLineIndex":24}],"sourceOrder":4,"displayOrder":3},{"order":5,"id":"05-fur-immer-jung","title":"Für immer jung","titleZh":"永远年轻","lines":[{"id":"dracula-das-musical-05-001","lineIndex":1,"speaker":"","original":"Schmieg deinen Mund an meinen Mund","ipa":"/ʃmˈiːk dˌaɪnən mˈʊnt an mˌaɪnən mˈʊnt/","en":"Put your mouth on my mouth","zh":"将你的唇覆上我的唇","note":"","sourceLineIndex":1},{"id":"dracula-das-musical-05-002","lineIndex":2,"speaker":"","original":"Will deine Nähe spüren","ipa":"/vɪl dˌaɪnə nˈɛːə ʃpˈyːrən/","en":"Wants to feel your closeness","zh":"让我感受你的亲近","note":"","sourceLineIndex":2},{"id":"dracula-das-musical-05-003","lineIndex":3,"speaker":"","original":"Atme die Lust an meiner Brust","ipa":"/ˈatmə diː lˈʊst an mˌaɪnɜ bɾˈʊst/","en":"Breathe the pleasure on my chest","zh":"从气息中吸收我们的欲望","note":"","sourceLineIndex":3},{"id":"dracula-das-musical-05-004","lineIndex":4,"speaker":"","original":"Lass dich von mir verführen","ipa":"/lˈas dɪç fɔn miːɾ fɛɾfˈyːrən/","en":"Let me seduce you","zh":"接受我们的诱惑","note":"","sourceLineIndex":4},{"id":"dracula-das-musical-05-005","lineIndex":5,"speaker":"","original":"Willst du uns nicht berühren","ipa":"/vɪlst duː ʊns nˈɪçt bərˈyːrən/","en":"Don't you want to touch us","zh":"难道你不想触碰我们的身躯","note":"","sourceLineIndex":5},{"id":"dracula-das-musical-05-006","lineIndex":6,"speaker":"","original":"mach dir nichts vor","ipa":"/mˈax diːɾ nˈɪçts fˈɔɾ/","en":"don't kid yourself","zh":"不要再压抑你的本能","note":"","sourceLineIndex":6},{"id":"dracula-das-musical-05-007","lineIndex":7,"speaker":"","original":"Maßlos und wild","ipa":"/mˈasloːs ʊnt vˈɪlt/","en":"Immoderate and wild","zh":"放纵而狂野","note":"","sourceLineIndex":7},{"id":"dracula-das-musical-05-008","lineIndex":8,"speaker":"","original":"sanft und verspielt","ipa":"/zˈanft ʊnt fɛɾʃpˈiːlt/","en":"gentle and playful","zh":"温柔而又刺激","note":"","sourceLineIndex":8},{"id":"dracula-das-musical-05-009","lineIndex":9,"speaker":"","original":"dreh dich unsren Tänzen","ipa":"/dɾˈeː dɪç ˈʊnsrən tˈɛntsən/","en":"turn to our dances","zh":"在我们的舞蹈中沉迷","note":"","sourceLineIndex":9},{"id":"dracula-das-musical-05-010","lineIndex":10,"speaker":"","original":"Fraglos wir gehen, bis zum Extrem","ipa":"/frˈaɡloːs viːɾ ɡˈeːən bɪs tsʊm ɛkstɾˈeːm/","en":"Without question we go to extremes","zh":"只要你要求 我们就带你进入天堂","note":"","sourceLineIndex":10},{"id":"dracula-das-musical-05-011","lineIndex":11,"speaker":"","original":"Trunken von den Essenzen","ipa":"/tɾˈʊŋkən fɔn deːn ɛsˈɛntsən/","en":"Drunk on the essences","zh":"陶醉于这美妙的香气","note":"","sourceLineIndex":11},{"id":"dracula-das-musical-05-012","lineIndex":12,"speaker":"","original":"Bis an die wahren Grenzen","ipa":"/bɪs an diː vˈɑːrən ɡɾˈɛntsən/","en":"To the true limits","zh":"把一切都交给你的身体","note":"","sourceLineIndex":12},{"id":"dracula-das-musical-05-013","lineIndex":13,"speaker":"","original":"deiner Natur","ipa":"/dˌaɪnɜ natˈuːɾ/","en":"your nature","zh":"享受极致的欢愉","note":"","sourceLineIndex":13},{"id":"dracula-das-musical-05-014","lineIndex":14,"speaker":"","original":"Lieb für immer","ipa":"/lˈiːp fyːɾ ˈɪmɜ/","en":"Love forever","zh":"永远的生命","note":"","sourceLineIndex":14},{"id":"dracula-das-musical-05-015","lineIndex":15,"speaker":"","original":"Leb für immer","ipa":"/lˈeːp fyːɾ ˈɪmɜ/","en":"Live forever","zh":"永恒的爱情","note":"","sourceLineIndex":15},{"id":"dracula-das-musical-05-016","lineIndex":16,"speaker":"","original":"Nimm für immer","ipa":"/nˈɪm fyːɾ ˈɪmɜ/","en":"Take forever","zh":"永远掠夺","note":"","sourceLineIndex":16},{"id":"dracula-das-musical-05-017","lineIndex":17,"speaker":"","original":"Tanz für immer","ipa":"/tˈants fyːɾ ˈɪmɜ/","en":"Dance forever","zh":"永远舞蹈","note":"","sourceLineIndex":17},{"id":"dracula-das-musical-05-018","lineIndex":18,"speaker":"","original":"Sing für immer","ipa":"/zˈɪŋ fyːɾ ˈɪmɜ/","en":"Sing forever","zh":"永远歌唱","note":"","sourceLineIndex":18},{"id":"dracula-das-musical-05-019","lineIndex":19,"speaker":"","original":"Jung für immer","ipa":"/jˈʊŋ fyːɾ ˈɪmɜ/","en":"Young forever","zh":"青春永驻","note":"","sourceLineIndex":19},{"id":"dracula-das-musical-05-020","lineIndex":20,"speaker":"","original":"Wie schmeckt dein Blut in meinen Mund","ipa":"/viː ʃmˈɛkt daɪn blˈuːt ɪn mˌaɪnən mˈʊnt/","en":"How does your blood taste in my mouth","zh":"我的唇吮吸你的血","note":"","sourceLineIndex":20},{"id":"dracula-das-musical-05-021","lineIndex":21,"speaker":"","original":"Für immer jung","ipa":"/fyːɾ ˈɪmɜ jˈʊŋ/","en":"Forever young","zh":"青春永驻","note":"","sourceLineIndex":21},{"id":"dracula-das-musical-05-022","lineIndex":22,"speaker":"","original":"Für immer jung","ipa":"/fyːɾ ˈɪmɜ jˈʊŋ/","en":"Forever young","zh":"青春永驻","note":"","sourceLineIndex":22},{"id":"dracula-das-musical-05-023","lineIndex":23,"speaker":"","original":"Für immer jung","ipa":"/fyːɾ ˈɪmɜ jˈʊŋ/","en":"Forever young","zh":"青春永驻","note":"","sourceLineIndex":23},{"id":"dracula-das-musical-05-024","lineIndex":24,"speaker":"","original":"Dein heißes Blut in meinem Mund","ipa":"/daɪn hˈaɪsəs blˈuːt ɪn mˌaɪnəm mˈʊnt/","en":"Your hot blood in my mouth","zh":"你的热血沾上我的唇","note":"","sourceLineIndex":24},{"id":"dracula-das-musical-05-025","lineIndex":25,"speaker":"","original":"Für immer jung","ipa":"/fyːɾ ˈɪmɜ jˈʊŋ/","en":"Forever young","zh":"青春永驻","note":"","sourceLineIndex":25},{"id":"dracula-das-musical-05-026","lineIndex":26,"speaker":"","original":"Für immer jung","ipa":"/fyːɾ ˈɪmɜ jˈʊŋ/","en":"Forever young","zh":"青春永驻","note":"","sourceLineIndex":26},{"id":"dracula-das-musical-05-027","lineIndex":27,"speaker":"","original":"Für immer jung","ipa":"/fyːɾ ˈɪmɜ jˈʊŋ/","en":"Forever young","zh":"青春永驻","note":"","sourceLineIndex":27},{"id":"dracula-das-musical-05-028","lineIndex":28,"speaker":"","original":"Für immer jung","ipa":"/fyːɾ ˈɪmɜ jˈʊŋ/","en":"Forever young","zh":"青春永驻","note":"","sourceLineIndex":28},{"id":"dracula-das-musical-05-029","lineIndex":29,"speaker":"","original":"Für immer jung","ipa":"/fyːɾ ˈɪmɜ jˈʊŋ/","en":"Forever young","zh":"青春永驻","note":"","sourceLineIndex":29}],"sourceOrder":5,"displayOrder":4},{"order":6,"id":"06-blut","title":"Blut","titleZh":"血","lines":[{"id":"dracula-das-musical-06-001","lineIndex":1,"speaker":"","original":"Să nu-l atingeți! V-am dat un ordin!","ipa":"/zˈɑː nˈuːˈɛl ˈɑtɪŋˌeːtiː fˈaʊam dˈɑːt ˈʊn ˈɔɾdɪn/","en":"Să nu-l atingeți! V-am dat un ordin!","zh":"都给我住手！我已下过命令！","note":"","sourceLineIndex":1},{"id":"dracula-das-musical-06-002","lineIndex":2,"speaker":"","original":"N-ați vrut să-l țineți","ipa":"/ˈɛnˈɑtiː fˈaʊrˈuːt zˈɑːˈɛl tˈiːneːtˌiː/","en":"N-ați vrut să-l țineți","zh":"这个人是我的！","note":"","sourceLineIndex":2},{"id":"dracula-das-musical-06-003","lineIndex":3,"speaker":"","original":"Ihr wisst, dieser Mann gehört nur mir","ipa":"/iːɾ vˈɪst dˌiːzɜ mˈan ɡəhˈœɾt nˈuːɾ mˈiːɾ/","en":"You know this man belongs only to me","zh":"你们明知，他只属于我！","note":"","sourceLineIndex":3},{"id":"dracula-das-musical-06-004","lineIndex":4,"speaker":"","original":"Wir brauchen ihn","ipa":"/viːɾ bɾˈaʊxən ˈiːn/","en":"Vampire ladies: We need him","zh":"我们需要他","note":"","sourceLineIndex":4},{"id":"dracula-das-musical-06-005","lineIndex":5,"speaker":"","original":"Schon höchste Zeit","ipa":"/ʃˌoːn hˈœkstə tsˈaɪt/","en":"It's about time","zh":"已经很久了","note":"","sourceLineIndex":5},{"id":"dracula-das-musical-06-006","lineIndex":6,"speaker":"","original":"Der Hunger schreit","ipa":"/dɛɾ hˈʊŋɜ ʃrˈaɪt/","en":"Hunger screams","zh":"我们饥饿难耐","note":"","sourceLineIndex":6},{"id":"dracula-das-musical-06-007","lineIndex":7,"speaker":"","original":"Gibt es denn heut' gar nichts für uns","ipa":"/ɡˈiːpt ɛs dɛn hˈɔøt ɡˈɑːɾ nˈɪçts fyːɾ ˈʊns/","en":"There's nothing for us today","zh":"难道我们今晚没有食物了么？","note":"","sourceLineIndex":7},{"id":"dracula-das-musical-06-008","lineIndex":8,"speaker":"","original":"Habt Ihr immer d'ran gedacht","ipa":"/hˈɑːpt iːɾ ˈɪmɜ dˈeːrˈɑːn ɡədˈaxt/","en":"Have you always thought of that?","zh":"你们可曾失望过？","note":"","sourceLineIndex":8},{"id":"dracula-das-musical-06-009","lineIndex":9,"speaker":"","original":"und euch Beute mitgebracht","ipa":"/ʊnt ɔøç bˈɔøtə mˈɪtɡəbɾˌaxt/","en":"and brought you booty","zh":"我已为你们带来猎物","note":"","sourceLineIndex":9},{"id":"dracula-das-musical-06-010","lineIndex":10,"speaker":"","original":"Ich hab' für Hunger doch Verständnis.","ipa":"/ɪç hˈɑːp fyːɾ hˈʊŋɜ dɔx fɛɾʃtˈɛndnɪs/","en":"I understand hunger.","zh":"我理解你们的饥饿","note":"","sourceLineIndex":10},{"id":"dracula-das-musical-06-011","lineIndex":11,"speaker":"","original":"Erst der Meister, dann die Brut","ipa":"/ˈeːɾst dɛɾ mˈaɪstɜ dan diː bɾˈuːt/","en":"First the master, then the brood","zh":"主人为先，然后轮到你们","note":"","sourceLineIndex":11},{"id":"dracula-das-musical-06-012","lineIndex":12,"speaker":"","original":"Dieses Bad in jungem Blut - es erneuert unser Bündnis.","ipa":"/dˌiːzəs bˈɑːt ɪn jˈʊŋəm blˈuːt ɛs ɛɾnˈɔøɜt ˌʊnzɜ bˈʏndnɪs/","en":"This bath in young blood - it renews our alliance.","zh":"这场年轻血液中的沐浴使我们重获新生","note":"","sourceLineIndex":12},{"id":"dracula-das-musical-06-014","lineIndex":13,"speaker":"","original":"Hier - für euch - nun verschwindet","ipa":"/hˈiːɾ fyːɾ ɔøç nˈuːn fɛɾʃvˈɪndət/","en":"Here - for you - now disappear","zh":"这是给你们的—马上离开！","note":"","sourceLineIndex":14},{"id":"dracula-das-musical-06-015","lineIndex":14,"speaker":"","original":"Ich allein will es tun","ipa":"/ɪç alˈaɪn vɪl ɛs tˈuːn/","en":"I alone want to do it","zh":"我要独享这大餐","note":"","sourceLineIndex":15},{"id":"dracula-das-musical-06-016","lineIndex":15,"speaker":"","original":"Wie das Kleine sich windet...","ipa":"/viː das klˈaɪnə zɪç vˈɪndət/","en":"Vampire Lady: How the little one squirms...","zh":"这只是个扭动的小肉球","note":"","sourceLineIndex":16},{"id":"dracula-das-musical-06-017","lineIndex":16,"speaker":"","original":"Wenn der Schein nicht trügt schreit ein Weib nach dem Sohn...","ipa":"/vˌɛn dɛɾ ʃˈaɪn nˈɪçt tɾˈyːkt ʃrˈaɪt aɪn vˈaɪp nɑːx deːm zˈoːn/","en":"If appearances are not deceiving a woman cries out for her son...","zh":"那必是一位母亲在哭喊着寻回她的孩子","note":"","sourceLineIndex":17},{"id":"dracula-das-musical-06-019","lineIndex":17,"speaker":"","original":"Meine Kinder dieser Nacht - in der Dunkelheit erwacht - willst du nicht heimlich sie belauschen","ipa":"/mˌaɪnə kˈɪndɜ dˌiːzɜ nˈaxt ɪn dɛɾ dˈʊnkəlhˌaɪt ɛɾvˈaxt vɪlst duː nˈɪçt hˈaɪmlɪç ziː bəlˈaʊʃən/","en":"My children of this night - awakened in the darkness - Don't you want to secretly eavesdrop on them?","zh":"我的黑夜之子在这暗夜苏醒你可听得它们的高歌？","note":"","sourceLineIndex":19},{"id":"dracula-das-musical-06-022","lineIndex":18,"speaker":"","original":"Ich bin ihr Meister, ihr Bojar -","ipa":"/ɪç bɪn iːɾ mˈaɪstɜ iːɾ bˈoːjɑːɾ/","en":"I am their master, their boyar -","zh":"我是你们的主人","note":"","sourceLineIndex":22},{"id":"dracula-das-musical-06-023","lineIndex":19,"speaker":"","original":"ruf' sie herbei an den Altar -","ipa":"/rˈuːf ziː hɛɾbˈaɪ an deːn altˈɑːɾ/","en":"call her to the altar -","zh":"是我召它们来这圣坛","note":"","sourceLineIndex":23},{"id":"dracula-das-musical-06-024","lineIndex":20,"speaker":"","original":"der schwarzen Töne, die berauschen","ipa":"/dɛɾ ʃvˈaɾtsən tˈøːnə diː bərˈaʊʃən/","en":"of black tones that intoxicate","zh":"这醉人的黑夜","note":"","sourceLineIndex":24},{"id":"dracula-das-musical-06-025","lineIndex":21,"speaker":"","original":"Doch nun such' ich das Neue und ich lass' sie zurück.","ipa":"/dɔx nˈuːn zˈuːx ɪç das nˈɔøə ʊnt ɪç lˈas ziː tsuːrˈʏk/","en":"But now I'm looking for something new and I leave her behind.","zh":"但如今我仍要离开它们去寻找新的世界","note":"","sourceLineIndex":25},{"id":"dracula-das-musical-06-027","lineIndex":22,"speaker":"","original":"Ohne Wehmut und Reue","ipa":"/ˈoːnə vˈeːmuːt ʊnt rˈɔøə/","en":"Without sadness or regret","zh":"在异乡的土地上","note":"","sourceLineIndex":27},{"id":"dracula-das-musical-06-028","lineIndex":23,"speaker":"","original":"Auf ins fremde Land","ipa":"/aʊf ɪns frˈɛmdə lˈant/","en":"Off to a foreign country","zh":"没有忧伤，没有痛苦","note":"","sourceLineIndex":28},{"id":"dracula-das-musical-06-029","lineIndex":24,"speaker":"","original":"Denn ich brauch' frisches Blut","ipa":"/dɛn ɪç bɾˈaʊx frˈɪʃəs blˈuːt/","en":"Because I need fresh blood","zh":"因为我将获得鲜血的滋养","note":"","sourceLineIndex":29},{"id":"dracula-das-musical-06-030","lineIndex":25,"speaker":"","original":"um mich zu stärken -","ipa":"/ʊm mɪç tsuː ʃtˈɛɾkən/","en":"to strengthen me -","zh":"变得强壮","note":"","sourceLineIndex":30},{"id":"dracula-das-musical-06-031","lineIndex":26,"speaker":"","original":"Blut, aus frischem Quell","ipa":"/blˈuːt ˌaʊs frˈɪʃəm kvˈɛl/","en":"Blood, from a fresh source","zh":"血液，新鲜的血液！","note":"","sourceLineIndex":31},{"id":"dracula-das-musical-06-032","lineIndex":27,"speaker":"","original":"Keiner wird es merken - in London stirbt's sich schnell","ipa":"/kˈaɪnɜ vˌɪɾt ɛs mˈɛɾkən ɪn lˈɔndoːn ʃtˈɪɾpts zɪç ʃnˈɛl/","en":"Nobody will notice - Things die quickly in London","zh":"伦敦表面平静无波我这恶魔却在迅速逼近！","note":"","sourceLineIndex":32},{"id":"dracula-das-musical-06-034","lineIndex":28,"speaker":"","original":"Hier in England - ihrem Land -","ipa":"/hˈiːɾ ɪn ˈɛŋlant ˌiːrəm lˈant/","en":"Here in England - her country -","zh":"在英格兰，她的国土上","note":"","sourceLineIndex":34},{"id":"dracula-das-musical-06-035","lineIndex":29,"speaker":"","original":"wie jeder Fremde unbekannt","ipa":"/viː jˈeːdɜ frˈɛmdə ˈʊnbəkˌant/","en":"like every stranger unknown","zh":"我如同每个默默无闻的异乡人","note":"","sourceLineIndex":35},{"id":"dracula-das-musical-06-036","lineIndex":30,"speaker":"","original":"bin ich mit Taten und mit Namen","ipa":"/bɪn ɪç mɪt tˈɑːtən ʊnt mɪt nˈɑːmən/","en":"I am with deeds and with name","zh":"无人知晓我的姓名与所作所为","note":"","sourceLineIndex":36},{"id":"dracula-das-musical-06-037","lineIndex":31,"speaker":"","original":"Ein bleiches Antlitz im Gewühl","ipa":"/aɪn blˈaɪçəs ˈantlˌɪts ɪm ɡəvˈyːl/","en":"A pale face in the crowd","zh":"而我会成为人群中苍白的面容","note":"","sourceLineIndex":37},{"id":"dracula-das-musical-06-038","lineIndex":32,"speaker":"","original":"- ein kurzes stechendes Gefühl -","ipa":"/aɪn kˈʊɐtsəs ʃtˈɛçəndəs ɡəfˈyːl/","en":"- a short stabbing feeling -","zh":"一闪而过却咄咄逼人","note":"","sourceLineIndex":38},{"id":"dracula-das-musical-06-039","lineIndex":33,"speaker":"","original":"und in Dir keimt mein kalter Samen","ipa":"/ʊnt ɪn diːɾ kˈaɪmt maɪn kˈaltɜ zˈɑːmən/","en":"and in you my cold seed germinates","zh":"我的冷酷会在人们之中萌芽","note":"","sourceLineIndex":39},{"id":"dracula-das-musical-06-040","lineIndex":34,"speaker":"","original":"Hier begegnen die Leute","ipa":"/hˈiːɾ bəɡˈeːɡnən diː lˈɔøtə/","en":"This is where people meet","zh":"这里的人们","note":"","sourceLineIndex":40},{"id":"dracula-das-musical-06-041","lineIndex":35,"speaker":"","original":"mir mit Argwohn und List","ipa":"/miːɾ mɪt ˈaɾɡvoːn ʊnt lˈɪst/","en":"me with suspicion and cunning","zh":"对我只有猜忌和欺骗","note":"","sourceLineIndex":41},{"id":"dracula-das-musical-06-042","lineIndex":36,"speaker":"","original":"Sind nur schwierige Beute","ipa":"/zɪnt nˈuːɾ ʃvˈiːrɪɡə bˈɔøtə/","en":"They're just difficult prey","zh":"这里只有艰难枯燥的狩猎","note":"","sourceLineIndex":42},{"id":"dracula-das-musical-06-043","lineIndex":37,"speaker":"","original":"Auf in's neue Land","ipa":"/aʊf ˈiːns nˈɔøə lˈant/","en":"Off to the new country","zh":"我要去那片全新的大陆","note":"","sourceLineIndex":43},{"id":"dracula-das-musical-06-044","lineIndex":38,"speaker":"","original":"denn ich brauch' frisches Blut","ipa":"/dɛn ɪç bɾˈaʊx frˈɪʃəs blˈuːt/","en":"because I need fresh blood","zh":"因为我需要喷薄而出的","note":"","sourceLineIndex":44},{"id":"dracula-das-musical-06-045","lineIndex":39,"speaker":"","original":"aus zarten Kehlen","ipa":"/ˌaʊs tsˈaɾtən kˈeːlən/","en":"from tender throats","zh":"新鲜血液","note":"","sourceLineIndex":45},{"id":"dracula-das-musical-06-046","lineIndex":40,"speaker":"","original":"Frag' nicht, ob sich's schickt","ipa":"/frˈɑːk nˈɪçt ˌɔp zˈɪçs ʃˈɪkt/","en":"Don't ask if it's appropriate","zh":"别对我讲是非","note":"","sourceLineIndex":46},{"id":"dracula-das-musical-06-047","lineIndex":41,"speaker":"","original":"Keinen wird es quälen","ipa":"/kˈaɪnən vˌɪɾt ɛs kvˈɛːlən/","en":"It won't hurt anyone","zh":"这轻微的过失","note":"","sourceLineIndex":47},{"id":"dracula-das-musical-06-048","lineIndex":42,"speaker":"","original":"ein Kavalliersdelikt","ipa":"/aɪn kˌɑvalˈiːɾsdəlˌɪkt/","en":"a cavalier offense","zh":"不会令你有丝毫痛苦","note":"","sourceLineIndex":48},{"id":"dracula-das-musical-06-049","lineIndex":43,"speaker":"","original":"Auch du und Mina","ipa":"/ˌaʊx duː ʊnt mˈiːnɑː/","en":"Also you and Mina","zh":"你和米娜","note":"","sourceLineIndex":49},{"id":"dracula-das-musical-06-050","lineIndex":44,"speaker":"","original":"sollt ewig leben","ipa":"/zˈɔlt ˈeːvɪç lˈeːbən/","en":"should live forever","zh":"将得永生","note":"","sourceLineIndex":50},{"id":"dracula-das-musical-06-051","lineIndex":45,"speaker":"","original":"Auf mein Gebot hin","ipa":"/aʊf maɪn ɡəbˈoːt hˈɪn/","en":"At my command","zh":"成为我的奴仆","note":"","sourceLineIndex":51},{"id":"dracula-das-musical-06-052","lineIndex":46,"speaker":"","original":"bringt Ihr das Entsetzen unter's Volk","ipa":"/bɾˈɪŋt iːɾ das ɛntzˈɛtsən ˈʊntˌeːɾs fˈɔlk/","en":"you bring horror to the people","zh":"将恐惧带去那里的人们","note":"","sourceLineIndex":52},{"id":"dracula-das-musical-06-053","lineIndex":47,"speaker":"","original":"Sprich nicht von Mina","ipa":"/ʃpɾˈɪç nˈɪçt fɔn mˈiːnɑː/","en":"Don't talk about Mina","zh":"不许伤害米娜！","note":"","sourceLineIndex":53},{"id":"dracula-das-musical-06-054","lineIndex":48,"speaker":"","original":"Sie ist mein Leben","ipa":"/ziː ɪst maɪn lˈeːbən/","en":"She is my life","zh":"她是我的生命！","note":"","sourceLineIndex":54},{"id":"dracula-das-musical-06-055","lineIndex":49,"speaker":"","original":"Du willst nicht hören","ipa":"/duː vɪlst nˈɪçt hˈøːrən/","en":"You don't want to listen","zh":"你没听到么！","note":"","sourceLineIndex":55},{"id":"dracula-das-musical-06-056","lineIndex":50,"speaker":"","original":"Ewig lebt Ihr nur durch mich","ipa":"/ˈeːvɪç lˈeːpt iːɾ nˈuːɾ dʊɐç mɪç/","en":"You only live forever through me","zh":"我将赋予你们永恒的生命！","note":"","sourceLineIndex":56},{"id":"dracula-das-musical-06-057","lineIndex":51,"speaker":"","original":"Eine kleine Menge Blut","ipa":"/ˌaɪnə klˈaɪnə mˈɛŋə blˈuːt/","en":"A small amount of blood","zh":"一点点血液","note":"","sourceLineIndex":57},{"id":"dracula-das-musical-06-058","lineIndex":52,"speaker":"","original":"ist ein würdiger Tribut","ipa":"/ɪst aɪn vˈʏɾdɪɡɜ tɾˈiːbuːt/","en":"is a worthy tribute","zh":"只是你小小的牺牲","note":"","sourceLineIndex":58},{"id":"dracula-das-musical-06-059","lineIndex":53,"speaker":"","original":"Denn es wird reichlich dir gegeben","ipa":"/dɛn ɛs vˌɪɾt rˈaɪçlɪç diːɾ ɡəɡˈeːbən/","en":"For it will be given to you in abundance","zh":"而你获得的回馈更多","note":"","sourceLineIndex":59},{"id":"dracula-das-musical-06-060","lineIndex":54,"speaker":"","original":"Sind wir verbannt auch in die Nacht","ipa":"/zɪnt viːɾ fɛɾbˈant ˌaʊx ɪn diː nˈaxt/","en":"We are also banished into the night","zh":"我们虽被放逐在黑夜","note":"","sourceLineIndex":60},{"id":"dracula-das-musical-06-061","lineIndex":55,"speaker":"","original":"und nur für's Schattenreich gemacht","ipa":"/ʊnt nˈuːɾ fˈyːɾs ʃˈatənrˌaɪç ɡəmˈaxt/","en":"and made only for the shadow kingdom","zh":"仅与魔鬼为伴","note":"","sourceLineIndex":61},{"id":"dracula-das-musical-06-062","lineIndex":56,"speaker":"","original":"so kosten wir doch voll am Leben","ipa":"/zoː kˈɔstən viːɾ dɔx fˈɔl am lˈeːbən/","en":"so we taste fully alive","zh":"但这是我们永生的代价！","note":"","sourceLineIndex":62},{"id":"dracula-das-musical-06-063","lineIndex":57,"speaker":"","original":"Lasst uns langsam geniessen","ipa":"/lˈast ʊns lˈaŋzɑːm ɡənˈiːsən/","en":"Let's enjoy slowly","zh":"让我们慢慢享受","note":"","sourceLineIndex":63},{"id":"dracula-das-musical-06-064","lineIndex":58,"speaker":"","original":"Wir verlier'n keine Zeit","ipa":"/viːɾ fɛɾlˈiːɾn kˈaɪnə tsˈaɪt/","en":"We don't waste any time","zh":"不必在乎时光流逝","note":"","sourceLineIndex":64},{"id":"dracula-das-musical-06-065","lineIndex":59,"speaker":"","original":"Blut in Strömen wird fliessen","ipa":"/blˈuːt ɪn ʃtɾˈøːmən vˌɪɾt flˈiːsən/","en":"Blood will flow in streams","zh":"血液不住流淌","note":"","sourceLineIndex":65},{"id":"dracula-das-musical-06-066","lineIndex":60,"speaker":"","original":"London röchelt schon","ipa":"/lˈɔndoːn rˈœçəlt ʃˈoːn/","en":"London is already wheezing","zh":"伦敦已开始喘息","note":"","sourceLineIndex":66},{"id":"dracula-das-musical-06-067","lineIndex":61,"speaker":"","original":"London bringt frisches Blut","ipa":"/lˈɔndoːn bɾˈɪŋt frˈɪʃəs blˈuːt/","en":"London brings new blood","zh":"它将提供源源不断的鲜血","note":"","sourceLineIndex":67},{"id":"dracula-das-musical-06-068","lineIndex":62,"speaker":"","original":"- mir zur Erlösung","ipa":"/miːɾ tsuːɾ ɛɾlˈøːzʊŋ/","en":"- me to salvation","zh":"使我获得救赎","note":"","sourceLineIndex":68},{"id":"dracula-das-musical-06-069","lineIndex":63,"speaker":"","original":"Die Themse färbt sich rot","ipa":"/diː tˈɛmzə fˈɛɾpt zɪç rˈoːt/","en":"The Thames turns red","zh":"泰晤士河将一片殷红","note":"","sourceLineIndex":69},{"id":"dracula-das-musical-06-070","lineIndex":64,"speaker":"","original":"Frischfleisch, statt Verwesung","ipa":"/frˈɪʃflaɪʃ ʃtˈat fɛɾvˈeːzʊŋ/","en":"Fresh meat instead of rotting","zh":"新生代替腐朽","note":"","sourceLineIndex":70},{"id":"dracula-das-musical-06-071","lineIndex":65,"speaker":"","original":"Ein Loblieb auf den Tod","ipa":"/aɪn lˈɔbliːp aʊf deːn tˈoːt/","en":"A praise for death","zh":"是我们为死神奏响的赞歌","note":"","sourceLineIndex":71},{"id":"dracula-das-musical-06-072","lineIndex":66,"speaker":"","original":"Blut an London's Kragen","ipa":"/blˈuːt an lˈɔndoːns kɾˈɑːɡən/","en":"Blood on London's collar","zh":"鲜血将淹没伦敦","note":"","sourceLineIndex":72},{"id":"dracula-das-musical-06-073","lineIndex":67,"speaker":"","original":"- Stadt in Anämie","ipa":"/ʃtˈat ɪn ˈanɛːmˌiː/","en":"- City in anemia","zh":"使这城市陷入绝望","note":"","sourceLineIndex":73},{"id":"dracula-das-musical-06-074","lineIndex":68,"speaker":"","original":"Blut, das will ich jagen denn sterben werd' ich nie","ipa":"/blˈuːt das vɪl ɪç jˈɑːɡən dɛn ʃtˈɛɾbən vˈeːɾt ɪç nˈiː/","en":"Blood, that's what I want to hunt because I will never die","zh":"我不断猎取鲜血成为这世界永恒的噩梦！","note":"","sourceLineIndex":74}],"sourceOrder":6,"displayOrder":5},{"order":7,"id":"07-das-lied-vom-meister","title":"Das Lied vom Meister","titleZh":"大师之歌","lines":[{"id":"dracula-das-musical-07-001","lineIndex":1,"speaker":"","original":"Vor langer Zeit da befiel mich ein Fieber","ipa":"/fˌɔɾ lˈaŋɜ tsˈaɪt dɑː bəfˈiːl mɪç aɪn fˈiːbɜ/","en":"A long time ago I was struck by a fever","zh":"很久以前的一个傍晚","note":"","sourceLineIndex":1},{"id":"dracula-das-musical-07-002","lineIndex":2,"speaker":"","original":"Plötzlich des Abends im Garten","ipa":"/plˈœtslɪç dɛs ˈɑːbənts ɪm ɡˈaɾtən/","en":"Suddenly one evening in the garden","zh":"我在花园里突然陷入一股异样的兴奋","note":"","sourceLineIndex":2},{"id":"dracula-das-musical-07-003","lineIndex":3,"speaker":"","original":"Hörte im Kopf eine Stimme, die sagte","ipa":"/hˈœɾtə ɪm kˈɔpf ˌaɪnə ʃtˈɪmə diː zˈɑːɡtə/","en":"Heard a voice in my head saying","zh":"我听见有个声音在我脑海中说道","note":"","sourceLineIndex":3},{"id":"dracula-das-musical-07-004","lineIndex":4,"speaker":"","original":"Worauf mein Freund willst du warten","ipa":"/voːrˈaʊf maɪn frˈɔønt vɪlst duː vˈaɾtən/","en":"What are you waiting for my friend?","zh":"我的朋友 你还在等待什么","note":"","sourceLineIndex":4},{"id":"dracula-das-musical-07-005","lineIndex":5,"speaker":"","original":"Ich hab die Stimme des Meisters vernommen","ipa":"/ɪç hˈɑːp diː ʃtˈɪmə dɛs mˈaɪstɜs fɛɾnˈɔmən/","en":"I heard the master's voice","zh":"我听见主人的声音","note":"","sourceLineIndex":5},{"id":"dracula-das-musical-07-006","lineIndex":6,"speaker":"","original":"Und lauschte seinem Plan","ipa":"/ʊnt lˈaʊʃtə zˌaɪnəm plˈɑːn/","en":"And listened to his plan","zh":"并且聆听他的计划","note":"","sourceLineIndex":6},{"id":"dracula-das-musical-07-007","lineIndex":7,"speaker":"","original":"Er kann auf Ruf eines andern nur kommen","ipa":"/ɛɾ kˌan aʊf rˈuːf ˌaɪnəs ˈandɜn nˈuːɾ kˈɔmən/","en":"He can only come at the call of another","zh":"他可能还呼唤了别人","note":"","sourceLineIndex":7},{"id":"dracula-das-musical-07-008","lineIndex":8,"speaker":"","original":"Und ich war sein Mann","ipa":"/ʊnt ɪç vɑːɾ zaɪn mˈan/","en":"And I was his man","zh":"但是只有我注定是他的奴仆","note":"","sourceLineIndex":8},{"id":"dracula-das-musical-07-009","lineIndex":9,"speaker":"","original":"Seither sehe ich alles, das er sieht","ipa":"/zˈaɪtɜ zˈeːə ɪç ˈaləs das ɛɾ zˈiːt/","en":"Since then, I see everything he sees","zh":"自那之后 我能见他眼之所见","note":"","sourceLineIndex":9},{"id":"dracula-das-musical-07-010","lineIndex":10,"speaker":"","original":"Geh ich die Wege, die er geht","ipa":"/ɡˈeː ɪç diː vˈeːɡə diː ɛɾ ɡˈeːt/","en":"I'll go the way he goes","zh":"我能到他足之所及","note":"","sourceLineIndex":10},{"id":"dracula-das-musical-07-011","lineIndex":11,"speaker":"","original":"Und ich spür, wenn er schlüpft","ipa":"/ʊnt ɪç ʃpˈyːɾ vˌɛn ɛɾ ʃlˈʏpft/","en":"And I can feel when it hatches","zh":"我能感受到","note":"","sourceLineIndex":11},{"id":"dracula-das-musical-07-012","lineIndex":12,"speaker":"","original":"Durch deine Tür","ipa":"/dʊɐç dˌaɪnə tˈyːɾ/","en":"Through your door","zh":"他穿过你的大门","note":"","sourceLineIndex":12},{"id":"dracula-das-musical-07-013","lineIndex":13,"speaker":"","original":"Seither bin ich sein einziger Zeuge","ipa":"/zˈaɪtɜ bɪn ɪç zaɪn ˈaɪntsɪɡɜ tsˈɔøɡə/","en":"Since then I have been his only witness","zh":"自那之后 我成为唯一能看见他的人","note":"","sourceLineIndex":13},{"id":"dracula-das-musical-07-014","lineIndex":14,"speaker":"","original":"Hör sein Gelächter und shcweige in der Not","ipa":"/hˈøːɾ zaɪn ɡəlˈɛçtɜ ʊnt ˌɛshˌɑːtsˈeːvˈaɪɡə ɪn dɛɾ nˈoːt/","en":"Hear his laughter and be silent in times of need","zh":"我能感觉到他的一切感受 一切快乐与苦恼","note":"","sourceLineIndex":14},{"id":"dracula-das-musical-07-015","lineIndex":15,"speaker":"","original":"Denn sein Biss macht dich bestimmt","ipa":"/dɛn zaɪn bˈɪs mˈaxt dɪç bəʃtˈɪmt/","en":"Because his bite makes you determined","zh":"他的噬咬无疑能让你不死","note":"","sourceLineIndex":15},{"id":"dracula-das-musical-07-016","lineIndex":16,"speaker":"","original":"untot","ipa":"/ˈʊntˌoːt/","en":"undead","zh":"不死","note":"","sourceLineIndex":16},{"id":"dracula-das-musical-07-017","lineIndex":17,"speaker":"","original":"Untot?","ipa":"/ˈʊntˌoːt/","en":"Undead?","zh":"不死？","note":"","sourceLineIndex":17},{"id":"dracula-das-musical-07-018","lineIndex":18,"speaker":"","original":"Verzeihen Sie meinen Fachjargon.","ipa":"/fɛɾtsˈaɪən ziː mˌaɪnən fˈaxjaɾɡˌoːn/","en":"Pardon my jargon.","zh":"对不起 也许这个词对您来说太难懂了","note":"","sourceLineIndex":18},{"id":"dracula-das-musical-07-019","lineIndex":19,"speaker":"","original":"Mr. Renfield, ich fürchte Sie leiden an hysterischen Phantasmen.","ipa":"/ˌɛmˈɛɾ rˈɛnfiːlt ɪç fˈʏɾçtə ziː lˈaɪdən an hˈʏstərˌɪʃən fˈantasmən/","en":"Mr. Renfield, I fear you are suffering from hysterical phantasms.","zh":"伦福尔德先生，我恐怕您陷入了疯狂的幻想中","note":"","sourceLineIndex":19},{"id":"dracula-das-musical-07-020","lineIndex":20,"speaker":"","original":"Nein Doktor, ich sehe es so klar, wie die Nase in ihrem Gesicht.","ipa":"/nˈaɪn dˈɔktoːɾ ɪç zˈeːə ɛs zoː klˈɑːɾ viː diː nˈɑːzə ɪn ˌiːrəm ɡəzˈɪçt/","en":"No doctor, I see it as clearly as the nose on her face.","zh":"不 医生 我很清醒 我清楚这件事 正如看见您脸上的鼻子一样清楚","note":"","sourceLineIndex":20},{"id":"dracula-das-musical-07-021","lineIndex":21,"speaker":"","original":"Auf sieben Meeren segelt er","ipa":"/aʊf zˈiːbən mˈeːrən zˈeːɡəlt ɛɾ/","en":"He sails on seven seas","zh":"他驾船跨过重洋","note":"","sourceLineIndex":21},{"id":"dracula-das-musical-07-022","lineIndex":22,"speaker":"","original":"sein Schiff liegt hart am Wind","ipa":"/zaɪn ʃˈɪf lˈiːkt hˈaɾt am vˈɪnt/","en":"his ship lies close to the wind","zh":"冲破狂风而来","note":"","sourceLineIndex":22},{"id":"dracula-das-musical-07-023","lineIndex":23,"speaker":"","original":"wenn blutig rot der Mond erscheint","ipa":"/vˌɛn blˈuːtɪç rˈoːt dɛɾ mˈoːnt ɛɾʃˈaɪnt/","en":"when the moon appears bloody red","zh":"在惨淡的月光下","note":"","sourceLineIndex":23},{"id":"dracula-das-musical-07-024","lineIndex":24,"speaker":"","original":"dann schlachtet er ein Kind.","ipa":"/dan ʃlˈaxtət ɛɾ aɪn kˈɪnt/","en":"then he slaughters a child.","zh":"他畅饮猎物的鲜血","note":"","sourceLineIndex":24},{"id":"dracula-das-musical-07-025","lineIndex":25,"speaker":"","original":"Diese Nachtmusik ist das Meisterstück","ipa":"/dˌiːzə nˈaxtmuːzˌiːk ɪst das mˈaɪstɜʃtˌʏk/","en":"This night music is a masterpiece","zh":"这首夜之乐章正是他的杰作","note":"","sourceLineIndex":25},{"id":"dracula-das-musical-07-026","lineIndex":26,"speaker":"","original":"Und der Meister liebt diese Weise.","ipa":"/ʊnt dɛɾ mˈaɪstɜ lˈiːpt dˌiːzə vˈaɪzə/","en":"And the master loves this way.","zh":"主人喜爱这种方式","note":"","sourceLineIndex":26},{"id":"dracula-das-musical-07-027","lineIndex":27,"speaker":"","original":"Sing mit mir und du bekommst dafür","ipa":"/zˈɪŋ mɪt miːɾ ʊnt duː bəkˈɔmst dɑːfˈyːɾ/","en":"Sing with me and you get what you get in return","zh":"随我一起歌唱","note":"","sourceLineIndex":27},{"id":"dracula-das-musical-07-028","lineIndex":28,"speaker":"","original":"Eine Reise ins ewige Glück.","ipa":"/ˌaɪnə rˈaɪzə ɪns ˈeːvɪɡə ɡlˈʏk/","en":"A journey to eternal happiness.","zh":"这样你将能进入永恒的幸福之旅","note":"","sourceLineIndex":28},{"id":"dracula-das-musical-07-029","lineIndex":29,"speaker":"","original":"Wer nur ist dieser Meister","ipa":"/vˈeːɾ nˈuːɾ ɪst dˌiːzɜ mˈaɪstɜ/","en":"Who is this master?","zh":"这个主人究竟是谁","note":"","sourceLineIndex":29},{"id":"dracula-das-musical-07-030","lineIndex":30,"speaker":"","original":"kann es sein, das alles sind nur Imaginationen","ipa":"/kˈan ɛs zaɪn das ˈaləs zɪnt nˈuːɾ ˌɪmaɡˌiːnatsjˈoːnən/","en":"It could be, it's all just imagination","zh":"他只存在于您的想象","note":"","sourceLineIndex":30},{"id":"dracula-das-musical-07-031","lineIndex":31,"speaker":"","original":"Was Sie fühlen nennt ein Doktor Halluzinationen","ipa":"/vˈas ziː fˈyːlən nˈɛnt aɪn dˈɔktoːɾ hˌaluːtsˌiːnatsjˈoːnən/","en":"What you feel is what a doctor calls hallucinations","zh":"您所说的全都是幻觉","note":"","sourceLineIndex":31},{"id":"dracula-das-musical-07-032","lineIndex":32,"speaker":"","original":"Und krankhaften Wahn","ipa":"/ʊnt kɾˈaŋkhaftən vˈɑːn/","en":"And morbid delusion","zh":"这是可怕的病态","note":"","sourceLineIndex":32},{"id":"dracula-das-musical-07-033","lineIndex":33,"speaker":"","original":"Ich kann nicht drüber reden","ipa":"/ɪç kˌan nˈɪçt dɾˈyːbɜ rˈeːdən/","en":"I can't talk about it","zh":"我不能告诉您这些","note":"","sourceLineIndex":33},{"id":"dracula-das-musical-07-034","lineIndex":34,"speaker":"","original":"denn Meister will, dass alle die ihn kennen schweigen","ipa":"/dɛn mˈaɪstɜ vɪl das ˈalə diː iːn kˈɛnən ʃvˈaɪɡən/","en":"because Master wants everyone who knows him to be silent","zh":"因为主人希望他的仆人守口如瓶","note":"","sourceLineIndex":34},{"id":"dracula-das-musical-07-035","lineIndex":35,"speaker":"","original":"und sich immerfort bereit für seine Wünsche zeigen","ipa":"/ʊnt zɪç ˈɪmɜfˌɔɾt bərˈaɪt fyːɾ zˌaɪnə vˈʏnʃə tsˈaɪɡən/","en":"and always show yourself ready for your wishes","zh":"并且随时准备达成他的意愿","note":"","sourceLineIndex":35},{"id":"dracula-das-musical-07-036","lineIndex":36,"speaker":"","original":"Ich bin es, ich bin es und bald bin ich frei","ipa":"/ɪç bɪn ˈɛs ɪç bɪn ɛs ʊnt bˈalt bɪn ɪç frˈaɪ/","en":"It's me, it's me and soon I'll be free","zh":"我正是如此 正是如此 而且我将很快得到自由","note":"","sourceLineIndex":36},{"id":"dracula-das-musical-07-037","lineIndex":37,"speaker":"","original":"Bin ich frei","ipa":"/bɪn ɪç frˈaɪ/","en":"Am I free","zh":"得到自由","note":"","sourceLineIndex":37},{"id":"dracula-das-musical-07-038","lineIndex":38,"speaker":"","original":"Am kühlen Grund des Ozeans","ipa":"/am kˈyːlən ɡɾˈʊnt dɛs ˌoːtseːˈɑːns/","en":"At the cool bottom of the ocean","zh":"在寒冷漆黑的海面上","note":"","sourceLineIndex":38},{"id":"dracula-das-musical-07-039","lineIndex":39,"speaker":"","original":"Da liegt die tote Crew","ipa":"/dɑː lˈiːkt diː tˈoːtə kɹˈuː/","en":"There lies the dead crew","zh":"船员尽数倒地死去","note":"","sourceLineIndex":39},{"id":"dracula-das-musical-07-040","lineIndex":40,"speaker":"","original":"Der Captain kämpft allein im Sturm dann schlägt der Meister zu.","ipa":"/dɛɾ kˈaptaɪn kˈɛmpft alˈaɪn ɪm ʃtˈʊɐm dan ʃlˈɛːkt dɛɾ mˈaɪstɜ tsˈuː/","en":"The captain fights alone in the storm then the master strikes.","zh":"船长独自与暴风雨抗争直到主人给他最后一击","note":"","sourceLineIndex":40},{"id":"dracula-das-musical-07-042","lineIndex":41,"speaker":"","original":"De morituri","ipa":"/dˈeː mˈoːriːtˌuːriː/","en":"De morituri","zh":"德莫里图里","note":"","sourceLineIndex":42},{"id":"dracula-das-musical-07-043","lineIndex":42,"speaker":"","original":"De morituri","ipa":"/dˈeː mˈoːriːtˌuːriː/","en":"De morituri","zh":"德莫里图里","note":"","sourceLineIndex":43},{"id":"dracula-das-musical-07-044","lineIndex":43,"speaker":"","original":"De morituri","ipa":"/dˈeː mˈoːriːtˌuːriː/","en":"De morituri","zh":"德莫里图里","note":"","sourceLineIndex":44},{"id":"dracula-das-musical-07-045","lineIndex":44,"speaker":"","original":"De morituri","ipa":"/dˈeː mˈoːriːtˌuːriː/","en":"De morituri","zh":"德莫里图里","note":"","sourceLineIndex":45},{"id":"dracula-das-musical-07-046","lineIndex":45,"speaker":"","original":"De morituri","ipa":"/dˈeː mˈoːriːtˌuːriː/","en":"De morituri","zh":"德莫里图里","note":"","sourceLineIndex":46},{"id":"dracula-das-musical-07-047","lineIndex":46,"speaker":"","original":"De morituri","ipa":"/dˈeː mˈoːriːtˌuːriː/","en":"De morituri","zh":"德莫里图里","note":"","sourceLineIndex":47},{"id":"dracula-das-musical-07-048","lineIndex":47,"speaker":"","original":"De morituri","ipa":"/dˈeː mˈoːriːtˌuːriː/","en":"De morituri","zh":"德莫里图里","note":"","sourceLineIndex":48},{"id":"dracula-das-musical-07-049","lineIndex":48,"speaker":"","original":"De morituri","ipa":"/dˈeː mˈoːriːtˌuːriː/","en":"De morituri","zh":"德莫里图里","note":"","sourceLineIndex":49},{"id":"dracula-das-musical-07-050","lineIndex":49,"speaker":"","original":"Aaaaaaaaaaaaaaaaaaaaaaaaaaah","ipa":"/ˈɑːɑːˌɑːɑːˌɑːɑːˌɑːɑːˌɑːɑːˌɑːɑːˌɑːɑː/","en":"Aaaaaaaaaaaaaaaaaaaaaaaaaah","zh":"啊啊啊啊啊啊啊啊啊啊啊啊啊","note":"","sourceLineIndex":50},{"id":"dracula-das-musical-07-051","lineIndex":50,"speaker":"","original":"Meister, ich hab den Rufen vernommen","ipa":"/mˈaɪstɜ ɪç hˈɑːp deːn rˈuːfən fɛɾnˈɔmən/","en":"Master, I heard the call","zh":"主人 我已经听到了您的呼唤","note":"","sourceLineIndex":51},{"id":"dracula-das-musical-07-052","lineIndex":51,"speaker":"","original":"sei mir als Richter willkommen","ipa":"/zˈaɪ miːɾ als rˈɪçtɜ vɪlkˈɔmən/","en":"I am welcome as a judge","zh":"请您成为我的主宰","note":"","sourceLineIndex":52},{"id":"dracula-das-musical-07-053","lineIndex":52,"speaker":"","original":"guter Geister, der Unsterblichkeit verheißt","ipa":"/ɡˈuːtɜ ɡˈaɪstɜ dɛɾ ˈʊnʃtˌɛɾplɪçkˌaɪt fɛɾhˈaɪst/","en":"good spirits that promise immortality","zh":"仁慈的您允诺给我不朽的生命","note":"","sourceLineIndex":53},{"id":"dracula-das-musical-07-054","lineIndex":53,"speaker":"","original":"Lautlos gehst du durch Wände und Türen","ipa":"/lˈaʊtloːs ɡˈeːst duː dʊɐç vˈɛndə ʊnt tˈyːrən/","en":"You walk silently through walls and doors","zh":"您静静地穿过墙壁和门","note":"","sourceLineIndex":54},{"id":"dracula-das-musical-07-055","lineIndex":54,"speaker":"","original":"kann deine Nähe schon spüren","ipa":"/kˌan dˌaɪnə nˈɛːə ʃˌoːn ʃpˈyːrən/","en":"can already feel your closeness","zh":"我已感觉到您的到来","note":"","sourceLineIndex":55},{"id":"dracula-das-musical-07-056","lineIndex":55,"speaker":"","original":"durch das Fenster, durch das Gitter","ipa":"/dʊɐç das fˈɛnstɜ dʊɐç das ɡˈɪtɜ/","en":"through the window, through the grille","zh":"从窗户外 从栅栏间","note":"","sourceLineIndex":56},{"id":"dracula-das-musical-07-057","lineIndex":56,"speaker":"","original":"durch den Boden, durch den Nebel und der Nacht","ipa":"/dʊɐç deːn bˈoːdən dʊɐç deːn nˈeːbəl ʊnt dɛɾ nˈaxt/","en":"through the ground, through the fog and the night","zh":"从地底下 从浓雾中","note":"","sourceLineIndex":57},{"id":"dracula-das-musical-07-058","lineIndex":57,"speaker":"","original":"wird’s vollbracht","ipa":"/vˈɪɾds fɔlbɾˈaxt/","en":"it will be accomplished","zh":"只属于您的夜晚很快就会降临","note":"","sourceLineIndex":58}],"sourceOrder":7,"displayOrder":6},{"order":8,"id":"08-wie-wahlt-man-aus","title":"Wie wählt man aus?","titleZh":"如何选择？","lines":[{"id":"dracula-das-musical-08-001","lineIndex":1,"speaker":"","original":"Wer soll es sein?","ipa":"/vˈeːɾ zˌɔl ɛs zaɪn/","en":"Who should it be?","zh":"到底选哪个呢？","note":"","sourceLineIndex":1},{"id":"dracula-das-musical-08-002","lineIndex":2,"speaker":"","original":"Einer ist ein Held, einer ein Genie und der dritte schüchtern","ipa":"/ˌaɪnɜ ɪst aɪn hˈɛlt ˌaɪnɜ aɪn ɡənˈiː ʊnt dɛɾ dɾˈɪtə ʃˈʏçtɜn/","en":"One is a hero, one is a genius and the third is shy","zh":"一个是英雄 一个是天才 还有一个害羞得可爱","note":"","sourceLineIndex":2},{"id":"dracula-das-musical-08-003","lineIndex":3,"speaker":"","original":"Neulich beim Wein","ipa":"/nˈɔølɪç baɪm vˈaɪn/","en":"Recently with wine","zh":"刚刚喝酒的时候","note":"","sourceLineIndex":3},{"id":"dracula-das-musical-08-004","lineIndex":4,"speaker":"","original":"War der eine frech und der andre ernst und der dritte nüchtern","ipa":"/vɑːɾ dɛɾ ˌaɪnə frˈɛç ʊnt dɛɾ ˈandɾə ˈɛɾnst ʊnt dɛɾ dɾˈɪtə nˈʏçtɜn/","en":"One was cheeky and the other was serious and the third was sober","zh":"一个放荡不羁 一个一本正经 还有一个平平无奇","note":"","sourceLineIndex":4},{"id":"dracula-das-musical-08-005","lineIndex":5,"speaker":"","original":"Quincy redet wie ein Wüstling","ipa":"/kvˈɪnsiː rˈeːdət viː aɪn vˈʏstlɪŋ/","en":"Quincy talks like a libertine","zh":"昆西讲起话来 像个浪荡子弟","note":"","sourceLineIndex":5},{"id":"dracula-das-musical-08-006","lineIndex":6,"speaker":"","original":"Jack mit männlich sanftem Klang (Tralalaa)","ipa":"/jˈak mɪt mˈɛnlɪç zˈanftəm klˈaŋ tɾˈɑlalˌɑː/","en":"Jack with a gentle male sound (Tralalaa)","zh":"杰克有温柔有磁性的声音","note":"","sourceLineIndex":6},{"id":"dracula-das-musical-08-007","lineIndex":7,"speaker":"","original":"Und wenn Arthur jemals spricht, dann sicher nicht lang","ipa":"/ʊnt vˌɛn aɾtˈuːɾ jˈeːmɑːls ʃpɾˈɪçt dan zˈɪçɜ nˈɪçt lˈaŋ/","en":"And if Arthur ever speaks, it certainly won't be for long","zh":"阿瑟要是说起话来 肯定聊不过两句","note":"","sourceLineIndex":7},{"id":"dracula-das-musical-08-008","lineIndex":8,"speaker":"","original":"Lucy & Mina: Wo zieht man hin?","ipa":"/lˈuːsiː ˈʊnt mˈiːnɑː vˌoː tsˈiːt man hˈɪn/","en":"Lucy & Mina: Where are you moving to?","zh":"露西&米娜：到底要安家何处","note":"","sourceLineIndex":8},{"id":"dracula-das-musical-08-009","lineIndex":9,"speaker":"","original":"In die Steppe raus, in ein Ehrenhaus, in die beste Lage","ipa":"/ɪn diː ʃtˈɛpə rˈaʊs ɪn aɪn ˈeːrənhˌaʊs ɪn diː bˈɛstə lˈɑːɡə/","en":"Out into the steppe, into a house of honor, into the best location","zh":"是去草原 去医院 还是华丽的官邸","note":"","sourceLineIndex":9},{"id":"dracula-das-musical-08-010","lineIndex":10,"speaker":"","original":"Was sagt dein Herz?","ipa":"/vˈas zˈɑːkt daɪn hˈɛɾts/","en":"What does your heart say?","zh":"听听内心的声音","note":"","sourceLineIndex":10},{"id":"dracula-das-musical-08-011","lineIndex":11,"speaker":"","original":"Zieht dich einer an, hast du einen gern?","ipa":"/tsˈiːt dɪç ˌaɪnɜ ˈan hast duː ˌaɪnən ɡˈɛɾn/","en":"Are you attracted to one, do you like one?","zh":"到底哪个你中意","note":"","sourceLineIndex":11},{"id":"dracula-das-musical-08-012","lineIndex":12,"speaker":"","original":"Tja, das ist die Frage","ipa":"/tjˈɑː das ɪst diː frˈɑːɡə/","en":"Well, that's the question","zh":"嗯 这真是个难题","note":"","sourceLineIndex":12},{"id":"dracula-das-musical-08-013","lineIndex":13,"speaker":"","original":"Quincy reitet wilde Pferde","ipa":"/kvˈɪnsiː rˈaɪtət vˈɪldə pfˈeːɾdə/","en":"Quincy rides wild horses","zh":"昆西爱骑烈性的野马","note":"","sourceLineIndex":13},{"id":"dracula-das-musical-08-014","lineIndex":14,"speaker":"","original":"Jack macht Kranke stets gesund","ipa":"/jˈak mˈaxt kɾˈaŋkə ʃtˈeːts ɡəzˈʊnt/","en":"Jack always makes the sick better","zh":"杰克总能妙手回春","note":"","sourceLineIndex":14},{"id":"dracula-das-musical-08-015","lineIndex":15,"speaker":"","original":"Aber Arthur spielt nur immer mit dem Hund","ipa":"/ˌɑːbɜ aɾtˈuːɾ ʃpˈiːlt nˈuːɾ ˈɪmɜ mɪt deːm hˈʊnt/","en":"But Arthur only ever plays with the dog","zh":"至于阿瑟 他只会和狗亲近","note":"","sourceLineIndex":15},{"id":"dracula-das-musical-08-016","lineIndex":16,"speaker":"","original":"Lucy, du bist reizend","ipa":"/lˈuːsiː duː bɪst rˈaɪtsənt/","en":"Lucy, you're lovely","zh":"露西 你是如此美丽","note":"","sourceLineIndex":16},{"id":"dracula-das-musical-08-017","lineIndex":17,"speaker":"","original":"Schwing dich rauf auf Sattel und Pferd","ipa":"/ʃvˈɪŋ dɪç rˈaʊf aʊf zˈatəl ʊnt pfˈeːɾt/","en":"Get on the saddle and horse","zh":"快快跳上马鞍 让我们在一起","note":"","sourceLineIndex":17},{"id":"dracula-das-musical-08-018","lineIndex":18,"speaker":"","original":"Leb an meiner Seite vom Spital, geschätzt und verehrt","ipa":"/lˈeːp an mˌaɪnɜ zˈaɪtə fɔm ʃpiːtˈɑːl ɡəʃˈɛtst ʊnt fɛɾˈeːɾt/","en":"Live by my side from the hospital, valued and adored","zh":"还是和我一起在医院里 高贵又受人尊敬","note":"","sourceLineIndex":18},{"id":"dracula-das-musical-08-019","lineIndex":19,"speaker":"","original":"Eines wollt ich noch sagen, du","ipa":"/ˌaɪnəs vɔlt ɪç nɔx zˈɑːɡən dˈuː/","en":"I wanted to say one more thing, you","zh":"那个…我还想说 你…","note":"","sourceLineIndex":19},{"id":"dracula-das-musical-08-020","lineIndex":20,"speaker":"","original":"Ja nur zu","ipa":"/jˈɑː nˈuːɾ tsˈuː/","en":"Yes, go ahead","zh":"快说呀","note":"","sourceLineIndex":20},{"id":"dracula-das-musical-08-021","lineIndex":21,"speaker":"","original":"Nicht der Rede wert","ipa":"/nˈɪçt dɛɾ rˈeːdə vˈɛɾt/","en":"Not worth mentioning","zh":"算了那不值一提","note":"","sourceLineIndex":21},{"id":"dracula-das-musical-08-022","lineIndex":22,"speaker":"","original":"Hör auf dein Herz","ipa":"/hˈøːɾ aʊf daɪn hˈɛɾts/","en":"Listen to your heart","zh":"听从你内心的声音","note":"","sourceLineIndex":22},{"id":"dracula-das-musical-08-023","lineIndex":23,"speaker":"","original":"Willst du einen Kerl","ipa":"/vɪlst duː ˌaɪnən kˈɛɾl/","en":"Do you want a guy","zh":"你是想跟牛仔","note":"","sourceLineIndex":23},{"id":"dracula-das-musical-08-024","lineIndex":24,"speaker":"","original":"Oder einen Arzt","ipa":"/ˌoːdɜ ˌaɪnən ˈaɾtst/","en":"Or a doctor","zh":"想跟医生","note":"","sourceLineIndex":24},{"id":"dracula-das-musical-08-025","lineIndex":25,"speaker":"","original":"Oder was für’s Leben?","ipa":"/ˌoːdɜ vˈas fˈyːɾs lˈeːbən/","en":"Or what for life?","zh":"还是想跟踏实过日子的人一起","note":"","sourceLineIndex":25},{"id":"dracula-das-musical-08-026","lineIndex":26,"speaker":"","original":"Wer soll es sein?","ipa":"/vˈeːɾ zˌɔl ɛs zaɪn/","en":"Who should it be?","zh":"到底选哪个","note":"","sourceLineIndex":26},{"id":"dracula-das-musical-08-027","lineIndex":27,"speaker":"","original":"Ranger mit Gewehr, Akademiker","ipa":"/rˈaŋɜ mɪt ɡəvˈeːɾ ˈɑkadˌeːmɪkɜ/","en":"Ranger with rifle, academic","zh":"是带枪的骑行侠 还是选个学问人","note":"","sourceLineIndex":27},{"id":"dracula-das-musical-08-028","lineIndex":28,"speaker":"","original":"Der mit dem Vermögen","ipa":"/dɛɾ mɪt deːm fɛɾmˈøːɡən/","en":"The one with the fortune","zh":"反正他们都很富裕","note":"","sourceLineIndex":28},{"id":"dracula-das-musical-08-029","lineIndex":29,"speaker":"","original":"Arthur ist kein großer Denker","ipa":"/aɾtˈuːɾ ɪst kˈaɪn ɡɾˈoːsɜ dˈɛŋkɜ/","en":"Arthur isn't a great thinker","zh":"阿瑟不是伟大的思想家","note":"","sourceLineIndex":29},{"id":"dracula-das-musical-08-030","lineIndex":30,"speaker":"","original":"Kein Adonis, kein Galant","ipa":"/kˈaɪn ˈɑdoːnˌɪs kˈaɪn ɡalˈant/","en":"No Adonis, no Gallant","zh":"他不是风流美少年 也不懂如何献殷勤","note":"","sourceLineIndex":30},{"id":"dracula-das-musical-08-031","lineIndex":31,"speaker":"","original":"Doch vielleicht ist grade er der richtige Mann","ipa":"/dɔx fɪlˈaɪçt ɪst ɡɾˈɑːdə ɛɾ dɛɾ rˈɪçtɪɡə mˈan/","en":"But maybe he is the right man","zh":"可正因如此 他可能就是我要找的那个人","note":"","sourceLineIndex":31},{"id":"dracula-das-musical-08-032","lineIndex":32,"speaker":"","original":"Ich war verschossen in ihn schon als Mädchen","ipa":"/ɪç vɑːɾ fɛɾʃˈɔsən ɪn iːn ʃˌoːn als mˈɛːdçən/","en":"I had a crush on him even as a girl","zh":"早在少女时候 我就对他倾心","note":"","sourceLineIndex":32},{"id":"dracula-das-musical-08-033","lineIndex":33,"speaker":"","original":"Wenn’s nur Strohfeuer war, wär es kalt","ipa":"/vˈɛns nˈuːɾ ʃtɾˈoːfɔøɜ vɑːɾ vˈɛːɾ ɛs kˈalt/","en":"If it was just a flash in the pan, it would be cold","zh":"爱情的火花短暂容易熄","note":"","sourceLineIndex":33},{"id":"dracula-das-musical-08-034","lineIndex":34,"speaker":"","original":"Er ist gütig, solide und still","ipa":"/ɛɾ ɪst ɡˈyːtɪç zoːlˈiːdə ʊnt ʃtˈɪl/","en":"He is kind, solid and quiet","zh":"他安静稳重又可靠","note":"","sourceLineIndex":34},{"id":"dracula-das-musical-08-035","lineIndex":35,"speaker":"","original":"Heirat bedeutet mit ihm wirst du alt","ipa":"/haɪrˈɑːt bədˈɔøtət mɪt iːm vˌɪɾst duː ˈalt/","en":"Marriage means you'll grow old with him","zh":"可婚姻意味着携手到老","note":"","sourceLineIndex":35},{"id":"dracula-das-musical-08-036","lineIndex":36,"speaker":"","original":"Er war und bleibt meine heimliche Liebe","ipa":"/ɛɾ vɑːɾ ʊnt blˈaɪpt mˌaɪnə hˈaɪmlɪçə lˈiːbə/","en":"He was and remains my secret love","zh":"他是我的挚爱 一直藏在心底","note":"","sourceLineIndex":36},{"id":"dracula-das-musical-08-037","lineIndex":37,"speaker":"","original":"Wenn er das ist dann verrat es ihm bald","ipa":"/vˌɛn ɛɾ das ɪst dan fɛɾrˈɑːt ɛs iːm bˈalt/","en":"If that's him then tell him soon","zh":"既然如此 那就快快向他表白心意","note":"","sourceLineIndex":37},{"id":"dracula-das-musical-08-038","lineIndex":38,"speaker":"","original":"Er ist der einzige Mann den ich mag","ipa":"/ɛɾ ɪst dɛɾ ˈaɪntsɪɡə mˈan deːn ɪç mˈɑːk/","en":"He's the only man I like","zh":"他就是我心意的那个男子","note":"","sourceLineIndex":38},{"id":"dracula-das-musical-08-039","lineIndex":39,"speaker":"","original":"Quincy, Jack und Arthur: Wie sieht es aus","ipa":"/kvˈɪnsiː jˈak ʊnt aɾtˈuːɾ viː zˈiːt ɛs ˈaʊs/","en":"Quincy, Jack and Arthur: What does it look like?","zh":"昆西&杰克&阿瑟：选得怎么样了","note":"","sourceLineIndex":39},{"id":"dracula-das-musical-08-040","lineIndex":40,"speaker":"","original":"Gibst du mir die Hand","ipa":"/ɡˈiːpst duː miːɾ diː hˈant/","en":"Will you shake my hand","zh":"给我你的手","note":"","sourceLineIndex":40},{"id":"dracula-das-musical-08-041","lineIndex":41,"speaker":"","original":"Folgst du dem Verstand","ipa":"/fˈɔlkst duː deːm fɛɾʃtˈant/","en":"Are you following reason?","zh":"再考虑考虑","note":"","sourceLineIndex":41},{"id":"dracula-das-musical-08-042","lineIndex":42,"speaker":"","original":"Darf man etwa hoffen","ipa":"/dˈaɾf man ˌɛtvɑː hˈɔfən/","en":"One can hope so","zh":"我还有希望吗","note":"","sourceLineIndex":42},{"id":"dracula-das-musical-08-043","lineIndex":43,"speaker":"","original":"Ehrlich heraus, ihr seid alle lieb","ipa":"/ˈeːɾlɪç hɛrˈaʊs iːɾ zˈaɪt ˈalə lˈiːp/","en":"Honestly, you're all lovely","zh":"你们都很优秀","note":"","sourceLineIndex":43},{"id":"dracula-das-musical-08-044","lineIndex":44,"speaker":"","original":"Doch ich habe längst meine Wahl getroffen","ipa":"/dɔx ɪç hɑːbə lˈɛŋst mˌaɪnə vˈɑːl ɡətɾˈɔfən/","en":"But I made my choice long ago","zh":"可我和我的真爱相识已久","note":"","sourceLineIndex":44},{"id":"dracula-das-musical-08-045","lineIndex":45,"speaker":"","original":"Quincy schoss nur knapp daneben","ipa":"/kvˈɪnsiː ʃˈɔs nˈuːɾ knˈap dɑːnˈeːbən/","en":"Quincy shot just wide","zh":"昆西磨刀霍霍","note":"","sourceLineIndex":45},{"id":"dracula-das-musical-08-046","lineIndex":46,"speaker":"","original":"Jack erträgt es wie ein Mann","ipa":"/jˈak ɛɾtɾˈɛːkt ɛs viː aɪn mˈan/","en":"Jack takes it like a man","zh":"杰克沉默不语","note":"","sourceLineIndex":46},{"id":"dracula-das-musical-08-047","lineIndex":47,"speaker":"","original":"Während Arthur gewann noch bevor er begann","ipa":"/vˌɛːrənt aɾtˈuːɾ ɡəvˈan nɔx bəfˈoːɾ ɛɾ bəɡˈan/","en":"While Arthur won before he even started","zh":"傻傻阿瑟赢了还不明就里","note":"","sourceLineIndex":47},{"id":"dracula-das-musical-08-048","lineIndex":48,"speaker":"","original":"Wahre Liebe kennt nie eine zweite Wahl","ipa":"/vˈɑːrə lˈiːbə kˈɛnt nˈiː ˌaɪnə tsvˈaɪtə vˈɑːl/","en":"True love never knows a second choice","zh":"真爱不容置疑","note":"","sourceLineIndex":48},{"id":"dracula-das-musical-08-049","lineIndex":49,"speaker":"","original":"Wahre Liebe ist immer ein Einzelfall","ipa":"/vˈɑːrə lˈiːbə ɪst ˈɪmɜ aɪn ˈaɪntsˌɛlfal/","en":"True love is always an individual case","zh":"真爱无例可循","note":"","sourceLineIndex":49},{"id":"dracula-das-musical-08-050","lineIndex":50,"speaker":"","original":"Da hilft kein Gram, kein Getu‘","ipa":"/dɑː hˈɪlft kˈaɪn ɡɾˈɑːm kˈaɪn ɡətˈuː/","en":"No amount of grief or fuss helps","zh":"任何悲伤 装模作样","note":"","sourceLineIndex":50},{"id":"dracula-das-musical-08-051","lineIndex":51,"speaker":"","original":"Keine Hoffnung und keine Fragen mehr","ipa":"/kˈaɪnə hˈɔfnʊŋ ʊnt kˈaɪnə frˈɑːɡən mˈeːɾ/","en":"No hope and no more questions","zh":"任何幻想 问题 都毫无意义","note":"","sourceLineIndex":51},{"id":"dracula-das-musical-08-052","lineIndex":52,"speaker":"","original":"Zwecklos ist jede Gegenwehr","ipa":"/tsvˈɛkloːs ɪst jˈeːdə ɡeːɡənvˈeːɾ/","en":"Any resistance is pointless","zh":"任何反抗都无济于事","note":"","sourceLineIndex":52},{"id":"dracula-das-musical-08-053","lineIndex":53,"speaker":"","original":"Denn zu der wahren Liebe gehört es dazu","ipa":"/dɛn tsuː dɛɾ vˈɑːrən lˈiːbə ɡəhˈœɾt ɛs dɑːtsˈuː/","en":"Because it is part of true love","zh":"因为真爱就是如此","note":"","sourceLineIndex":53},{"id":"dracula-das-musical-08-054","lineIndex":54,"speaker":"","original":"Nicht er, nicht er, du!","ipa":"/nˈɪçt ɛɾ nˈɪçt ɛɾ dˈuː/","en":"Not him, not him, you!","zh":"不是他 也不是他 是你啦","note":"","sourceLineIndex":54}],"sourceOrder":8,"displayOrder":7},{"order":9,"id":"09-nebel-und-nacht","title":"Nebel und Nacht","titleZh":"雾和夜","lines":[{"id":"dracula-das-musical-09-001","lineIndex":1,"speaker":"","original":"Das Mondlicht trug mich","ipa":"/das mˈɔndlɪçt tɾˈuːk mɪç/","en":"The moonlight carried me","zh":"我在月光的笼罩下","note":"","sourceLineIndex":1},{"id":"dracula-das-musical-09-002","lineIndex":2,"speaker":"","original":"wie körperlos ans Meer","ipa":"/viː kˈœɾpɜlˌoːs ans mˈeːɾ/","en":"as if disembodied at the sea","zh":"轻盈地去向海边","note":"","sourceLineIndex":2},{"id":"dracula-das-musical-09-003","lineIndex":3,"speaker":"","original":"Ich ertrank in dunklen Wellen","ipa":"/ɪç ɛɾtɾˈaŋk ɪn dˈʊŋklən vˈɛlən/","en":"I drowned in dark waves","zh":"我为这些海波所吞噬","note":"","sourceLineIndex":3},{"id":"dracula-das-musical-09-004","lineIndex":4,"speaker":"","original":"mehr schwebend als schwer","ipa":"/mˈeːɾ ʃvˈeːbənt als ʃvˈeːɾ/","en":"more floating than heavy","zh":"摇曳着漂浮着","note":"","sourceLineIndex":4},{"id":"dracula-das-musical-09-005","lineIndex":5,"speaker":"","original":"berauscht von seinem Blick","ipa":"/bərˈaʊʃt fɔn zˌaɪnəm blˈɪk/","en":"intoxicated by his gaze","zh":"我沉浸在他的目光中","note":"","sourceLineIndex":5},{"id":"dracula-das-musical-09-006","lineIndex":6,"speaker":"","original":"dem heißen Blick einer hypnotischen Macht","ipa":"/deːm hˈaɪsən blˈɪk ˌaɪnɜ hʏpnˈoːtɪʃən mˈaxt/","en":"the hot gaze of a hypnotic power","zh":"那炙热且迷恋的目光","note":"","sourceLineIndex":6},{"id":"dracula-das-musical-09-007","lineIndex":7,"speaker":"","original":"verging ich im Nebel der Nacht","ipa":"/fɛɾɡˈɪŋ ɪç ɪm nˈeːbəl dɛɾ nˈaxt/","en":"I disappeared in the fog of the night","zh":"我消逝在夜的雾中","note":"","sourceLineIndex":7},{"id":"dracula-das-musical-09-008","lineIndex":8,"speaker":"","original":"Die Hunde heulten","ipa":"/diː hˈʊndə hˈɔøltən/","en":"The dogs howled","zh":"传来狼的长嚎","note":"","sourceLineIndex":8},{"id":"dracula-das-musical-09-009","lineIndex":9,"speaker":"","original":"vielleicht auch nur zum Schein","ipa":"/fɪlˈaɪçt ˌaʊx nˈuːɾ tsʊm ʃˈaɪn/","en":"maybe just for appearances","zh":"也许只是表象","note":"","sourceLineIndex":9},{"id":"dracula-das-musical-09-010","lineIndex":10,"speaker":"","original":"Als er plötzlich neben mir stand da wollte ich schreien.","ipa":"/als ɛɾ plˈœtslɪç nˌeːbən miːɾ ʃtˈant dɑː vɔltə ɪç ʃrˈaɪən/","en":"When he suddenly stood next to me I wanted to scream.","zh":"他倏尔出现在身旁我想尖叫","note":"","sourceLineIndex":10},{"id":"dracula-das-musical-09-012","lineIndex":11,"speaker":"","original":"Die stimme war mir starr","ipa":"/diː ʃtˈɪmə vɑːɾ miːɾ ʃtˈaɾ/","en":"The voice was rigid to me","zh":"但如鲠在喉","note":"","sourceLineIndex":12},{"id":"dracula-das-musical-09-013","lineIndex":12,"speaker":"","original":"ich war fürwahr um meinen Willen gebracht","ipa":"/ɪç vɑːɾ fˈʏɾvɑːɾ ʊm mˌaɪnən vˈɪlən ɡəbɾˈaxt/","en":"I was truly deprived of my will","zh":"似乎一切有生命的东西","note":"","sourceLineIndex":13},{"id":"dracula-das-musical-09-014","lineIndex":13,"speaker":"","original":"und glitt in den Nebel der Nacht","ipa":"/ʊnt ɡlˈɪt ɪn deːn nˈeːbəl dɛɾ nˈaxt/","en":"and slipped into the mist of the night","zh":"都沉没在雾中","note":"","sourceLineIndex":14},{"id":"dracula-das-musical-09-015","lineIndex":14,"speaker":"","original":"ein Singen war's für mein Gefühl","ipa":"/aɪn zˈɪŋən vˈɑɾs fyːɾ maɪn ɡəfˈyːl/","en":"it was a singing for my feeling","zh":"我听见他在耳边呢喃","note":"","sourceLineIndex":15},{"id":"dracula-das-musical-09-016","lineIndex":15,"speaker":"","original":"als ich ihn sprechen hörte","ipa":"/als ɪç iːn ʃpɾˈɛçən hˈœɾtə/","en":"when I heard him speak","zh":"轻柔如歌声","note":"","sourceLineIndex":16},{"id":"dracula-das-musical-09-017","lineIndex":16,"speaker":"","original":"zart wie ein sanfter Kavalier","ipa":"/tsˈaɾt viː aɪn zˈanftɜ kˌɑvalˈiːɾ/","en":"delicate like a gentle cavalier","zh":"他是如此温文尔雅","note":"","sourceLineIndex":17},{"id":"dracula-das-musical-09-018","lineIndex":17,"speaker":"","original":"die Worte waren so sonderbar","ipa":"/diː vˈɔɾtə vɑːrən zoː zˈɔndɜbˌɑːɾ/","en":"the words were so strange","zh":"那些词句如此美妙","note":"","sourceLineIndex":18},{"id":"dracula-das-musical-09-019","lineIndex":18,"speaker":"","original":"es schwanden mir die Sinne","ipa":"/ɛs ʃvˈandən miːɾ diː zˈɪnə/","en":"I lost my senses","zh":"我沉迷在蜜语中","note":"","sourceLineIndex":19},{"id":"dracula-das-musical-09-020","lineIndex":19,"speaker":"","original":"und dann sprach er nur noch von dir","ipa":"/ʊnt dan ʃpɾˈɑːx ɛɾ nˈuːɾ nɔx fɔn dˈiːɾ/","en":"and then he only spoke about you","zh":"每字每句都是你","note":"","sourceLineIndex":20},{"id":"dracula-das-musical-09-021","lineIndex":20,"speaker":"","original":"es klang als wär er schon lang mit dir bekannt hauchte lächelnd deinen Namen von Zauber gebannt.","ipa":"/ɛs klˈaŋ als vˈɛːɾ ɛɾ ʃˌoːn lˈaŋ mɪt diːɾ bəkˈant hˈaʊxtə lˈɛçəlnt dˌaɪnən nˈɑːmən fɔn tsˈaʊbɜ ɡəbˈant/","en":"it sounded like he had known you for a long time breathed your name with a smile spellbound.","zh":"我们仿佛相识已久他微笑，他低语你的名像魔法","note":"","sourceLineIndex":21},{"id":"dracula-das-musical-09-024","lineIndex":21,"speaker":"","original":"Aus Angst wurde verlangen","ipa":"/ˌaʊs ˈaŋst vˌʊɐdə fɛɾlˈaŋən/","en":"Fear became desire","zh":"我的恐惧变为渴望","note":"","sourceLineIndex":24},{"id":"dracula-das-musical-09-025","lineIndex":22,"speaker":"","original":"und mein Bangen war zum Schweigen gebracht","ipa":"/ʊnt maɪn bˈaŋən vɑːɾ tsʊm ʃvˈaɪɡən ɡəbɾˈaxt/","en":"and my fear was silenced","zh":"我跨过沉沦的一切","note":"","sourceLineIndex":25},{"id":"dracula-das-musical-09-026","lineIndex":23,"speaker":"","original":"Sein Kuss war wie Flammen","ipa":"/zaɪn kˈʊs vɑːɾ viː flˈamən/","en":"His kiss was like flames","zh":"燃烧在他的吻里","note":"","sourceLineIndex":26},{"id":"dracula-das-musical-09-027","lineIndex":24,"speaker":"","original":"wir lagen zusammen","ipa":"/viːɾ lˈɑːɡən tsuːzˈamən/","en":"we lay together","zh":"我们依偎","note":"","sourceLineIndex":27},{"id":"dracula-das-musical-09-028","lineIndex":25,"speaker":"","original":"im Feuer, bei Nebel und Nacht","ipa":"/ɪm fˈɔøɜ baɪ nˈeːbəl ʊnt nˈaxt/","en":"in fire, in fog and night","zh":"在夜下，在雾中，在火里","note":"","sourceLineIndex":28}],"sourceOrder":9,"displayOrder":8},{"order":10,"id":"10-nebel-und-nacht-reprise","title":"Nebel und Nacht - Reprise","titleZh":"雾与夜（重唱）","lines":[{"id":"dracula-das-musical-10-001","lineIndex":1,"speaker":"","original":"Die eine fügt sich","ipa":"/diː ˌaɪnə fˈyːkt zɪç/","en":"One complies","zh":"那个孩子","note":"","sourceLineIndex":1},{"id":"dracula-das-musical-10-002","lineIndex":2,"speaker":"","original":"ist willenlos und leer","ipa":"/ɪst vˈɪlənlˌoːs ʊnt lˈeːɾ/","en":"is willless and empty","zh":"优柔寡断又空虚","note":"","sourceLineIndex":2},{"id":"dracula-das-musical-10-003","lineIndex":3,"speaker":"","original":"Führt mich in den Arm der andern","ipa":"/fˈyːɾt mɪç ɪn deːn ˈaɾm dɛɾ ˈandɜn/","en":"Lead me into the arms of others","zh":"她会引我去你身边","note":"","sourceLineIndex":3},{"id":"dracula-das-musical-10-004","lineIndex":4,"speaker":"","original":"mein Ziel, mein Begehr","ipa":"/maɪn tsˈiːl maɪn bəɡˈeːɾ/","en":"my goal, my desire","zh":"你才是 我真正渴求的目标","note":"","sourceLineIndex":4},{"id":"dracula-das-musical-10-005","lineIndex":5,"speaker":"","original":"Ihr blut zieht mich zu ihr","ipa":"/iːɾ blˈuːt tsˈiːt mɪç tsuː iːɾ/","en":"Her blood draws me to her","zh":"她的血液吸引了我","note":"","sourceLineIndex":5},{"id":"dracula-das-musical-10-006","lineIndex":6,"speaker":"","original":"es hat die Gier nach neuem Leben entfacht","ipa":"/ɛs hat diː ɡˈiːɾ nɑːx nˈɔøəm lˈeːbən ɛntfˈaxt/","en":"it has ignited the hunger for new life","zh":"点燃了我对新生的渴望","note":"","sourceLineIndex":6},{"id":"dracula-das-musical-10-007","lineIndex":7,"speaker":"","original":"bald fällt sie im Nebel der Nacht","ipa":"/bˈalt fˈɛlt ziː ɪm nˈeːbəl dɛɾ nˈaxt/","en":"soon it falls in the mist of the night","zh":"她将迷失在长夜的谜雾中","note":"","sourceLineIndex":7}],"sourceOrder":10,"displayOrder":9},{"order":11,"id":"11-ein-lebenstraum-ich-leb-nur-weil-es-dich-gibt-whitby-bay-reprise","title":"Ein Lebenstraum / Ich leb’ nur, weil es dich gibt / Whitby Bay - Reprise","titleZh":"一生的梦想／我只因你而活／《惠特比湾》重唱","lines":[{"id":"dracula-das-musical-11-001","lineIndex":1,"speaker":"","original":"Mein großter Traum","ipa":"/maɪn ɡɾˈoːstɜ tɾˈaʊm/","en":"My biggest dream","zh":"我最大的梦想","note":"","sourceLineIndex":1},{"id":"dracula-das-musical-11-002","lineIndex":2,"speaker":"","original":"Soll heute in Erfüllung gehn","ipa":"/zˌɔl hˈɔøtə ɪn ɛɾfˈʏlʊŋ ɡˈeːn/","en":"Should come true today","zh":"今天就要实现","note":"","sourceLineIndex":2},{"id":"dracula-das-musical-11-003","lineIndex":3,"speaker":"","original":"Und doch, und doch","ipa":"/ʊnt dˈɔx ʊnt dˈɔx/","en":"And yet, and yet","zh":"但是啊","note":"","sourceLineIndex":3},{"id":"dracula-das-musical-11-004","lineIndex":4,"speaker":"","original":"Verhallt in mir die Stimme noch","ipa":"/fɛɾhˈalt ɪn miːɾ diː ʃtˈɪmə nɔx/","en":"The voice still fades away in me","zh":"我心里的声音越来越小","note":"","sourceLineIndex":4},{"id":"dracula-das-musical-11-005","lineIndex":5,"speaker":"","original":"Nur weg von hier","ipa":"/nˈuːɾ vˈɛk fɔn hˈiːɾ/","en":"Just get away from here","zh":"离这里越来越远","note":"","sourceLineIndex":5},{"id":"dracula-das-musical-11-006","lineIndex":6,"speaker":"","original":"Ein braver Mann","ipa":"/aɪn bɾˈɑːvɜ mˈan/","en":"A good man","zh":"一个勇敢善良的人","note":"","sourceLineIndex":6},{"id":"dracula-das-musical-11-007","lineIndex":7,"speaker":"","original":"Ich lieb ihn so, wie er mich liebt","ipa":"/ɪç lˈiːp iːn zˈoː viː ɛɾ mɪç lˈiːpt/","en":"I love him the way he loves me","zh":"我和他彼此相爱着","note":"","sourceLineIndex":7},{"id":"dracula-das-musical-11-008","lineIndex":8,"speaker":"","original":"Doch nein, doch nein","ipa":"/dɔx nˈaɪn dɔx nˈaɪn/","en":"But no, but no","zh":"但是啊，不，不","note":"","sourceLineIndex":8},{"id":"dracula-das-musical-11-009","lineIndex":9,"speaker":"","original":"Der Traum zerbricht","ipa":"/dɛɾ tɾˈaʊm tsɛɾbɾˈɪçt/","en":"The dream shatters","zh":"梦想破碎了","note":"","sourceLineIndex":9},{"id":"dracula-das-musical-11-010","lineIndex":10,"speaker":"","original":"Statt hellem Schein, nur dumpfes Licht","ipa":"/ʃtˈat hˈɛləm ʃˈaɪn nˈuːɾ dˈʊmpfəs lˈɪçt/","en":"Instead of bright light, only dull light","zh":"亮光熄灭了，只剩下黯淡","note":"","sourceLineIndex":10},{"id":"dracula-das-musical-11-011","lineIndex":11,"speaker":"","original":"Ich bin da, weil du mich liebst","ipa":"/ɪç bɪn dˈɑː vˌaɪl duː mɪç lˈiːpst/","en":"I'm here because you love me","zh":"我来到这里是因为你","note":"","sourceLineIndex":11},{"id":"dracula-das-musical-11-012","lineIndex":12,"speaker":"","original":"Denk daran in dieser Stunde","ipa":"/dˈɛŋk dɑːrˈan ɪn dˌiːzɜ ʃtˈʊndə/","en":"Remember that in this hour","zh":"在此刻仔细思索一下","note":"","sourceLineIndex":12},{"id":"dracula-das-musical-11-013","lineIndex":13,"speaker":"","original":"Eh du eins wirst mit dem Mann","ipa":"/ˈeː duː aɪns vˌɪɾst mɪt deːm mˈan/","en":"Before you become one with the man","zh":"在你和那个人合二为一之前","note":"","sourceLineIndex":13},{"id":"dracula-das-musical-11-014","lineIndex":14,"speaker":"","original":"Der dich nie für sich gewann","ipa":"/dɛɾ dɪç nˈiː fyːɾ zɪç ɡəvˈan/","en":"Who never won you over","zh":"那个人永远无法赢得你的心","note":"","sourceLineIndex":14},{"id":"dracula-das-musical-11-015","lineIndex":15,"speaker":"","original":"Er wird die Tiefe deiner Seele nie verstehn","ipa":"/ɛɾ vˌɪɾt diː tˈiːfə dˌaɪnɜ zˈeːlə nˈiː fɛɾʃtˈeːn/","en":"He will never understand the depth of your soul","zh":"他永远无法理解你的灵魂","note":"","sourceLineIndex":15},{"id":"dracula-das-musical-11-016","lineIndex":16,"speaker":"","original":"Nie selbst erreichen","ipa":"/nˈiː zˈɛlpst ɛɾrˈaɪçən/","en":"Never reach yourself","zh":"他甚至不能触及一鳞半爪","note":"","sourceLineIndex":16},{"id":"dracula-das-musical-11-017","lineIndex":17,"speaker":"","original":"Ich bin da, weil du mich liebst","ipa":"/ɪç bɪn dˈɑː vˌaɪl duː mɪç lˈiːpst/","en":"I'm here because you love me","zh":"我来到这里是因为你","note":"","sourceLineIndex":17},{"id":"dracula-das-musical-11-018","lineIndex":18,"speaker":"","original":"Nur für dich bin ich am Leben","ipa":"/nˈuːɾ fyːɾ dɪç bɪn ɪç am lˈeːbən/","en":"I'm only alive for you","zh":"我只为你而活","note":"","sourceLineIndex":18},{"id":"dracula-das-musical-11-019","lineIndex":19,"speaker":"","original":"Jede Sehnsucht tief in dir","ipa":"/jˈeːdə zˈeːnzuːxt tˈiːf ɪn dˈiːɾ/","en":"Every longing deep within you","zh":"你内心深处的任何渴望","note":"","sourceLineIndex":19},{"id":"dracula-das-musical-11-020","lineIndex":20,"speaker":"","original":"Findest du allein in mir","ipa":"/fˈɪndəst duː alˈaɪn ɪn mˈiːɾ/","en":"You find it alone in me","zh":"都只能在我这里寻求到","note":"","sourceLineIndex":20},{"id":"dracula-das-musical-11-021","lineIndex":21,"speaker":"","original":"Wirf dich nicht weg","ipa":"/vˈɪɾf dɪç nˈɪçt vˈɛk/","en":"Don't throw yourself away","zh":"不要把自己献给","note":"","sourceLineIndex":21},{"id":"dracula-das-musical-11-022","lineIndex":22,"speaker":"","original":"An diesen ahnungslosen Mann","ipa":"/an dˌiːzən ˈɑːnʊŋslˌoːzən mˈan/","en":"To this clueless man","zh":"这个幼稚无知的男人","note":"","sourceLineIndex":22},{"id":"dracula-das-musical-11-023","lineIndex":23,"speaker":"","original":"Und seinesgleichen","ipa":"/ʊnt zˈaɪnɛsɡlˌaɪçən/","en":"And his kind","zh":"和他的同类们","note":"","sourceLineIndex":23},{"id":"dracula-das-musical-11-024","lineIndex":24,"speaker":"","original":"Du hast mich ohne es zu wollen","ipa":"/duː hast mɪç ˈoːnə ɛs tsuː vɔlən/","en":"You have me without wanting it","zh":"在无形之中你使我","note":"","sourceLineIndex":24},{"id":"dracula-das-musical-11-025","lineIndex":25,"speaker":"","original":"Zu einem anderen gemacht","ipa":"/tsuː ˌaɪnəm ˈandərən ɡəmˈaxt/","en":"Made into another","zh":"变为一个崭新的人","note":"","sourceLineIndex":25},{"id":"dracula-das-musical-11-026","lineIndex":26,"speaker":"","original":"Wie sehr dein Wesen mich betört","ipa":"/viː zˈeːɾ daɪn vˈeːzən mɪç bətˈœɾt/","en":"How much your nature beguiles me","zh":"你的灵魂是如此吸引着我","note":"","sourceLineIndex":26},{"id":"dracula-das-musical-11-027","lineIndex":27,"speaker":"","original":"Das hätt‘ ich nie gedacht","ipa":"/das hˈɛt ɪç nˈiː ɡədˈaxt/","en":"I would never have thought that","zh":"这是我从来都没有想到的","note":"","sourceLineIndex":27},{"id":"dracula-das-musical-11-028","lineIndex":28,"speaker":"","original":"Ich bin nur da, weil du mich liebst","ipa":"/ɪç bɪn nˈuːɾ dˈɑː vˌaɪl duː mɪç lˈiːpst/","en":"I'm only here because you love me","zh":"我来到这里只是因为你","note":"","sourceLineIndex":28},{"id":"dracula-das-musical-11-029","lineIndex":29,"speaker":"","original":"Mit dir gewinn ich jede Schlacht","ipa":"/mɪt diːɾ ɡəvˈɪn ɪç jˈeːdə ʃlˈaxt/","en":"With you I win every battle","zh":"和你一起我能克服所有障碍","note":"","sourceLineIndex":29},{"id":"dracula-das-musical-11-030","lineIndex":30,"speaker":"","original":"Vertrau mir bis ans Ende aller Zeit","ipa":"/fɛɾtɾˈaʊ miːɾ bɪs ans ˈɛndə ˈalɜ tsˈaɪt/","en":"Trust me until the end of time","zh":"让我们一起到时间的尽头","note":"","sourceLineIndex":30},{"id":"dracula-das-musical-11-031","lineIndex":31,"speaker":"","original":"Wir gehen gemeinsam durch die Nacht","ipa":"/viːɾ ɡˈeːən ɡəmˈaɪnzɑːm dʊɐç diː nˈaxt/","en":"We walk through the night together","zh":"让我们一起穿越黑夜","note":"","sourceLineIndex":31},{"id":"dracula-das-musical-11-032","lineIndex":32,"speaker":"","original":"Wie kann es nur sein","ipa":"/viː kˌan ɛs nˈuːɾ zaɪn/","en":"How can it be?","zh":"为什么会这样呢","note":"","sourceLineIndex":32},{"id":"dracula-das-musical-11-033","lineIndex":33,"speaker":"","original":"Dass ich so fühle wie ich fühl","ipa":"/das ɪç zoː fˈyːlə viː ɪç fˈyːl/","en":"That I feel the way I feel","zh":"我感受到了什么","note":"","sourceLineIndex":33},{"id":"dracula-das-musical-11-034","lineIndex":34,"speaker":"","original":"Wie kann ich nur schwanken","ipa":"/viː kˌan ɪç nˈuːɾ ʃvˈaŋkən/","en":"How can I waver?","zh":"为什么我会犹豫","note":"","sourceLineIndex":34},{"id":"dracula-das-musical-11-035","lineIndex":35,"speaker":"","original":"Zwischen Liebe und Kalkül","ipa":"/tsvˈɪʃən lˈiːbə ʊnt kˈalkyːl/","en":"Between love and calculation","zh":"在爱和理性之间","note":"","sourceLineIndex":35},{"id":"dracula-das-musical-11-036","lineIndex":36,"speaker":"","original":"Etwas in mir sehnt sich nach","ipa":"/ˈɛtvɑːs ɪn miːɾ zˈeːnt zɪç nˈɑːx/","en":"Something inside me yearns","zh":"我心里的一部分渴望着","note":"","sourceLineIndex":36},{"id":"dracula-das-musical-11-037","lineIndex":37,"speaker":"","original":"Der Treue die ich schwor","ipa":"/dɛɾ tɾˈɔøə diː ɪç ʃvˈoːɾ/","en":"The loyalty I swore","zh":"我许下的忠诚诺言","note":"","sourceLineIndex":37},{"id":"dracula-das-musical-11-038","lineIndex":38,"speaker":"","original":"Etwas in mir fürchtet sich davor","ipa":"/ˈɛtvɑːs ɪn miːɾ fˈʏɾçtət zɪç dɑːfˈoːɾ/","en":"Something inside me is afraid of it","zh":"另一部分却害怕着它","note":"","sourceLineIndex":38},{"id":"dracula-das-musical-11-039","lineIndex":39,"speaker":"","original":"Mein größter Traum","ipa":"/maɪn ɡɾˈœstɜ tɾˈaʊm/","en":"My biggest dream","zh":"我最大的梦想","note":"","sourceLineIndex":39},{"id":"dracula-das-musical-11-040","lineIndex":40,"speaker":"","original":"Einsam durch die Nacht","ipa":"/ˈaɪnzˌɑːm dʊɐç diː nˈaxt/","en":"Lonely through the night","zh":"漫漫长夜）","note":"","sourceLineIndex":40},{"id":"dracula-das-musical-11-041","lineIndex":41,"speaker":"","original":"Soll heute in Erfüllung gehen","ipa":"/zˌɔl hˈɔøtə ɪn ɛɾfˈʏlʊŋ ɡˈeːən/","en":"Should come true today","zh":"今天就要实现","note":"","sourceLineIndex":41},{"id":"dracula-das-musical-11-042","lineIndex":42,"speaker":"","original":"Und doch und doch","ipa":"/ʊnt dɔx ʊnt dˈɔx/","en":"And yet and yet","zh":"但是啊","note":"","sourceLineIndex":42},{"id":"dracula-das-musical-11-043","lineIndex":43,"speaker":"","original":"(Trägt der Wind)","ipa":"/tɾˈɛːkt dɛɾ vˈɪnt/","en":"(The wind carries)","zh":"（阴风阵阵）","note":"","sourceLineIndex":43},{"id":"dracula-das-musical-11-044","lineIndex":44,"speaker":"","original":"Ich merk an mir","ipa":"/ɪç mˈɛɾk an mˈiːɾ/","en":"I notice myself","zh":"我感受到","note":"","sourceLineIndex":44},{"id":"dracula-das-musical-11-045","lineIndex":45,"speaker":"","original":"Ich weiß nicht wo ich hingehör","ipa":"/ɪç vˈaɪs nˈɪçt vˌoː ɪç hˈɪnɡəhˌøːɾ/","en":"I don't know where I belong","zh":"我不知道自己该去往何方","note":"","sourceLineIndex":45},{"id":"dracula-das-musical-11-046","lineIndex":46,"speaker":"","original":"(Dunkle Wolken)","ipa":"/dˈʊŋklə vˈɔlkən/","en":"(Dark clouds)","zh":"（黑云沉沉）","note":"","sourceLineIndex":46},{"id":"dracula-das-musical-11-047","lineIndex":47,"speaker":"","original":"Ich liebe den großen Traum","ipa":"/ɪç lˈiːbə deːn ɡɾˈoːsən tɾˈaʊm/","en":"I love the big dream","zh":"我爱着那个最大的梦想","note":"","sourceLineIndex":47},{"id":"dracula-das-musical-11-048","lineIndex":48,"speaker":"","original":"Und doch, und doch, und doch (Bring mich heim)","ipa":"/ʊnt dˈɔx ʊnt dˈɔx ʊnt dɔx bɾˈɪŋ mɪç hˈaɪm/","en":"And yet, and yet, and yet (Take me home)","zh":"但是啊，但是呐，但是呀（带我回家）","note":"","sourceLineIndex":48},{"id":"dracula-das-musical-11-049","lineIndex":49,"speaker":"","original":"Du bist Mein Glück, mein reines Glück (heim, nach Whitby Bay)","ipa":"/duː bɪst maɪn ɡlˈʏk maɪn rˈaɪnəs ɡlˈʏk hˈaɪm nɑːx vˈɪtbiː bˈɛɪ/","en":"You are my happiness, my pure happiness (home, to Whitby Bay)","zh":"你是我的快乐，我纯粹的快乐（回家，回到惠特比）","note":"","sourceLineIndex":49},{"id":"dracula-das-musical-11-050","lineIndex":50,"speaker":"","original":"Du zeigst mir einen Weg, den ich nicht sah","ipa":"/duː tsˈaɪkst miːɾ ˌaɪnən vˈeːk deːn ɪç nˈɪçt zˈɑː/","en":"You show me a path I didn't see","zh":"你让我看到了一条我从未见过的路","note":"","sourceLineIndex":50},{"id":"dracula-das-musical-11-051","lineIndex":51,"speaker":"","original":"Und lieben heißt bereit zu stehen","ipa":"/ʊnt lˈiːbən hˈaɪst bərˈaɪt tsuː ʃtˈeːən/","en":"And loving means being ready","zh":"而爱就是随时站在身边准备好","note":"","sourceLineIndex":51},{"id":"dracula-das-musical-11-052","lineIndex":52,"speaker":"","original":"Nun, ich bin da","ipa":"/nˈuːn ɪç bɪn dˈɑː/","en":"Well, I'm here","zh":"所以，我现在来到了这里","note":"","sourceLineIndex":52},{"id":"dracula-das-musical-11-053","lineIndex":53,"speaker":"","original":"Du hast mich ohne es zu wollen","ipa":"/duː hast mɪç ˈoːnə ɛs tsuː vɔlən/","en":"You have me without wanting it","zh":"在无形之中你使我","note":"","sourceLineIndex":53},{"id":"dracula-das-musical-11-054","lineIndex":54,"speaker":"","original":"Zu einem anderen gemacht","ipa":"/tsuː ˌaɪnəm ˈandərən ɡəmˈaxt/","en":"Made into another","zh":"变为一个崭新的人","note":"","sourceLineIndex":54},{"id":"dracula-das-musical-11-055","lineIndex":55,"speaker":"","original":"Wie sehr dein Wesen mich betört","ipa":"/viː zˈeːɾ daɪn vˈeːzən mɪç bətˈœɾt/","en":"How much your nature beguiles me","zh":"你的灵魂是如此吸引着我","note":"","sourceLineIndex":55},{"id":"dracula-das-musical-11-056","lineIndex":56,"speaker":"","original":"Das hätt‘ ich nie gedacht","ipa":"/das hˈɛt ɪç nˈiː ɡədˈaxt/","en":"I would never have thought that","zh":"这是我从来都没有想到的","note":"","sourceLineIndex":56},{"id":"dracula-das-musical-11-057","lineIndex":57,"speaker":"","original":"Ich bin nur da, weil du mich liebst","ipa":"/ɪç bɪn nˈuːɾ dˈɑː vˌaɪl duː mɪç lˈiːpst/","en":"I'm only here because you love me","zh":"德古拉&米娜：我来到这里只是因为你","note":"","sourceLineIndex":57},{"id":"dracula-das-musical-11-058","lineIndex":58,"speaker":"","original":"Mit dir gewinn ich jede Schlacht","ipa":"/mɪt diːɾ ɡəvˈɪn ɪç jˈeːdə ʃlˈaxt/","en":"With you I win every battle","zh":"和你一起我能克服所有障碍","note":"","sourceLineIndex":58},{"id":"dracula-das-musical-11-059","lineIndex":59,"speaker":"","original":"Dracula & Mina & Jonathan: Vertrau mir bis ans Ende aller Zeit","ipa":"/dɾˈɑkuːlˌɑː ˈʊnt mˈiːnɑː ˈʊnt jˈoːnatˌɑːn fɛɾtɾˈaʊ miːɾ bɪs ans ˈɛndə ˈalɜ tsˈaɪt/","en":"Dracula & Mina & Jonathan: Trust me until the end of time","zh":"德古拉&米娜&乔纳森：让我们一起到时间的尽头","note":"","sourceLineIndex":59},{"id":"dracula-das-musical-11-060","lineIndex":60,"speaker":"","original":"Wir gehen gemeinsam durch die Nacht","ipa":"/viːɾ ɡˈeːən ɡəmˈaɪnzɑːm dʊɐç diː nˈaxt/","en":"We walk through the night together","zh":"让我们一起穿越黑夜","note":"","sourceLineIndex":60}],"sourceOrder":11,"displayOrder":10},{"order":12,"id":"12-die-einladung","title":"Die Einladung","titleZh":"邀请函","lines":[{"id":"dracula-das-musical-12-001","lineIndex":1,"speaker":"","original":"Ist die Stunde schon da?","ipa":"/ɪst diː ʃtˈʊndə ʃˌoːn dˈɑː/","en":"Is the hour already here?","zh":"那一刻是否已降临？","note":"","sourceLineIndex":1},{"id":"dracula-das-musical-12-002","lineIndex":2,"speaker":"","original":"Spür den Windzug kalt auf Wangen und Haar","ipa":"/ʃpˈyːɾ deːn vˈɪnttsuːk kˈalt aʊf vˈaŋən ʊnt hˈɑːɾ/","en":"Feel the cold breeze on your cheeks and hair","zh":"我感到寒意爬上我的头发与脸颊","note":"","sourceLineIndex":2},{"id":"dracula-das-musical-12-003","lineIndex":3,"speaker":"","original":"Mein Blut ist erstarrt","ipa":"/maɪn blˈuːt ɪst ɛɾʃtˈaɾt/","en":"My blood has frozen","zh":"我的血液冰冷","note":"","sourceLineIndex":3},{"id":"dracula-das-musical-12-004","lineIndex":4,"speaker":"","original":"Wie der zitternd kleine Fink, der auf den Raubvogel starrt","ipa":"/viː dɛɾ tsˈɪtɛɾnt klˈaɪnə fˈɪŋk dɛɾ aʊf deːn rˈaʊbfoːɡəl ʃtˈaɾt/","en":"Like the trembling little finch staring at the bird of prey","zh":"就如那因猛禽窥伺而颤抖的雀鸟","note":"","sourceLineIndex":4},{"id":"dracula-das-musical-12-005","lineIndex":5,"speaker":"","original":"Lass mich los","ipa":"/lˈas mɪç lˈoːs/","en":"let me go","zh":"放我走吧","note":"","sourceLineIndex":5},{"id":"dracula-das-musical-12-006","lineIndex":6,"speaker":"","original":"Ich spiel nicht mit in deinem Spiel","ipa":"/ɪç ʃpˈiːl nˈɪçt mɪt ɪn dˌaɪnəm ʃpˈiːl/","en":"I'm not playing your game","zh":"我不想参与你的游戏","note":"","sourceLineIndex":6},{"id":"dracula-das-musical-12-007","lineIndex":7,"speaker":"","original":"Lass mich nicht los","ipa":"/lˈas mɪç nˈɪçt lˈoːs/","en":"Don't let me go","zh":"别让我离开","note":"","sourceLineIndex":7},{"id":"dracula-das-musical-12-008","lineIndex":8,"speaker":"","original":"du weißt ein Kuss ist was ich will","ipa":"/duː vˈaɪst aɪn kˈʊs ɪst vˈas ɪç vɪl/","en":"you know a kiss is what I want","zh":"你知道我所冀求的不过是你的吻","note":"","sourceLineIndex":8},{"id":"dracula-das-musical-12-009","lineIndex":9,"speaker":"","original":"Sei mein Geliebter","ipa":"/zˈaɪ maɪn ɡəlˈiːptɜ/","en":"Be my lover","zh":"做我的情人","note":"","sourceLineIndex":9},{"id":"dracula-das-musical-12-010","lineIndex":10,"speaker":"","original":"Lass mich frei","ipa":"/lˈas mɪç frˈaɪ/","en":"Set me free","zh":"赐我以自由","note":"","sourceLineIndex":10},{"id":"dracula-das-musical-12-011","lineIndex":11,"speaker":"","original":"Mir ist die Welt in der du leben willst so fern","ipa":"/miːɾ ɪst diː vˈɛlt ɪn dɛɾ duː lˈeːbən vɪlst zoː fˈɛɾn/","en":"The world you want to live in is so far away from me","zh":"你生活的世界离我如此之远","note":"","sourceLineIndex":11},{"id":"dracula-das-musical-12-012","lineIndex":12,"speaker":"","original":"Komm nur herein","ipa":"/kˈɔm nˈuːɾ hɛrˈaɪn/","en":"Just come in","zh":"来我身边","note":"","sourceLineIndex":12},{"id":"dracula-das-musical-12-013","lineIndex":13,"speaker":"","original":"dann zeigt die Sklavin ihrem Herrn`","ipa":"/dan tsˈaɪkt diː sklˈɑvɪn ˌiːrəm hˈɛɾn/","en":"then the slave shows her master","zh":"我将甘做你的女奴","note":"","sourceLineIndex":13},{"id":"dracula-das-musical-12-014","lineIndex":14,"speaker":"","original":"Wie sie sich fügt, für immer fügt","ipa":"/viː ziː zɪç fˈyːkt fyːɾ ˈɪmɜ fˈyːkt/","en":"How she submits, submits forever","zh":"你的所感永恒激荡","note":"","sourceLineIndex":14},{"id":"dracula-das-musical-12-015","lineIndex":15,"speaker":"","original":"Bist du da?","ipa":"/bɪst duː dˈɑː/","en":"Are you there?","zh":"你可在这？","note":"","sourceLineIndex":15},{"id":"dracula-das-musical-12-016","lineIndex":16,"speaker":"","original":"Ist die Stunde schon da?","ipa":"/ɪst diː ʃtˈʊndə ʃˌoːn dˈɑː/","en":"Is the hour already here?","zh":"那一刻是否已降临？","note":"","sourceLineIndex":16},{"id":"dracula-das-musical-12-017","lineIndex":17,"speaker":"","original":"Warst du nur ein Spuk im dunklen Licht das ich sah?","ipa":"/vɑːɾst duː nˈuːɾ aɪn ʃpˈuːk ɪm dˈʊŋklən lˈɪçt das ɪç zˈɑː/","en":"Were you just a ghost in the dark light I saw?","zh":"我所见的是否仅为暗夜之光中一游魂？","note":"","sourceLineIndex":17},{"id":"dracula-das-musical-12-018","lineIndex":18,"speaker":"","original":"Wirst du Wolf oder Fledermaus sein?","ipa":"/vˌɪɾst duː vˈɔlf ˌoːdɜ flˈeːdɜmˌaʊs zaɪn/","en":"Will you be a wolf or a bat?","zh":"你是那狼？还是蝙蝠？","note":"","sourceLineIndex":18},{"id":"dracula-das-musical-12-019","lineIndex":19,"speaker":"","original":"Wie kann es sein","ipa":"/viː kˈan ɛs zaɪn/","en":"How can it be?","zh":"这是如何成真的？","note":"","sourceLineIndex":19},{"id":"dracula-das-musical-12-020","lineIndex":20,"speaker":"","original":"Das sich nun Alles in mir sträubt","ipa":"/das zɪç nˈuːn ˈaləs ɪn miːɾ ʃtɾˈɔøpt/","en":"That everything in me is now struggling","zh":"此刻我一切心神都在挣扎","note":"","sourceLineIndex":20},{"id":"dracula-das-musical-12-021","lineIndex":21,"speaker":"","original":"Und doch ich brenn′","ipa":"/ʊnt dɔx ɪç bɾˈɛn/","en":"And yet I burn′","zh":"此刻我正燃烧","note":"","sourceLineIndex":21},{"id":"dracula-das-musical-12-022","lineIndex":22,"speaker":"","original":"Und bin von Leidenschaft betäubt","ipa":"/ʊnt bɪn fɔn lˈaɪdənʃˌaft bətˈɔøpt/","en":"And I'm numb with passion","zh":"激情征服了我","note":"","sourceLineIndex":22},{"id":"dracula-das-musical-12-023","lineIndex":23,"speaker":"","original":"In meinem Verhängnis","ipa":"/ɪn mˌaɪnəm fɛɾhˈɛŋnɪs/","en":"In my fate","zh":"在我那灾厄的命运中","note":"","sourceLineIndex":23},{"id":"dracula-das-musical-12-024","lineIndex":24,"speaker":"","original":"Wie ich dich erwählt","ipa":"/viː ɪç dɪç ɛɾvˈɛːlt/","en":"How I choose you","zh":"我如何把你选择？","note":"","sourceLineIndex":24},{"id":"dracula-das-musical-12-025","lineIndex":25,"speaker":"","original":"Will das mein Blut in deinem Pulsschlag wiederklingt","ipa":"/vɪl das maɪn blˈuːt ɪn dˌaɪnəm pˈʊlsçlɑːk viːdɜklˈɪŋt/","en":"I want my blood to resonate in your pulse","zh":"我的鲜血可会在你心中搏动？","note":"","sourceLineIndex":25},{"id":"dracula-das-musical-12-026","lineIndex":26,"speaker":"","original":"Such das Gefühl, wenn Gift und Stachel mich durchdringt","ipa":"/zˈuːx das ɡəfˈyːl vˌɛn ɡˈɪft ʊnt ʃtˈaxəl mɪç dˈʊɐçdɾˌɪŋt/","en":"Look for the feeling when poison and sting penetrate me","zh":"当毒液交相渗透时，那将是怎样的感受…","note":"","sourceLineIndex":26},{"id":"dracula-das-musical-12-027","lineIndex":27,"speaker":"","original":"Dunkle Empfängnis","ipa":"/dˈʊŋklə ɛmpfˈɛŋnɪs/","en":"Dark conception","zh":"黑暗的幽灵","note":"","sourceLineIndex":27},{"id":"dracula-das-musical-12-028","lineIndex":28,"speaker":"","original":"Blut zu Blut","ipa":"/blˈuːt tsuː blˈuːt/","en":"Blood to blood","zh":"以鲜血交换鲜血","note":"","sourceLineIndex":28},{"id":"dracula-das-musical-12-029","lineIndex":29,"speaker":"","original":"So lade ich dich ein","ipa":"/zoː lˈɑːdə ɪç dɪç ˈaɪn/","en":"So I invite you","zh":"至此我邀请你","note":"","sourceLineIndex":29},{"id":"dracula-das-musical-12-030","lineIndex":30,"speaker":"","original":"Dein Wille soll geschehn","ipa":"/daɪn vˈɪlə zˌɔl ɡəʃˈeːn/","en":"Your will shall be done","zh":"你的愿望将化为现实","note":"","sourceLineIndex":30},{"id":"dracula-das-musical-12-031","lineIndex":31,"speaker":"","original":"Kein Pfaffentrödel hier","ipa":"/kˈaɪn pfˈafəntɾˌøːdəl hˈiːɾ/","en":"No Pfaffentri? del here","zh":"此处不见悔恨","note":"","sourceLineIndex":31},{"id":"dracula-das-musical-12-032","lineIndex":32,"speaker":"","original":"Soll unsrer Lust im Wege stehn","ipa":"/zˌɔl ˈʊnsrɜ lˈʊst ɪm vˈeːɡə ʃtˈeːn/","en":"Should stand in the way of our desire","zh":"我们的欲念愈发滋长","note":"","sourceLineIndex":32},{"id":"dracula-das-musical-12-033","lineIndex":33,"speaker":"","original":"Ich schenk dir was ich hab","ipa":"/ɪç ʃˈɛŋk diːɾ vˈas ɪç hˈɑːp/","en":"I'll give you what I have","zh":"我将一切所有献予你","note":"","sourceLineIndex":33},{"id":"dracula-das-musical-12-034","lineIndex":34,"speaker":"","original":"Mein Lebenselexier","ipa":"/maɪn lˌeːbənzˌɛlɛksˈiːɾ/","en":"My elixir of life","zh":"我生命的灵药","note":"","sourceLineIndex":34},{"id":"dracula-das-musical-12-035","lineIndex":35,"speaker":"","original":"Geliebter steig herab","ipa":"/ɡəlˈiːptɜ ʃtˈaɪk hɛrˈap/","en":"Beloved, come down","zh":"我的情人已至","note":"","sourceLineIndex":35},{"id":"dracula-das-musical-12-036","lineIndex":36,"speaker":"","original":"Komm und still deinen Durst an mir, stil nur deinen Durst an mir...","ipa":"/kˈɔm ʊnt ʃtˈɪl dˌaɪnən dˈuːɾst an mˈiːɾ ʃtˈiːl nˈuːɾ dˌaɪnən dˈuːɾst an mˈiːɾ/","en":"Come and quench your thirst with me, just quench your thirst with me...","zh":"来吧用我将你的渴望满足，用我将你的渴望满足…","note":"","sourceLineIndex":36}],"sourceOrder":12,"displayOrder":11},{"order":13,"id":"13-nosferatu","title":"Nosferatu","titleZh":"诺斯费拉图","lines":[{"id":"dracula-das-musical-13-001","lineIndex":1,"speaker":"","original":"I am here to tell you the truth you won't believe:","ipa":"/ˈiː am hˈeːrə tʊ tˈɛl jˈuː ðə tɾˈʊt jˈuː vˈoːnt bəlˈiːvə/","en":"I am here to tell you the truth you won't believe:","zh":"我在这里要告诉你一个你不会相信的事实。","note":"","sourceLineIndex":1},{"id":"dracula-das-musical-13-002","lineIndex":2,"speaker":"","original":"There are many mysteries in life.","ipa":"/tˈeːrə ˈɑːrə mˈɑniː mˈʏsteːrˌiːs ɪn lˈiːfə/","en":"There are many mysteries in life.","zh":"生命中有许多奥秘。","note":"","sourceLineIndex":2},{"id":"dracula-das-musical-13-003","lineIndex":3,"speaker":"","original":"If we watch and listen we may hope to percieve","ipa":"/ˈiːf vˈeː vˈatʃ ˈant lˈɪstən vˈeː mˈɛɪ hˈoːpə tʊ pˈɛɾsiːvə/","en":"If we watch and listen we may hope to perceive","zh":"如果我们观察和倾听，我们可能会希望察觉到","note":"","sourceLineIndex":3},{"id":"dracula-das-musical-13-004","lineIndex":4,"speaker":"","original":"What is killing your lovely wife.","ipa":"/vˈɑːt ˈiːs kˈɪlɪŋ jˈuːɾ lˈoːvəlˌiː vˈiːfə/","en":"What is killing your lovely wife?","zh":"是什么在杀害你可爱的妻子。","note":"","sourceLineIndex":4},{"id":"dracula-das-musical-13-005","lineIndex":5,"speaker":"","original":"You have heard of vampires; you're sure - they don't exist.","ipa":"/jˈuː hˈɑːvə hˈeːaɾt ɒv vˈampiːrəs jˈuːrə zˈuːrə ðeɪ dˈoːnt ɛksˈɪst/","en":"You have heard of vampires; you're sure - they don't exist.","zh":"你听说过吸血鬼，你肯定他们不存在。","note":"","sourceLineIndex":5},{"id":"dracula-das-musical-13-006","lineIndex":6,"speaker":"","original":"Let me tell you friends, that they do.","ipa":"/lˈeːt mˈeː tˈɛl jˈuː frˈiːnts tˈɑːt ðeɪ dˈoː/","en":"Let me tell you friends, that they do.","zh":"让我告诉你，朋友们，他们确实存在。","note":"","sourceLineIndex":6},{"id":"dracula-das-musical-13-007","lineIndex":7,"speaker":"","original":"Undead, Nosferatu - why give you a long list.","ipa":"/ˈʊndˌeːɑːt nˈɔsfeːrˌɑtuː vˈyː ɡˈiːvə jˈuː ˈɑː lˈɔŋ lˈɪst/","en":"Undead, Nosferatu - why give you a long list.","zh":"亡灵、诺斯费拉图--为什么要给你一个长长的清单。","note":"","sourceLineIndex":7},{"id":"dracula-das-musical-13-008","lineIndex":8,"speaker":"","original":"Point is that the legend is true.","ipa":"/pˈoːɪnt ˈiːs tˈɑːt ðə lˈeːɡənt ˈiːs tɾˈuːə/","en":"The point is that the legend is true.","zh":"关键是，这个传说是真的。","note":"","sourceLineIndex":8},{"id":"dracula-das-musical-13-009","lineIndex":9,"speaker":"","original":"A bee, when he stings once - he dies, but not the Nosferatu.","ipa":"/ˈɑː bəˈeː vˈeːn hˈeː ʃtˈɪŋs wˈʌns hˈeː diːs bˈuːt nˈoːt ðə nˈɔsfeːrˌɑtuː/","en":"A bee, when he stings once - he dies, but not the Nosferatu.","zh":"一只蜜蜂，当他被蜇一次--他就死了，但诺斯费拉图不会。","note":"","sourceLineIndex":9},{"id":"dracula-das-musical-13-010","lineIndex":10,"speaker":"","original":"Not he. His powers grow - he drinks the blood and lives again.","ipa":"/nˈoːt hˈeː hˈiːs pˈaʊɜs ɡɾˈoːf hˈeː dɾˈɪŋks ðə blˈoːt ˈant lˈiːvəs ˈɑɡaɪn/","en":"Not hey. His powers grow - he drinks the blood and lives again.","zh":"他不会。他的力量在增长--他喝了血，又活了过来。","note":"","sourceLineIndex":10},{"id":"dracula-das-musical-13-011","lineIndex":11,"speaker":"","original":"And the blood brings back his youth - the cruel and evel Nosferatu.","ipa":"/ˈant ðə blˈoːt bɾˈɪŋs bˈak hˈiːs jˈuːt ðə kɾˈuːəl ˈant ˈeːvəl nˈɔsfeːrˌɑtuː/","en":"And the blood brings back his youth - the cruel and evil Nosferatu.","zh":"血液使他恢复了年轻时的样子 - 残忍而勇敢的诺斯费拉图。","note":"","sourceLineIndex":11},{"id":"dracula-das-musical-13-012","lineIndex":12,"speaker":"","original":"And gives him the strength of twenty men.","ipa":"/ˈant ɡˈiːvəs hˈiːm ðə ʃtɾˈɛŋt ɒv twˈɛnti mˈeːn/","en":"And gives him the strength of twenty men.","zh":"并赋予他20个人的力量。","note":"","sourceLineIndex":12},{"id":"dracula-das-musical-13-013","lineIndex":13,"speaker":"","original":"He can change his form to a wolf, a fox, a bat.","ipa":"/hˈeː kˈɑːn tʃˈeɪndʒ hˈiːs fˈɔɾm tʊ ˈɑː vˈɔlf ˈɑː fˈɔks ˈɑː bˈɑːt/","en":"He can change his form to a wolf, a fox, a bat.","zh":"他可以改变自己的形态，变成狼、狐狸、蝙蝠。","note":"","sourceLineIndex":13},{"id":"dracula-das-musical-13-014","lineIndex":14,"speaker":"","original":"He commands the mist and the storm.","ipa":"/hˈeː kˈɔmants ðə mˈɪst ˈant ðə ʃtˈɔɾm/","en":"He commands the mist and the storm.","zh":"他能指挥迷雾和风暴。","note":"","sourceLineIndex":14},{"id":"dracula-das-musical-13-015","lineIndex":15,"speaker":"","original":"He can fly like eagle, or crawl like sew or rat","ipa":"/hˈeː kˈɑːn flˈyː lˈaɪk ˈeːaɡlə ˈoːɾ kɾˈavl lˈaɪk zˈeːf ˈoːɾ rˈɑːt/","en":"He can fly like eagle, or crawl like sew or rat","zh":"他能像鹰一样飞翔，或像缝纫机或老鼠一样爬行","note":"","sourceLineIndex":15},{"id":"dracula-das-musical-13-016","lineIndex":16,"speaker":"","original":"Before he assumes his own form.","ipa":"/bəfˈoːrə hˈeː ˈasʊməs hˈiːs ˈɔvn fˈɔɾm/","en":"Before he assumes his own form.","zh":"然后再变成自己的形状。","note":"","sourceLineIndex":16},{"id":"dracula-das-musical-13-017","lineIndex":17,"speaker":"","original":"How do we destroy him when so many have failed?","ipa":"/hˈoːf dˈoː vˈeː dˈɛstɾɔø hˈiːm vˈeːn zoː mˈɑniː hˈɑːvə fˈaɪleːt/","en":"How do we destroy him when so many have failed?","zh":"这么多人都失败了，我们怎么消灭他呢？","note":"","sourceLineIndex":17},{"id":"dracula-das-musical-13-018","lineIndex":18,"speaker":"","original":"Someone has to cut off his head.","ipa":"/zˌoːmeːˈoːnə hˈɑːs tʊ kˈuːt ˈɔf hˈiːs hˈeːɑːt/","en":"Someone has to cut off his head.","zh":"必须有人砍下他的头。","note":"","sourceLineIndex":18},{"id":"dracula-das-musical-13-019","lineIndex":19,"speaker":"","original":"And to make quite certain his heart must be impaled.","ipa":"/ˈant tʊ mˈɑːkə kvˈiːtə kˈɛɾtaɪn hˈiːs hˈeːaɾt mˈʊst bˈeː ˈɪmpalˌeːt/","en":"And to make quite certain his heart must be impaled.","zh":"为了确定他的心脏必须被刺穿。","note":"","sourceLineIndex":19},{"id":"dracula-das-musical-13-020","lineIndex":20,"speaker":"","original":"And then the Nasferatu -","ipa":"/ˈant tˈeːn ðə nˈasfeːrˌɑtuː/","en":"And then the Nasferatu -","zh":"然后诺斯费拉图...","note":"","sourceLineIndex":20},{"id":"dracula-das-musical-13-021","lineIndex":21,"speaker":"","original":"At last the Nosferatu","ipa":"/ˈɑːt lˈast ðə nˈɔsfeːrˌɑtuː/","en":"At last the Nosferatu","zh":"最后，诺斯费拉图","note":"","sourceLineIndex":21},{"id":"dracula-das-musical-13-022","lineIndex":22,"speaker":"","original":"Will no more be un-dead.","ipa":"/vɪl nˈoː mˈoːrə bˈeː ˈʊndˈeːɑːt/","en":"Will no longer be un-dead.","zh":"将不再是不死之身。","note":"","sourceLineIndex":22}],"sourceOrder":13,"displayOrder":12},{"order":14,"id":"14-ein-leben-mehr","title":"Ein Leben mehr","titleZh":"又一个生命","lines":[{"id":"dracula-das-musical-14-001","lineIndex":1,"speaker":"","original":"Was sich tarnt wie ein Ende ist neuer Beginn","ipa":"/vˈas zɪç tˈaɾnt viː aɪn ˈɛndə ɪst nˈɔøɜ bəɡˈɪn/","en":"What disguises itself as an end is a new beginning","zh":"你们所认为的结束实际是一个新的开始","note":"","sourceLineIndex":1},{"id":"dracula-das-musical-14-002","lineIndex":2,"speaker":"","original":"Ich komme zur Taufe und nicht zur Beerdigung","ipa":"/ɪç kˈɔmə tsuːɾ tˈaʊfə ʊnt nˈɪçt tsuːɾ bəˈeːɾdɪɡˌʊŋ/","en":"I'm coming to the baptism and not the funeral","zh":"这不是你的葬礼 而是你新生的洗礼","note":"","sourceLineIndex":2},{"id":"dracula-das-musical-14-003","lineIndex":3,"speaker":"","original":"halt die Tränen zurück","ipa":"/hˈalt diː tɾˈɛːnən tsuːrˈʏk/","en":"hold back the tears","zh":"收起你的哀伤","note":"","sourceLineIndex":3},{"id":"dracula-das-musical-14-004","lineIndex":4,"speaker":"","original":"Und empfang deinen Bräutigam","ipa":"/ʊnt ɛmpfˈaŋ dˌaɪnən bɾˈɔøtɪɡˌɑːm/","en":"And receive your bridegroom","zh":"准备迎接你的新郎","note":"","sourceLineIndex":4},{"id":"dracula-das-musical-14-005","lineIndex":5,"speaker":"","original":"Unsere Hochzeit aus Blut bringt uns selige Kinderschar","ipa":"/ˌʊnzrə hˈoːxtsˌaɪt ˌaʊs blˈuːt bɾˈɪŋt ʊns zˈeːlɪɡə kˈɪndɜʃˌɑːɾ/","en":"Our marriage of blood brings us blessed flocks of children","zh":"我们沐浴着鲜血的婚礼会给我们带来更多同类","note":"","sourceLineIndex":5},{"id":"dracula-das-musical-14-006","lineIndex":6,"speaker":"","original":"Eine untote Brut","ipa":"/ˌaɪnə ˈʊntˌoːtə bɾˈuːt/","en":"An undead spawn","zh":"这是不死之血！","note":"","sourceLineIndex":6},{"id":"dracula-das-musical-14-007","lineIndex":7,"speaker":"","original":"Ein Leben mehr und du entkommst dem kühlen Grab","ipa":"/aɪn lˈeːbən mˈeːɾ ʊnt duː ɛntkˈɔmst deːm kˈyːlən ɡɾˈɑːp/","en":"One more life and you'll escape the cool grave","zh":"重获新生 走出那阴冷的坟墓","note":"","sourceLineIndex":7},{"id":"dracula-das-musical-14-008","lineIndex":8,"speaker":"","original":"brauchst kein Gebet steigst nich ins toten Reich hinab","ipa":"/bɾˈaʊxst kˈaɪn ɡeːbˈeːt ʃtˈaɪkst nˈɪç ɪns tˈoːtən rˈaɪç hɪnˈap/","en":"You don't need prayer, you don't descend into the dead realm","zh":"不需要什么祈祷 也没有什么灵魂需要拯救","note":"","sourceLineIndex":8},{"id":"dracula-das-musical-14-009","lineIndex":9,"speaker":"","original":"Spart euch den Psalm","ipa":"/ʃpˈaɾt ɔøç deːn psˈalm/","en":"Save the psalm","zh":"停止那徒劳的祷告","note":"","sourceLineIndex":9},{"id":"dracula-das-musical-14-010","lineIndex":10,"speaker":"","original":"Weint einem Anderem hinterher","ipa":"/vˈaɪnt ˌaɪnəm ˈandərəm hˈɪntɜhɜ/","en":"Cry after someone else","zh":"省省你们的眼泪","note":"","sourceLineIndex":10},{"id":"dracula-das-musical-14-011","lineIndex":11,"speaker":"","original":"Denn die Gnade die ich gewähr wiegt unendlich schwer","ipa":"/dɛn diː ɡənˈɑːdə diː ɪç ɡəvˈɛːɾ vˈiːkt ˈʊnˌɛntlɪç ʃvˈeːɾ/","en":"Because the grace that I grant weighs infinitely heavy","zh":"我所赐予的恩赏 将会沉重到无法估量","note":"","sourceLineIndex":11},{"id":"dracula-das-musical-14-012","lineIndex":12,"speaker":"","original":"Ein Leben mehr","ipa":"/aɪn lˈeːbən mˈeːɾ/","en":"One more life","zh":"重获新生！","note":"","sourceLineIndex":12},{"id":"dracula-das-musical-14-013","lineIndex":13,"speaker":"","original":"Unsere Nachkommen werden sich prächtig vermehren","ipa":"/ˌʊnzrə nˈaxkɔmən vˌɛɾdən zɪç pɾˈɛçtɪç fɛɾmˈeːrən/","en":"Our offspring will multiply magnificently","zh":"我们的同伴马上就会开始激增","note":"","sourceLineIndex":13},{"id":"dracula-das-musical-14-014","lineIndex":14,"speaker":"","original":"schon nach kürzester Zeit wirst du Götter von London sein","ipa":"/ʃˌoːn nɑːx kˈʏɾtsəstɜ tsˈaɪt vˌɪɾst duː ɡˈœtɜ fɔn lˈɔndoːn zaɪn/","en":"in no time you will be gods of London","zh":"用不了多久你就会成为伦敦的女神","note":"","sourceLineIndex":14},{"id":"dracula-das-musical-14-015","lineIndex":15,"speaker":"","original":"Jede Nacht wird zum Fest","ipa":"/jˈeːdə nˈaxt vˌɪɾt tsʊm fˈɛst/","en":"Every night becomes a celebration","zh":"每个夜晚都会是我们的盛宴","note":"","sourceLineIndex":15},{"id":"dracula-das-musical-14-016","lineIndex":16,"speaker":"","original":"und wir schlachten ein Opferlamm","ipa":"/ʊnt viːɾ ʃlˈaxtən aɪn ˈɔpfɜlˌam/","en":"and we kill a sacrificial lamb","zh":"我们屠杀那些无辜的人","note":"","sourceLineIndex":16},{"id":"dracula-das-musical-14-017","lineIndex":17,"speaker":"","original":"Kinder trinkt euer Blut denn so blüht und gedeiht der Stamm unser untoten Brut","ipa":"/kˈɪndɜ tɾˈɪŋkt ˈɔøɜ blˈuːt dɛn zoː blˈyːt ʊnt ɡədˈaɪht dɛɾ ʃtˈam ˌʊnzɜ ˈʊntˌoːtən bɾˈuːt/","en":"Children drink your blood because this is how the tribe of our undead brood flourishes and thrives","zh":"让孩子们喝你们的血我们的力量将会日渐壮大 我们的不死之血！","note":"","sourceLineIndex":17},{"id":"dracula-das-musical-14-019","lineIndex":18,"speaker":"","original":"Ein Leben mehr das ist mein Trost für deine Qual","ipa":"/aɪn lˈeːbən mˈeːɾ das ɪst maɪn tɾˈoːst fyːɾ dˌaɪnə kvˈɑːl/","en":"One more life is my consolation for your torment","zh":"重获新生！这就是为你的苦痛而得到的奖赏","note":"","sourceLineIndex":19},{"id":"dracula-das-musical-14-020","lineIndex":19,"speaker":"","original":"Geh in die Welt zeig ihr dein dunkles Potential","ipa":"/ɡˈeː ɪn diː vˈɛlt tsˈaɪk iːɾ daɪn dˈʊŋkləs pˌoːtɛntiːˈɑːl/","en":"Go into the world and show it your dark potential","zh":"潜入这个世界 放纵你心底最黑暗的欲望","note":"","sourceLineIndex":20},{"id":"dracula-das-musical-14-021","lineIndex":20,"speaker":"","original":"Kinder der Nacht tauchen die Stadt in dunkles Rot","ipa":"/kˈɪndɜ dɛɾ nˈaxt tˈaʊxən diː ʃtˈat ɪn dˈʊŋkləs rˈoːt/","en":"Children of the night bathe the city in dark red","zh":"可爱的黑暗之子们 尽情将城市浸入醉人的暗红","note":"","sourceLineIndex":21},{"id":"dracula-das-musical-14-022","lineIndex":21,"speaker":"","original":"wählen ein Opfer aus und saugen es leer","ipa":"/vˈɛːlən aɪn ˈɔpfɜ ˌaʊs ʊnt zˈaʊɡən ɛs lˈeːɾ/","en":"select a victim and suck it dry","zh":"仔细的挑选你的猎物 吸尽他们的最后一滴血","note":"","sourceLineIndex":22},{"id":"dracula-das-musical-14-023","lineIndex":22,"speaker":"","original":"Ein Leben mehr","ipa":"/aɪn lˈeːbən mˈeːɾ/","en":"One more life","zh":"重获新生！","note":"","sourceLineIndex":23},{"id":"dracula-das-musical-14-024","lineIndex":23,"speaker":"","original":"Außerordentlich gut schmeckt das Blut der Enthaltsamkeit","ipa":"/ˈaʊseːrˌɔɾdəntlɪç ɡˈuːt ʃmˈɛkt das blˈuːt dɛɾ ɛnthˈaltzɑːmkˌaɪt/","en":"The blood of abstinence tastes extraordinarily good","zh":"那些未经世俗污染的血液是梦寐以求的美味","note":"","sourceLineIndex":24},{"id":"dracula-das-musical-14-025","lineIndex":24,"speaker":"","original":"Sucht dir ein zartes Geschöpf, das in Unschuld erstrahlt","ipa":"/zˈuːxt diːɾ aɪn tsˈaɾtəs ɡəʃˈœpf das ɪn ˈʊnʃˌʊlt ɛɾʃtɾˈɑːlt/","en":"Find a delicate creature who shines in innocence","zh":"去寻找纯洁的儿童 品味他们鲜嫩的肉体","note":"","sourceLineIndex":25},{"id":"dracula-das-musical-14-026","lineIndex":25,"speaker":"","original":"Ein Leben mehr und du entkommst dem kühlen Grab","ipa":"/aɪn lˈeːbən mˈeːɾ ʊnt duː ɛntkˈɔmst deːm kˈyːlən ɡɾˈɑːp/","en":"One more life and you'll escape the cool grave","zh":"重获新生！走出那阴冷的坟墓","note":"","sourceLineIndex":26},{"id":"dracula-das-musical-14-027","lineIndex":26,"speaker":"","original":"brauchst kein Gebet steigst nich ins toten Reich hinab","ipa":"/bɾˈaʊxst kˈaɪn ɡeːbˈeːt ʃtˈaɪkst nˈɪç ɪns tˈoːtən rˈaɪç hɪnˈap/","en":"You don't need prayer, you don't descend into the dead realm","zh":"不需要什么祈祷 也没有什么灵魂需要拯救","note":"","sourceLineIndex":27},{"id":"dracula-das-musical-14-028","lineIndex":27,"speaker":"","original":"Kinder der Nacht tauchen die Stadt in dunkles Rot","ipa":"/kˈɪndɜ dɛɾ nˈaxt tˈaʊxən diː ʃtˈat ɪn dˈʊŋkləs rˈoːt/","en":"Children of the night bathe the city in dark red","zh":"可爱的黑夜之子们 尽情的将城市浸入醉人的暗红","note":"","sourceLineIndex":28},{"id":"dracula-das-musical-14-029","lineIndex":28,"speaker":"","original":"wählen ein Opfer aus und saugen es leer","ipa":"/vˈɛːlən aɪn ˈɔpfɜ ˌaʊs ʊnt zˈaʊɡən ɛs lˈeːɾ/","en":"select a victim and suck it dry","zh":"仔细挑选你的猎物 吸尽他们的最后一滴血","note":"","sourceLineIndex":29},{"id":"dracula-das-musical-14-030","lineIndex":29,"speaker":"","original":"Ein Leben mehr","ipa":"/aɪn lˈeːbən mˈeːɾ/","en":"One more life","zh":"重获新生！","note":"","sourceLineIndex":30},{"id":"dracula-das-musical-14-031","lineIndex":30,"speaker":"","original":"Leben und nehmen und nehmen und leben und nehmen und nehmen und leben und ein Leben mehr","ipa":"/lˈeːbən ʊnt nˈeːmən ʊnt nˈeːmən ʊnt lˈeːbən ʊnt nˈeːmən ʊnt nˈeːmən ʊnt lˈeːbən ʊnt aɪn lˈeːbən mˈeːɾ/","en":"Live and take and take and live and take and take and live and one more life","zh":"他们的生命将一个接一个接一个地凋落 而我们将获得一次再一次再一次的新生！","note":"","sourceLineIndex":31}],"sourceOrder":14,"displayOrder":13},{"order":15,"id":"15-lass-mich-dich-nicht-lieben","title":"Lass mich dich nicht lieben","titleZh":"别让我爱你","lines":[{"id":"dracula-das-musical-15-001","lineIndex":1,"speaker":"","original":"Es schlägt mein Herz nun","ipa":"/ɛs ʃlˈɛːkt maɪn hˈɛɾts nˈuːn/","en":"My heart is beating now","zh":"现在我的心","note":"","sourceLineIndex":1},{"id":"dracula-das-musical-15-002","lineIndex":2,"speaker":"","original":"Zwischen Qual und Glück","ipa":"/tsvˈɪʃən kvˈɑːl ʊnt ɡlˈʏk/","en":"Between torment and happiness","zh":"在痛苦和喜悦间博动","note":"","sourceLineIndex":2},{"id":"dracula-das-musical-15-003","lineIndex":3,"speaker":"","original":"Gibt es denn kein Zurück?","ipa":"/ɡˈiːpt ɛs dɛn kˈaɪn tsuːrˈʏk/","en":"Is there no turning back?","zh":"难道无法回头了么？","note":"","sourceLineIndex":3},{"id":"dracula-das-musical-15-004","lineIndex":4,"speaker":"","original":"Lass mich dich nicht lieben","ipa":"/lˈas mɪç dɪç nˈɪçt lˈiːbən/","en":"Don't make me love you","zh":"不要让我爱你","note":"","sourceLineIndex":4},{"id":"dracula-das-musical-15-005","lineIndex":5,"speaker":"","original":"Lass mich nicht begehren","ipa":"/lˈas mɪç nˈɪçt bəɡˈeːrən/","en":"Don't make me desire","zh":"不要让我渴望得到","note":"","sourceLineIndex":5},{"id":"dracula-das-musical-15-006","lineIndex":6,"speaker":"","original":"Was ich fürchte und doch ganz heimlich begehr.","ipa":"/vˈas ɪç fˈʏɾçtə ʊnt dɔx ɡˌants hˈaɪmlɪç bəɡˈeːɾ/","en":"What I fear and but secretly desire.","zh":"我害怕但内心又期盼的东西","note":"","sourceLineIndex":6},{"id":"dracula-das-musical-15-008","lineIndex":7,"speaker":"","original":"nimm mir nicht den Frühling","ipa":"/nˈɪm miːɾ nˈɪçt deːn frˈyːlɪŋ/","en":"don't take away my spring","zh":"不要夺走我的春天","note":"","sourceLineIndex":8},{"id":"dracula-das-musical-15-009","lineIndex":8,"speaker":"","original":"nimm mir nicht das Leben","ipa":"/nˈɪm miːɾ nˈɪçt das lˈeːbən/","en":"don't take my life","zh":"不要拿走我的生命","note":"","sourceLineIndex":9},{"id":"dracula-das-musical-15-010","lineIndex":9,"speaker":"","original":"ich weiß dass dein Kuss","ipa":"/ɪç vˈaɪs das daɪn kˈʊs/","en":"I know that your kiss","zh":"我知道你的吻","note":"","sourceLineIndex":10},{"id":"dracula-das-musical-15-011","lineIndex":10,"speaker":"","original":"schon mein Untergang wär.","ipa":"/ʃˌoːn maɪn ˌʊntɜɡˈaŋ vˈɛːɾ/","en":"would already be my downfall.","zh":"会带给我毁灭","note":"","sourceLineIndex":11},{"id":"dracula-das-musical-15-012","lineIndex":11,"speaker":"","original":"Ich bin schwach und verwirrt","ipa":"/ɪç bɪn ʃvˈax ʊnt fɛɾvˈɪɾt/","en":"I am weak and confused","zh":"我脆弱而迷茫","note":"","sourceLineIndex":12},{"id":"dracula-das-musical-15-013","lineIndex":12,"speaker":"","original":"Wenn du stehst neben mir","ipa":"/vˌɛn duː ʃtˈeːst nˌeːbən mˈiːɾ/","en":"When you stand next to me","zh":"当你站在我身旁","note":"","sourceLineIndex":13},{"id":"dracula-das-musical-15-014","lineIndex":13,"speaker":"","original":"Besser wär‘s ich geh fort","ipa":"/bˈɛsɜ vˈɛːɾs ɪç ɡˈeː fˈɔɾt/","en":"It would be better if I went away","zh":"我本应逃开","note":"","sourceLineIndex":14},{"id":"dracula-das-musical-15-015","lineIndex":14,"speaker":"","original":"Aber nein, ich bleib hier.","ipa":"/ˌɑːbɜ nˈaɪn ɪç blˈaɪp hˈiːɾ/","en":"But no, I'll stay here.","zh":"但却留在原地","note":"","sourceLineIndex":15},{"id":"dracula-das-musical-15-016","lineIndex":15,"speaker":"","original":"Hilf mir, dich zu hassen","ipa":"/hˈɪlf mˈiːɾ dɪç tsuː hˈasən/","en":"Help me hate you","zh":"帮帮我，让我恨你","note":"","sourceLineIndex":16},{"id":"dracula-das-musical-15-017","lineIndex":16,"speaker":"","original":"Hilf mir, dich zu meiden.","ipa":"/hˈɪlf mˈiːɾ dɪç tsuː mˈaɪdən/","en":"Help me avoid you.","zh":"帮帮我，让我能回避你","note":"","sourceLineIndex":17},{"id":"dracula-das-musical-15-018","lineIndex":17,"speaker":"","original":"Bin ich nicht auf brav und bescheiden getrimmt?","ipa":"/bɪn ɪç nˈɪçt aʊf bɾˈɑːf ʊnt bəʃˈaɪdən ɡətɾˈɪmt/","en":"I'm not being good and modestly trimmed?","zh":"难道我不是本份和谨慎的女人？","note":"","sourceLineIndex":18},{"id":"dracula-das-musical-15-020","lineIndex":18,"speaker":"","original":"Plötzlich trägt dein Feuer alle meine Träume.","ipa":"/plˈœtslɪç tɾˈɛːkt daɪn fˈɔøɜ ˈalə mˌaɪnə tɾˈɔømə/","en":"Suddenly your fire carries all my dreams.","zh":"突然间你的光辉承载了我所有的梦想","note":"","sourceLineIndex":20},{"id":"dracula-das-musical-15-022","lineIndex":19,"speaker":"","original":"Seltsam wie das Herz","ipa":"/zˈɛltzɑːm viː das hˈɛɾts/","en":"Strange as the heart","zh":"奇异的心绪","note":"","sourceLineIndex":22},{"id":"dracula-das-musical-15-023","lineIndex":20,"speaker":"","original":"Die Vernunft überstimmt.","ipa":"/diː fɛɾnˈʊnft ˌyːbɜʃtˈɪmt/","en":"Reason prevails.","zh":"超越了我的理智","note":"","sourceLineIndex":23},{"id":"dracula-das-musical-15-024","lineIndex":21,"speaker":"","original":"Ich weiß führt mein Weg mich nun","ipa":"/ɪç vˈaɪs fˈyːɾt maɪn vˈeːk mɪç nˈuːn/","en":"I know my path leads me now","zh":"我知道我的路","note":"","sourceLineIndex":24},{"id":"dracula-das-musical-15-025","lineIndex":22,"speaker":"","original":"In Glück oder Leid.","ipa":"/ɪn ɡlˈʏk ˌoːdɜ lˈaɪt/","en":"In happiness or suffering.","zh":"将要面临幸与不幸","note":"","sourceLineIndex":25},{"id":"dracula-das-musical-15-026","lineIndex":23,"speaker":"","original":"Doch niemals kann ich diesem Traum entfliehn.","ipa":"/dɔx nˈiːmɑːls kˌan ɪç dˌiːzəm tɾˈaʊm ɛntflˈiːn/","en":"But I can never escape this dream.","zh":"但我无法从这个梦境里逃脱","note":"","sourceLineIndex":26},{"id":"dracula-das-musical-15-027","lineIndex":24,"speaker":"","original":"Lass mich dich nicht lieben","ipa":"/lˈas mɪç dɪç nˈɪçt lˈiːbən/","en":"Don't make me love you","zh":"不要让我爱你","note":"","sourceLineIndex":27},{"id":"dracula-das-musical-15-028","lineIndex":25,"speaker":"","original":"Nie mehr von dir träumen.","ipa":"/nˈiː mˈeːɾ fɔn diːɾ tɾˈɔømən/","en":"Never dream about you again.","zh":"不要再给我梦想","note":"","sourceLineIndex":28},{"id":"dracula-das-musical-15-029","lineIndex":26,"speaker":"","original":"Noch bin ich erlöst","ipa":"/nɔx bɪn ɪç ɛɾlˈœst/","en":"I am still redeemed","zh":"如果你给我自由","note":"","sourceLineIndex":29},{"id":"dracula-das-musical-15-030","lineIndex":27,"speaker":"","original":"Wenn du Freiheit mir gibts.","ipa":"/vˌɛn duː frˈaɪhaɪt miːɾ ɡˈiːpts/","en":"If you give me freedom.","zh":"我现在还能解脱","note":"","sourceLineIndex":30},{"id":"dracula-das-musical-15-031","lineIndex":28,"speaker":"","original":"Soll ich dir gehören","ipa":"/zˌɔl ɪç diːɾ ɡəhˈøːrən/","en":"Should I be yours","zh":"如果天意让我属于你","note":"","sourceLineIndex":31},{"id":"dracula-das-musical-15-032","lineIndex":29,"speaker":"","original":"Muss du eins mir schwören.","ipa":"/mˈʊs duː aɪns miːɾ ʃvˈøːrən/","en":"Do you have to swear to me?","zh":"你必须向我发誓","note":"","sourceLineIndex":32},{"id":"dracula-das-musical-15-033","lineIndex":30,"speaker":"","original":"Lass mich dich nur lieben wenn du mich auch liebst.","ipa":"/lˈas mɪç dɪç nˈuːɾ lˈiːbən vˌɛn duː mɪç ˌaʊx lˈiːpst/","en":"Just let me love you if you love me too.","zh":"只有当你也爱我的时候才让我爱上你","note":"","sourceLineIndex":33}],"sourceOrder":15,"displayOrder":14},{"order":16,"id":"16-roseanne","title":"Roseanne","titleZh":"罗珊娜","lines":[{"id":"dracula-das-musical-16-001","lineIndex":1,"speaker":"","original":"Kein Mädchen war wie Roseanne","ipa":"/kˈaɪn mˈɛːdçən vɑːɾ viː rˈoːzeːˌanə/","en":"No girl was like Roseanne","zh":"没有女孩曾像Roseanne一样","note":"","sourceLineIndex":1},{"id":"dracula-das-musical-16-002","lineIndex":2,"speaker":"","original":"So klug und froh, wie Roseanne","ipa":"/zoː klˈuːk ʊnt frˈoː viː rˈoːzeːˌanə/","en":"So smart and happy, like Roseanne","zh":"聪明快乐，像Roseanne一样","note":"","sourceLineIndex":2},{"id":"dracula-das-musical-16-003","lineIndex":3,"speaker":"","original":"Jahre gehen still ins Land","ipa":"/jˈɑːrə ɡˈeːən ʃtˈɪl ɪns lˈant/","en":"Years go by in silence","zh":"时光静静逝去","note":"","sourceLineIndex":3},{"id":"dracula-das-musical-16-004","lineIndex":4,"speaker":"","original":"Sommer geht, Sommer kommt","ipa":"/zˈɔmɜ ɡˈeːt zˈɔmɜ kˈɔmt/","en":"Summer goes, summer comes","zh":"春去秋来","note":"","sourceLineIndex":4},{"id":"dracula-das-musical-16-005","lineIndex":5,"speaker":"","original":"Alles zieht vorbei an mir","ipa":"/ˈaləs tsˈiːt foːɾbˈaɪ an mˈiːɾ/","en":"Everything passes me by","zh":"所有事物于我如过眼烟云","note":"","sourceLineIndex":5},{"id":"dracula-das-musical-16-006","lineIndex":6,"speaker":"","original":"Als wäre nichts geschehen.","ipa":"/als vˈɛːrə nˈɪçts ɡəʃˈeːən/","en":"As if nothing had happened.","zh":"仿佛什么都没发生","note":"","sourceLineIndex":6},{"id":"dracula-das-musical-16-007","lineIndex":7,"speaker":"","original":"Wintertag, Frühlingsduft","ipa":"/vˈɪntɜtˌɑːk frˈyːlɪŋsdˌʊft/","en":"Winter day, spring scent","zh":"冬去春来","note":"","sourceLineIndex":7},{"id":"dracula-das-musical-16-008","lineIndex":8,"speaker":"","original":"Nie mehr liegt ihr Lachen in der Luft","ipa":"/nˈiː mˈeːɾ lˈiːkt iːɾ lˈaxən ɪn dɛɾ lˈʊft/","en":"Her laughter will never be in the air again","zh":"空气中不再有她的笑声","note":"","sourceLineIndex":8},{"id":"dracula-das-musical-16-009","lineIndex":9,"speaker":"","original":"Roseanne, mein Herz ist kalt und leer","ipa":"/rˈoːzeːˌanə maɪn hˈɛɾts ɪst kˈalt ʊnt lˈeːɾ/","en":"Roseanne, my heart is cold and empty","zh":"Roseanne，我的心冰冷空虚","note":"","sourceLineIndex":9},{"id":"dracula-das-musical-16-010","lineIndex":10,"speaker":"","original":"Mein Gott, wie fehlst du mir.","ipa":"/maɪn ɡˈɔt viː fˈeːlst duː mˈiːɾ/","en":"My God, how I miss you.","zh":"上帝啊，我多么想念你！","note":"","sourceLineIndex":10},{"id":"dracula-das-musical-16-011","lineIndex":11,"speaker":"","original":"Wie lebhaft bleibt dein frohes Bild in mir","ipa":"/viː lˈeːphaft blˈaɪpt daɪn frˈoːəs bˈɪlt ɪn mˈiːɾ/","en":"How vividly your happy image remains in me","zh":"你的音容笑貌在我心中栩栩如生","note":"","sourceLineIndex":11},{"id":"dracula-das-musical-16-012","lineIndex":12,"speaker":"","original":"Denn wahre Liebe bleibt bestehen","ipa":"/dɛn vˈɑːrə lˈiːbə blˈaɪpt bəʃtˈeːən/","en":"Because true love endures","zh":"因为真爱永驻","note":"","sourceLineIndex":12},{"id":"dracula-das-musical-16-013","lineIndex":13,"speaker":"","original":"Warst du nicht viel zu jung","ipa":"/vɑːɾst duː nˈɪçt fˈiːl tsuː jˈʊŋ/","en":"Weren't you much too young?","zh":"你走得太年轻","note":"","sourceLineIndex":13},{"id":"dracula-das-musical-16-014","lineIndex":14,"speaker":"","original":"Viel zu schön um so früh zu gehen.","ipa":"/fˈiːl tsuː ʃˈøːn ʊm zoː frˈyː tsuː ɡˈeːən/","en":"Far too beautiful to leave so early.","zh":"太美，太早","note":"","sourceLineIndex":14},{"id":"dracula-das-musical-16-015","lineIndex":15,"speaker":"","original":"Kein Mädchen war wie Roseanne","ipa":"/kˈaɪn mˈɛːdçən vɑːɾ viː rˈoːzeːˌanə/","en":"There was no girl like Roseanne","zh":"没有女孩曾像Roseanne一样","note":"","sourceLineIndex":15},{"id":"dracula-das-musical-16-016","lineIndex":16,"speaker":"","original":"Verspielt und sanft wie Roseanne","ipa":"/fɛɾʃpˈiːlt ʊnt zˈanft viː rˈoːzeːˌanə/","en":"Playful and gentle like Roseanne","zh":"顽皮温柔，像Roseanne一样","note":"","sourceLineIndex":16},{"id":"dracula-das-musical-16-017","lineIndex":17,"speaker":"","original":"Sommer geht, Sommer kommt","ipa":"/zˈɔmɜ ɡˈeːt zˈɔmɜ kˈɔmt/","en":"Summer goes, summer comes","zh":"春去秋来","note":"","sourceLineIndex":17},{"id":"dracula-das-musical-16-018","lineIndex":18,"speaker":"","original":"Und mein Herz bleibt leer und unbewohnt","ipa":"/ʊnt maɪn hˈɛɾts blˈaɪpt lˈeːɾ ʊnt ˈʊnbəvˌoːnt/","en":"And my heart remains empty and uninhabited","zh":"我的心依然空虚，无法习惯","note":"","sourceLineIndex":18},{"id":"dracula-das-musical-16-019","lineIndex":19,"speaker":"","original":"Es fand die Liebe wohl zu früh","ipa":"/ɛs fˈant diː lˈiːbə vˈoːl tsuː frˈyː/","en":"Love probably found it too early","zh":"定是爱得太早","note":"","sourceLineIndex":19},{"id":"dracula-das-musical-16-020","lineIndex":20,"speaker":"","original":"Und starb genau wie sie.","ipa":"/ʊnt ʃtˈaɾp ɡənˈaʊ viː ziː/","en":"And died just like her.","zh":"而随她死去了吧","note":"","sourceLineIndex":20},{"id":"dracula-das-musical-16-021","lineIndex":21,"speaker":"","original":"Für Roseanne erschaff ich eine bessere Welt","ipa":"/fyːɾ rˈoːzeːˌanə ɛɾʃˈaf ɪç ˌaɪnə bˈɛsərə vˈɛlt/","en":"I'm creating a better world for Roseanne","zh":"为了Roseanne，我创造了一个更好的世界","note":"","sourceLineIndex":21},{"id":"dracula-das-musical-16-022","lineIndex":22,"speaker":"","original":"Und leb ein Leben in Gefahr","ipa":"/ʊnt lˈeːp aɪn lˈeːbən ɪn ɡəfˈɑːɾ/","en":"And live a life in danger","zh":"终生活在危险中","note":"","sourceLineIndex":22},{"id":"dracula-das-musical-16-023","lineIndex":23,"speaker":"","original":"Nun manchmal seh ich sie","ipa":"/nˈuːn mˈançmɑːl zˈeː ɪç ziː/","en":"Now sometimes I see her","zh":"现在，有时我看见她","note":"","sourceLineIndex":23},{"id":"dracula-das-musical-16-024","lineIndex":24,"speaker":"","original":"Vor mir stehen","ipa":"/fˌɔɾ miːɾ ʃtˈeːən/","en":"Standing in front of me","zh":"站在我面前","note":"","sourceLineIndex":24},{"id":"dracula-das-musical-16-025","lineIndex":25,"speaker":"","original":"Zum Greifen nah, wunderschön und wahr","ipa":"/tsʊm ɡɾˈaɪfən nˈɑː vˈʊndɜʃˌøːn ʊnt vˈɑːɾ/","en":"Within reach, beautiful and true","zh":"近在咫尺，美丽又真实","note":"","sourceLineIndex":25},{"id":"dracula-das-musical-16-026","lineIndex":26,"speaker":"","original":"Der Sommer ist schon nah","ipa":"/dɛɾ zˈɔmɜ ɪst ʃˌoːn nˈɑː/","en":"Summer is already near","zh":"夏天快到了","note":"","sourceLineIndex":26},{"id":"dracula-das-musical-16-027","lineIndex":27,"speaker":"","original":"Wie wünscht ich du wärst da.","ipa":"/viː vˈʏnʃt ɪç duː vˈɛːɾst dˈɑː/","en":"How I wish you were there.","zh":"我多希望有你在！","note":"","sourceLineIndex":27}],"sourceOrder":16,"displayOrder":15},{"order":17,"id":"17-war-ich-der-wind","title":"Wär ich der Wind","titleZh":"假如我是风","lines":[{"id":"dracula-das-musical-17-001","lineIndex":1,"speaker":"","original":"Mit einem Pflock durch sein Herz soll er sterben","ipa":"/mɪt ˌaɪnəm pflˈɔk dʊɐç zaɪn hˈɛɾts zˌɔl ɛɾ ʃtˈɛɾbən/","en":"He shall die with a stake through his heart","zh":"他们想要用木桩戳穿他的心脏置他于死地","note":"","sourceLineIndex":1},{"id":"dracula-das-musical-17-002","lineIndex":2,"speaker":"","original":"warum fühl ich den Drang ihn zu warnen vor ihnen","ipa":"/vɑːrˈʊm fˈyːl ɪç deːn dɾˈaŋ iːn tsuː vˈaɾnən fˌɔɾ ˈiːnən/","en":"why do I feel the need to warn him about them","zh":"我为什么会想提醒他提防他们","note":"","sourceLineIndex":2},{"id":"dracula-das-musical-17-003","lineIndex":3,"speaker":"","original":"warum schreck ich zurück vor dem Kampf","ipa":"/vɑːrˈʊm ʃrˈɛk ɪç tsuːrˈʏk fˌɔɾ deːm kˈampf/","en":"why do I shy away from the fight","zh":"为什么我会想要躲避","note":"","sourceLineIndex":3},{"id":"dracula-das-musical-17-004","lineIndex":4,"speaker":"","original":"der so unvermeidbar scheint","ipa":"/dɛɾ zoː ˈʊnfɛɾmˌaɪdbɑːɾ ʃˈaɪnt/","en":"which seems so inevitable","zh":"我知道这场战争不可避免","note":"","sourceLineIndex":4},{"id":"dracula-das-musical-17-005","lineIndex":5,"speaker":"","original":"Mit jedem Schritt auf dem Weg ins Verderben","ipa":"/mɪt jˈeːdəm ʃrˈɪt aʊf deːm vˈeːk ɪns fɛɾdˈɛɾbən/","en":"With every step on the way to destruction","zh":"这条路上的每一步都引领我走向毁灭","note":"","sourceLineIndex":5},{"id":"dracula-das-musical-17-006","lineIndex":6,"speaker":"","original":"wird mir klar, es ist falsch","ipa":"/vˌɪɾt miːɾ klˈɑːɾ ɛsɪst fˈalʃ/","en":"I realize it's wrong","zh":"我知道这是一个错误的选择","note":"","sourceLineIndex":6},{"id":"dracula-das-musical-17-007","lineIndex":7,"speaker":"","original":"doch ich geh immer weiter","ipa":"/dɔx ɪç ɡˈeː ˈɪmɜ vˈaɪtɜ/","en":"but I keep going","zh":"而我却越走越远","note":"","sourceLineIndex":7},{"id":"dracula-das-musical-17-008","lineIndex":8,"speaker":"","original":"denn es scheint so als wär er mit mir in Gedanken wie vereint","ipa":"/dɛn ɛs ʃˈaɪnt zoː als vˈɛːɾ ɛɾ mɪt miːɾ ɪn ɡədˈaŋkən viː fɛɾˈaɪnt/","en":"because it seems as if he is united with me in thought","zh":"因为他和我在我的脑海里早已融为一体","note":"","sourceLineIndex":8},{"id":"dracula-das-musical-17-009","lineIndex":9,"speaker":"","original":"Bin wie ein Reh auf der Flucht vor dem Jäger","ipa":"/bɪn viː aɪn rˈeː aʊf dɛɾ flˈʊxt fˌɔɾ deːm jˈɛːɡɜ/","en":"I'm like a deer running away from the hunter","zh":"我就像是一只在森林里被狩猎的小鹿","note":"","sourceLineIndex":9},{"id":"dracula-das-musical-17-010","lineIndex":10,"speaker":"","original":"Schon erschöpft und vielleicht schon bereit mich zu stellen","ipa":"/ʃˌoːn ɛɾʃˈœpft ʊnt fɪlˈaɪçt ʃˌoːn bərˈaɪt mɪç tsuː ʃtˈɛlən/","en":"Already exhausted and perhaps ready to surrender","zh":"早已精疲力尽，已经做好被捕捉的准备了","note":"","sourceLineIndex":10},{"id":"dracula-das-musical-17-011","lineIndex":11,"speaker":"","original":"Warum nicht, wenn das Spiel mit der Angst mir viel spannender erscheint","ipa":"/vɑːrˈʊm nˈɪçt vˌɛn das ʃpˈiːl mɪt dɛɾ ˈaŋst miːɾ fˈiːl ʃpˈanəndɜ ɛɾʃˈaɪnt/","en":"Why not, when playing with fear seems much more exciting to me","zh":"这场让我心生恐惧的游戏似乎比想象中更为刺激","note":"","sourceLineIndex":11},{"id":"dracula-das-musical-17-012","lineIndex":12,"speaker":"","original":"Bitte hilf mir stark zu bleiben gib mir Kraft den Sturm zu überstehen willst du mich untergehen sehen","ipa":"/bˈɪtə hˈɪlf miːɾ ʃtˈaɾk tsuː blˈaɪbən ɡˈiːp miːɾ kɾˈaft deːn ʃtˈʊɐm tsuː ˌyːbɜʃtˈeːən vɪlst duː mɪç ˌʊntɜɡˈeːən zˈeːən/","en":"Please help me stay strong give me strength to weather the storm Do you want to see me sink?","zh":"请给我力量让我可以去经受风暴你愿意看到我消失吗","note":"","sourceLineIndex":12},{"id":"dracula-das-musical-17-015","lineIndex":13,"speaker":"","original":"wie ein Stein","ipa":"/viː aɪn ʃtˈaɪn/","en":"like a stone","zh":"就像一颗星星","note":"","sourceLineIndex":15},{"id":"dracula-das-musical-17-016","lineIndex":14,"speaker":"","original":"Nein, ich bin’s der dich errettet","ipa":"/nˈaɪn ɪç bˈiːns dɛɾ dɪç ɛɾrˈɛtət/","en":"No, it is I who save you","zh":"不，我是被你所救","note":"","sourceLineIndex":16},{"id":"dracula-das-musical-17-017","lineIndex":15,"speaker":"","original":"musst dich wappnen vor dem Untergang","ipa":"/mˈʊst dɪç vˈapnən fˌɔɾ deːm ˌʊntɜɡˈaŋ/","en":"you have to prepare yourself for destruction","zh":"你必须全副武装","note":"","sourceLineIndex":17},{"id":"dracula-das-musical-17-018","lineIndex":16,"speaker":"","original":"wenn es denn sein muss","ipa":"/vˌɛn ɛs dɛn zaɪn mˈʊs/","en":"if it has to be","zh":"如果必须要这样","note":"","sourceLineIndex":18},{"id":"dracula-das-musical-17-019","lineIndex":17,"speaker":"","original":"komm, ich lade dich ein","ipa":"/kˈɔm ɪç lˈɑːdə dɪç ˈaɪn/","en":"come, I invite you","zh":"来吧 我邀请你","note":"","sourceLineIndex":19},{"id":"dracula-das-musical-17-020","lineIndex":18,"speaker":"","original":"Wär ich der Wind, dann jagte ich davon","ipa":"/vˈɛːɾ ɪç dɛɾ vˈɪnt dan jˈɑːktə ɪç dɑːfˈɔn/","en":"If I were the wind, I would run away","zh":"如果我是风，我将会追随你","note":"","sourceLineIndex":20},{"id":"dracula-das-musical-17-021","lineIndex":19,"speaker":"","original":"So weit es nur ging","ipa":"/zoː vˈaɪt ɛs nˈuːɾ ɡˈɪŋ/","en":"As far as possible","zh":"随心所欲","note":"","sourceLineIndex":21},{"id":"dracula-das-musical-17-022","lineIndex":20,"speaker":"","original":"wie lebte ich befreit, für mich allein","ipa":"/viː lˈeːptə ɪç bəfrˈaɪt fyːɾ mɪç alˈaɪn/","en":"how did I live free, for myself alone","zh":"自由自在","note":"","sourceLineIndex":22},{"id":"dracula-das-musical-17-023","lineIndex":21,"speaker":"","original":"doch du, du fängst mich ein","ipa":"/dˈɔx duː duː fˈɛŋst mɪç ˈaɪn/","en":"but you, you catch me","zh":"只有你可以抓住我","note":"","sourceLineIndex":23},{"id":"dracula-das-musical-17-024","lineIndex":22,"speaker":"","original":"denn wär ich der Wind","ipa":"/dɛn vˈɛːɾ ɪç dɛɾ vˈɪnt/","en":"because if I were the wind","zh":"因为我是风","note":"","sourceLineIndex":24},{"id":"dracula-das-musical-17-025","lineIndex":23,"speaker":"","original":"wärst du mein Herr","ipa":"/vˈɛːɾst duː maɪn hˈɛɾ/","en":"if you were my lord","zh":"而你是我的主人","note":"","sourceLineIndex":25},{"id":"dracula-das-musical-17-026","lineIndex":24,"speaker":"","original":"aus allen Teilen dieser Welt käm ich Heim zu dir","ipa":"/ˌaʊs ˈalən tˈaɪlən dˌiːzɜ vˈɛlt kˈɛːm ɪç hˈaɪm tsuː dˈiːɾ/","en":"I come home to you from all parts of this world","zh":"我从世界各地赶来只为你","note":"","sourceLineIndex":26},{"id":"dracula-das-musical-17-027","lineIndex":25,"speaker":"","original":"Ich schwor ihm ewig Treue","ipa":"/ɪç ʃvˈoːɾ iːm ˈeːvɪç tɾˈɔøə/","en":"I swore loyalty to him forever","zh":"我承诺你永远的忠诚","note":"","sourceLineIndex":27},{"id":"dracula-das-musical-17-028","lineIndex":26,"speaker":"","original":"wollt ihn für immer lieben","ipa":"/vɔlt iːn fyːɾ ˈɪmɜ lˈiːbən/","en":"wanted to love him forever","zh":"我承诺你永恒的爱恋","note":"","sourceLineIndex":28},{"id":"dracula-das-musical-17-029","lineIndex":27,"speaker":"","original":"und dennoch lass ich es geschehen","ipa":"/ʊnt dˈɛnɔx lˈas ɪç ɛs ɡəʃˈeːən/","en":"and yet I let it happen","zh":"这些都将会实现","note":"","sourceLineIndex":29},{"id":"dracula-das-musical-17-030","lineIndex":28,"speaker":"","original":"wie könnt ich ihn betrügen und unsre Liebe hintergehen","ipa":"/viː kˌœnt ɪç iːn bətɾˈyːɡən ʊnt ˌʊnzrə lˈiːbə hˌɪntɜɡˈeːən/","en":"How can I cheat on him and betray our love?","zh":"我怎么能欺骗他，欺骗我们的爱","note":"","sourceLineIndex":30},{"id":"dracula-das-musical-17-031","lineIndex":29,"speaker":"","original":"Wär ich der Wind, dann jagte ich davon","ipa":"/vˈɛːɾ ɪç dɛɾ vˈɪnt dan jˈɑːktə ɪç dɑːfˈɔn/","en":"If I were the wind, I would run away","zh":"如果我是风，我将会追你","note":"","sourceLineIndex":31},{"id":"dracula-das-musical-17-032","lineIndex":30,"speaker":"","original":"So weit es nur ging","ipa":"/zoː vˈaɪt ɛs nˈuːɾ ɡˈɪŋ/","en":"As far as possible","zh":"随心所欲","note":"","sourceLineIndex":32},{"id":"dracula-das-musical-17-033","lineIndex":31,"speaker":"","original":"wie lebte ich befreit, für mich allein","ipa":"/viː lˈeːptə ɪç bəfrˈaɪt fyːɾ mɪç alˈaɪn/","en":"how did I live free, for myself alone","zh":"自由自在","note":"","sourceLineIndex":33},{"id":"dracula-das-musical-17-034","lineIndex":32,"speaker":"","original":"doch du, du fängst mich ein","ipa":"/dˈɔx duː duː fˈɛŋst mɪç ˈaɪn/","en":"but you, you catch me","zh":"只有你可以抓住我","note":"","sourceLineIndex":34},{"id":"dracula-das-musical-17-035","lineIndex":33,"speaker":"","original":"denn wär ich der Wind","ipa":"/dɛn vˈɛːɾ ɪç dɛɾ vˈɪnt/","en":"because if I were the wind","zh":"因为我是风","note":"","sourceLineIndex":35},{"id":"dracula-das-musical-17-036","lineIndex":34,"speaker":"","original":"wärst du mein Herr","ipa":"/vˈɛːɾst duː maɪn hˈɛɾ/","en":"if you were my lord","zh":"而你是我的主人","note":"","sourceLineIndex":36},{"id":"dracula-das-musical-17-037","lineIndex":35,"speaker":"","original":"aus allen Teilen dieser Welt käm ich Heim","ipa":"/ˌaʊs ˈalən tˈaɪlən dˌiːzɜ vˈɛlt kˈɛːm ɪç hˈaɪm/","en":"I come home from all parts of the world","zh":"我从世界各地赶来","note":"","sourceLineIndex":37},{"id":"dracula-das-musical-17-038","lineIndex":36,"speaker":"","original":"zu dir","ipa":"/tsuː dˈiːɾ/","en":"to you","zh":"只为你","note":"","sourceLineIndex":38}],"sourceOrder":17,"displayOrder":16},{"order":18,"id":"18-die-verfuhrung","title":"Die Verführung","titleZh":"诱惑","lines":[{"id":"dracula-das-musical-18-001","lineIndex":1,"speaker":"","original":"Niemals war ich sichrer","ipa":"/nˈiːmɑːls vɑːɾ ɪç zˈɪçrɜ/","en":"I have never been safer","zh":"我从未如此确信","note":"","sourceLineIndex":1},{"id":"dracula-das-musical-18-002","lineIndex":2,"speaker":"","original":"Niemals mehr bereit","ipa":"/nˈiːmɑːls mˈeːɾ bərˈaɪt/","en":"Never more ready","zh":"亦做好准备","note":"","sourceLineIndex":2},{"id":"dracula-das-musical-18-003","lineIndex":3,"speaker":"","original":"Du allein, sollst mein Engel sein","ipa":"/duː alˈaɪn zˌɔlst maɪn ˈɛŋəl zaɪn/","en":"You alone shall be my angel","zh":"只你一人，应是我的天使","note":"","sourceLineIndex":3},{"id":"dracula-das-musical-18-004","lineIndex":4,"speaker":"","original":"heut und in Ewigkeit","ipa":"/hˈɔøt ʊnt ɪn ˈeːvɪçkˌaɪt/","en":"today and forever","zh":"今日如此，夜夜皆然","note":"","sourceLineIndex":4},{"id":"dracula-das-musical-18-005","lineIndex":5,"speaker":"","original":"Du allein bist mein Ende, mein Beginn","ipa":"/duː alˈaɪn bɪst maɪn ˈɛndə maɪn bəɡˈɪn/","en":"You alone are my end, my beginning","zh":"你是我的新生，也是归宿","note":"","sourceLineIndex":5},{"id":"dracula-das-musical-18-006","lineIndex":6,"speaker":"","original":"gibst dem Leben neuen Sinn","ipa":"/ɡˈiːpst deːm lˈeːbən nˈɔøən zˈɪn/","en":"give new meaning to life","zh":"给予我生命全新的意义","note":"","sourceLineIndex":6},{"id":"dracula-das-musical-18-007","lineIndex":7,"speaker":"","original":"wir sind ein Fleisch und Blut","ipa":"/viːɾ zɪnt aɪn flˈaɪʃ ʊnt blˈuːt/","en":"we are one flesh and blood","zh":"我们的骨血相融","note":"","sourceLineIndex":7},{"id":"dracula-das-musical-18-008","lineIndex":8,"speaker":"","original":"allezeit","ipa":"/ˈaleːtsˌaɪt/","en":"at all times","zh":"永远如此","note":"","sourceLineIndex":8},{"id":"dracula-das-musical-18-009","lineIndex":9,"speaker":"","original":"Ich befahl Armeen","ipa":"/ɪç bəfˈɑːl aɾmˈeːən/","en":"I commanded armies","zh":"我曾统领军队","note":"","sourceLineIndex":9},{"id":"dracula-das-musical-18-010","lineIndex":10,"speaker":"","original":"schlug den Feind im Krieg","ipa":"/ʃlˈuːk deːn fˈaɪnt ɪm kɾˈiːk/","en":"defeated the enemy in war","zh":"在战役中击溃敌人","note":"","sourceLineIndex":10},{"id":"dracula-das-musical-18-011","lineIndex":11,"speaker":"","original":"doch ich seh wenn ich vor dir steh","ipa":"/dɔx ɪç zˈeː vˌɛn ɪç fˌɔɾ diːɾ ʃtˈeː/","en":"but I see when I stand in front of you","zh":"但当我见到你","note":"","sourceLineIndex":11},{"id":"dracula-das-musical-18-012","lineIndex":12,"speaker":"","original":"Kriege und Sieg","ipa":"/kɾˈiːɡə ʊnt zˈiːk/","en":"Wars and victory","zh":"战争与凯旋","note":"","sourceLineIndex":12},{"id":"dracula-das-musical-18-013","lineIndex":13,"speaker":"","original":"Sind wertloses Glück","ipa":"/zɪnt vˈɛɾtloːzəs ɡlˈʏk/","en":"Are worthless happiness","zh":"都是虚妄的愉悦","note":"","sourceLineIndex":13},{"id":"dracula-das-musical-18-014","lineIndex":14,"speaker":"","original":"eitles und wertloses Glück","ipa":"/ˈaɪtləs ʊnt vˈɛɾtloːzəs ɡlˈʏk/","en":"vain and worthless happiness","zh":"空虚和毫无意义的荣光","note":"","sourceLineIndex":14},{"id":"dracula-das-musical-18-015","lineIndex":15,"speaker":"","original":"Lass mich dich nicht lieben","ipa":"/lˈas mɪç dɪç nˈɪçt lˈiːbən/","en":"Don't make me love you","zh":"别让我爱你","note":"","sourceLineIndex":15},{"id":"dracula-das-musical-18-016","lineIndex":16,"speaker":"","original":"lass mich nicht begehren","ipa":"/lˈas mɪç nˈɪçt bəɡˈeːrən/","en":"don't let me desire","zh":"别让我怀抱期望","note":"","sourceLineIndex":16},{"id":"dracula-das-musical-18-017","lineIndex":17,"speaker":"","original":"was ich zu begehren schon lange vermag","ipa":"/vˈas ɪç tsuː bəɡˈeːrən ʃˌoːn lˈaŋə fɛɾmˈɑːk/","en":"what I have been wanting for a long time","zh":"木已成舟，我所渴求的早已静候","note":"","sourceLineIndex":17},{"id":"dracula-das-musical-18-018","lineIndex":18,"speaker":"","original":"ich laufe durch den Nebel näher an den Abgrund","ipa":"/ɪç lˈaʊfə dʊɐç deːn nˈeːbəl nˈɛːɜ an deːn ˈapɡɾˌʊnt/","en":"I run through the fog closer to the abyss","zh":"我在迷雾中狂奔，愈发逼近悬崖","note":"","sourceLineIndex":18},{"id":"dracula-das-musical-18-019","lineIndex":19,"speaker":"","original":"bin ich nun verbannt von dem hellichten Tag","ipa":"/bɪn ɪç nˈuːn fɛɾbˈant fɔn deːm hˈɛlɪçtən tˈɑːk/","en":"I am now banished from broad daylight","zh":"是否现在就是我放弃日光之时","note":"","sourceLineIndex":19},{"id":"dracula-das-musical-18-020","lineIndex":20,"speaker":"","original":"Mein Stern kennt keinen Untergang","ipa":"/maɪn ʃtˈɛɾn kˈɛnt kˈaɪnən ˌʊntɜɡˈaŋ/","en":"My star knows no setting","zh":"我的星辰永不坠落","note":"","sourceLineIndex":20},{"id":"dracula-das-musical-18-021","lineIndex":21,"speaker":"","original":"so können wir dem Tod entfliehen","ipa":"/zoː kˌœnən viːɾ deːm tˈoːt ɛntflˈiːən/","en":"this is how we can escape death","zh":"我们可以远离死亡","note":"","sourceLineIndex":21},{"id":"dracula-das-musical-18-022","lineIndex":22,"speaker":"","original":"wir leben ohne Zeit in Ewigkeit","ipa":"/viːɾ lˈeːbən ˈoːnə tsˈaɪt ɪn ˈeːvɪçkˌaɪt/","en":"we live forever without time","zh":"我们将在永恒之中存活","note":"","sourceLineIndex":22},{"id":"dracula-das-musical-18-023","lineIndex":23,"speaker":"","original":"denn meine Liebe heißt Unsterblichkeit","ipa":"/dɛn mˌaɪnə lˈiːbə hˈaɪst ˈʊnʃtˌɛɾplɪçkˌaɪt/","en":"because my love is called immortality","zh":"我的爱将亘古不变","note":"","sourceLineIndex":23},{"id":"dracula-das-musical-18-024","lineIndex":24,"speaker":"","original":"Ich teil mit dir mein Bett","ipa":"/ɪç tˈaɪl mɪt diːɾ maɪn bˈɛt/","en":"I share my bed with you","zh":"我与你共享栖身之所","note":"","sourceLineIndex":24},{"id":"dracula-das-musical-18-025","lineIndex":25,"speaker":"","original":"ich teil mit dir mein Blut","ipa":"/ɪç tˈaɪl mɪt diːɾ maɪn blˈuːt/","en":"I share my blood with you","zh":"共享血脉","note":"","sourceLineIndex":25},{"id":"dracula-das-musical-18-026","lineIndex":26,"speaker":"","original":"wir wanken nicht im Sturm","ipa":"/viːɾ vˈaŋkən nˈɪçt ɪm ʃtˈʊɐm/","en":"we do not waver in the storm","zh":"风暴与时间的浪潮","note":"","sourceLineIndex":26},{"id":"dracula-das-musical-18-027","lineIndex":27,"speaker":"","original":"nicht in der Zeit und Flut","ipa":"/nˈɪçt ɪn dɛɾ tsˈaɪt ʊnt flˈuːt/","en":"not in time and tide","zh":"不会让我们举步维艰","note":"","sourceLineIndex":27},{"id":"dracula-das-musical-18-028","lineIndex":28,"speaker":"","original":"soll diese Welt vergehen","ipa":"/zˌɔl dˌiːzə vˈɛlt fɛɾɡˈeːən/","en":"this world shall perish","zh":"世事变迁","note":"","sourceLineIndex":28},{"id":"dracula-das-musical-18-029","lineIndex":29,"speaker":"","original":"die unsre bleibt bestehen","ipa":"/diː ˌʊnzrə blˈaɪpt bəʃtˈeːən/","en":"ours remains","zh":"而我们将永生","note":"","sourceLineIndex":29},{"id":"dracula-das-musical-18-030","lineIndex":30,"speaker":"","original":"Der Stern wird niemals sinken","ipa":"/dɛɾ ʃtˈɛɾn vˌɪɾt nˈiːmɑːls zˈɪŋkən/","en":"The star will never sink","zh":"我的星辰永不沉没","note":"","sourceLineIndex":30},{"id":"dracula-das-musical-18-031","lineIndex":31,"speaker":"","original":"In Leben liegt Geborgenheit","ipa":"/ɪn lˈeːbən lˈiːkt ɡəbˈɔɾɡənhˌaɪt/","en":"There is security in life","zh":"日光中的生活是我的庇护","note":"","sourceLineIndex":31},{"id":"dracula-das-musical-18-032","lineIndex":32,"speaker":"","original":"er macht mich schwach und willenlos","ipa":"/ɛɾ mˈaxt mɪç ʃvˈax ʊnt vˈɪlənlˌoːs/","en":"he makes me weak and weak-willed","zh":"他让我如此软弱，无法自持","note":"","sourceLineIndex":32},{"id":"dracula-das-musical-18-033","lineIndex":33,"speaker":"","original":"Ich sehe deine Augen sagen ja","ipa":"/ɪç zˈeːə dˌaɪnə ˈaʊɡən zˈɑːɡən jˈɑː/","en":"I see your eyes say yes","zh":"你的目光已答允我","note":"","sourceLineIndex":33},{"id":"dracula-das-musical-18-034","lineIndex":34,"speaker":"","original":"sie stellen die verwirrten Worte klar","ipa":"/ziː ʃtˈɛlən diː fɛɾvˈɪɾtən vˈɔɾtə klˈɑːɾ/","en":"they clarify the confused words","zh":"你话语混乱，意志却已作出抉择","note":"","sourceLineIndex":34},{"id":"dracula-das-musical-18-035","lineIndex":35,"speaker":"","original":"sie sagen was du fühlst","ipa":"/ziː zˈɑːɡən vˈas duː fˈyːlst/","en":"they say what you feel","zh":"它们讲出了你的感受","note":"","sourceLineIndex":35},{"id":"dracula-das-musical-18-036","lineIndex":36,"speaker":"","original":"und was du fühlen willst","ipa":"/ʊnt vˈas duː fˈyːlən vɪlst/","en":"and what you want to feel","zh":"你想要的一切","note":"","sourceLineIndex":36},{"id":"dracula-das-musical-18-037","lineIndex":37,"speaker":"","original":"zwei Körper ziehn sich an","ipa":"/tsvˈaɪ kˈœɾpɜ tsˈiːn zɪç ˈan/","en":"two bodies attract each other","zh":"两人互相吸引","note":"","sourceLineIndex":37},{"id":"dracula-das-musical-18-038","lineIndex":38,"speaker":"","original":"und ändern ihre Bahn","ipa":"/ʊnt ˈɛndɜn ˌiːrə bˈɑːn/","en":"and change their path","zh":"改变余生的轨迹","note":"","sourceLineIndex":38},{"id":"dracula-das-musical-18-039","lineIndex":39,"speaker":"","original":"sie sterben und als Stern","ipa":"/ziː ʃtˈɛɾbən ʊnt als ʃtˈɛɾn/","en":"they die and as a star","zh":"你死去的同时","note":"","sourceLineIndex":39},{"id":"dracula-das-musical-18-040","lineIndex":40,"speaker":"","original":"erstehen sie vom Neuen","ipa":"/ɛɾʃtˈeːən ziː fɔm nˈɔøən/","en":"they arise from the new","zh":"我将赋予你新生","note":"","sourceLineIndex":40},{"id":"dracula-das-musical-18-041","lineIndex":41,"speaker":"","original":"Der Stern wird niemals sinken","ipa":"/dɛɾ ʃtˈɛɾn vˌɪɾt nˈiːmɑːls zˈɪŋkən/","en":"The star will never sink","zh":"我们的星辰将永不沉没","note":"","sourceLineIndex":41},{"id":"dracula-das-musical-18-042","lineIndex":42,"speaker":"","original":"Der Stern wird niemals sinken","ipa":"/dɛɾ ʃtˈɛɾn vˌɪɾt nˈiːmɑːls zˈɪŋkən/","en":"The star will never sink","zh":"星辰永不沉没","note":"","sourceLineIndex":42},{"id":"dracula-das-musical-18-043","lineIndex":43,"speaker":"","original":"Der Stern wird nie vergehn","ipa":"/dɛɾ ʃtˈɛɾn vˌɪɾt nˈiː fɛɾɡˈeːn/","en":"The star will never fade","zh":"星光永不消逝","note":"","sourceLineIndex":43},{"id":"dracula-das-musical-18-044","lineIndex":44,"speaker":"","original":"Nun kein Zurück mehr","ipa":"/nˈuːn kˈaɪn tsuːrˈʏk mˈeːɾ/","en":"Now no turning back","zh":"如今已无回头之路","note":"","sourceLineIndex":44},{"id":"dracula-das-musical-18-045","lineIndex":45,"speaker":"","original":"die Brücken brechen ein","ipa":"/diː bɾˈʏkən bɾˈɛçən ˈaɪn/","en":"the bridges collapse","zh":"桥梁焚毁崩塌","note":"","sourceLineIndex":45},{"id":"dracula-das-musical-18-046","lineIndex":46,"speaker":"","original":"alles will ich dafür geben","ipa":"/ˈaləs vɪl ɪç dɑːfˈyːɾ ɡˈeːbən/","en":"I want to give everything for it","zh":"我愿交付一切","note":"","sourceLineIndex":46},{"id":"dracula-das-musical-18-047","lineIndex":47,"speaker":"","original":"um bei dir zu sein","ipa":"/ʊm baɪ diːɾ tsuː zˈaɪn/","en":"to be with you","zh":"只为伴你同行","note":"","sourceLineIndex":47},{"id":"dracula-das-musical-18-048","lineIndex":48,"speaker":"","original":"Nun steh in meinem Bann","ipa":"/nˈuːn ʃtˈeː ɪn mˌaɪnəm bˈan/","en":"Now stand under my spell","zh":"在我的爱欲之中","note":"","sourceLineIndex":48},{"id":"dracula-das-musical-18-049","lineIndex":49,"speaker":"","original":"und nimm mich an als unbezwingbare Macht","ipa":"/ʊnt nˈɪm mɪç an als ˈʊnbətsvˌɪŋbɑːrə mˈaxt/","en":"and accept me as an invincible power","zh":"用你那无可抵挡的力量占有我","note":"","sourceLineIndex":49},{"id":"dracula-das-musical-18-050","lineIndex":50,"speaker":"","original":"mein Wunsch ist erfüllt nun","ipa":"/maɪn vˈʊnʃ ɪst ɛɾfˈʏlt nˈuːn/","en":"my wish is now fulfilled","zh":"此刻我的愿望已餍足","note":"","sourceLineIndex":50},{"id":"dracula-das-musical-18-051","lineIndex":51,"speaker":"","original":"der Nebel verhört nun die ewige Liebe der Nacht","ipa":"/dɛɾ nˈeːbəl fɛɾhˈœɾt nˈuːn diː ˈeːvɪɡə lˈiːbə dɛɾ nˈaxt/","en":"the fog now interrogates the eternal love of the night","zh":"在浓雾的见证下，属于黑夜的，我们永恒的爱","note":"","sourceLineIndex":51}],"sourceOrder":18,"displayOrder":17},{"order":19,"id":"19-zu-ende","title":"Zu Ende","titleZh":"终结","lines":[{"id":"dracula-das-musical-19-001","lineIndex":1,"speaker":"","original":"Zu Ende","ipa":"/tsuː ˈɛndə/","en":"Over","zh":"都结束了","note":"","sourceLineIndex":1},{"id":"dracula-das-musical-19-002","lineIndex":2,"speaker":"","original":"Sie gehört nur zu mir, alter Narr","ipa":"/ziː ɡəhˈœɾt nˈuːɾ tsuː mˈiːɾ ˈaltɜ nˈaɾ/","en":"She belongs only to me, old fool","zh":"她只属于我，你这老傻瓜","note":"","sourceLineIndex":2},{"id":"dracula-das-musical-19-003","lineIndex":3,"speaker":"","original":"Viel zu spät für dein Heldentum","ipa":"/fˈiːl tsuː ʃpˈɛːt fyːɾ daɪn hˈɛldəntˌuːm/","en":"Far too late for your heroism","zh":"想英雄救美，但已经太晚了","note":"","sourceLineIndex":3},{"id":"dracula-das-musical-19-004","lineIndex":4,"speaker":"","original":"Mach dich besser davon oder stirb","ipa":"/mˈax dɪç bˈɛsɜ dɑːfˈɔn ˌoːdɜ ʃtˈɪɾp/","en":"You better get going or die","zh":"不想死的话，你最好再做的好一点","note":"","sourceLineIndex":4},{"id":"dracula-das-musical-19-005","lineIndex":5,"speaker":"","original":"Viel Qual für ein bisschen Ruhm","ipa":"/fˈiːl kvˈɑːl fyːɾ aɪn bˈɪsçən rˈuːm/","en":"A lot of pain for a little glory","zh":"你给自己找了一堆麻烦，只为得到几句称赞","note":"","sourceLineIndex":5},{"id":"dracula-das-musical-19-006","lineIndex":6,"speaker":"","original":"Dein Leben war vergeudet ohne Lohn und Dank","ipa":"/daɪn lˈeːbən vɑːɾ fɛɾɡəˈuːdət ˈoːnə lˈoːn ʊnt dˈaŋk/","en":"Your life was wasted without reward or thanks","zh":"没有人感谢你，你的人生全是白费","note":"","sourceLineIndex":6},{"id":"dracula-das-musical-19-007","lineIndex":7,"speaker":"","original":"Sie wird niemals wie du, gib sie auf","ipa":"/ziː vˌɪɾt nˈiːmɑːls viː duː ɡˈiːp ziː ˈaʊf/","en":"She will never be like you, give up on her","zh":"她绝不会像你一样，放开她","note":"","sourceLineIndex":7},{"id":"dracula-das-musical-19-008","lineIndex":8,"speaker":"","original":"Ich behüte und schütze sie","ipa":"/ɪç bəhˈyːtə ʊnt ʃˈʏtsə ziː/","en":"I protect and protect her","zh":"我会保护和守卫她","note":"","sourceLineIndex":8},{"id":"dracula-das-musical-19-009","lineIndex":9,"speaker":"","original":"Deine Zeit ist vorbei, du vergehst","ipa":"/dˌaɪnə tsˈaɪt ɪst foːɾbˈaɪ duː fɛɾɡˈeːst/","en":"Your time is over, you are fading away","zh":"你的时代已经结束，你只是在垂死挣扎","note":"","sourceLineIndex":9},{"id":"dracula-das-musical-19-010","lineIndex":10,"speaker":"","original":"Keine Seele folgt dir ins Grab","ipa":"/kˈaɪnə zˈeːlə fˈɔlkt diːɾ ɪns ɡɾˈɑːp/","en":"No soul will follow you to the grave","zh":"休想再拉别人的灵魂做你的陪葬","note":"","sourceLineIndex":10},{"id":"dracula-das-musical-19-011","lineIndex":11,"speaker":"","original":"Ich sah schon viele Monster","ipa":"/ɪç zˈɑː ʃˌoːn fˈiːlə mˈoːnstɜ/","en":"I've seen a lot of monsters","zh":"我战胜过无数的怪物","note":"","sourceLineIndex":11},{"id":"dracula-das-musical-19-012","lineIndex":12,"speaker":"","original":"Keines war so krank","ipa":"/kˈaɪnəs vɑːɾ zoː kɾˈaŋk/","en":"Nobody was that sick","zh":"你是最弱的一个","note":"","sourceLineIndex":12},{"id":"dracula-das-musical-19-013","lineIndex":13,"speaker":"","original":"Zu Ende","ipa":"/tsuː ˈɛndə/","en":"Over","zh":"都结束了","note":"","sourceLineIndex":13},{"id":"dracula-das-musical-19-014","lineIndex":14,"speaker":"","original":"Zu Ende, dein Spiel ist aus","ipa":"/tsuː ˈɛndə daɪn ʃpˈiːl ɪst ˈaʊs/","en":"Over, your game is over","zh":"都结束了，你的游戏已经结束","note":"","sourceLineIndex":14},{"id":"dracula-das-musical-19-015","lineIndex":15,"speaker":"","original":"Warum gibst du nicht freiwillig auf","ipa":"/vɑːrˈʊm ɡˈiːpst duː nˈɪçt frˈaɪvɪlˌɪç ˈaʊf/","en":"Why don't you give up voluntarily","zh":"你伤不了我，放弃吧","note":"","sourceLineIndex":15},{"id":"dracula-das-musical-19-016","lineIndex":16,"speaker":"","original":"Kommt auf‘s Selbe hinaus","ipa":"/kˈɔmt ˈaʊfs zˈɛlbə hɪnˈaʊs/","en":"It comes to the same thing","zh":"还不乖乖认输","note":"","sourceLineIndex":16},{"id":"dracula-das-musical-19-017","lineIndex":17,"speaker":"","original":"Zu Ende, das weißt du nur all zu gut","ipa":"/tsuː ˈɛndə das vˈaɪst duː nˈuːɾ ˈal tsuː ɡˈuːt/","en":"Over, you know that all too well","zh":"都结束了，别再做你的美梦","note":"","sourceLineIndex":17},{"id":"dracula-das-musical-19-018","lineIndex":18,"speaker":"","original":"Denn der eine der siegen wird, ist des anderen Tod","ipa":"/dɛn dɛɾ ˌaɪnə dɛɾ zˈiːɡən vˌɪɾt ɪst dɛs ˈandərən tˈoːt/","en":"For the one who conquers is the death of the other","zh":"我们中的一个取得胜利之时，就是另一个的死期","note":"","sourceLineIndex":18},{"id":"dracula-das-musical-19-019","lineIndex":19,"speaker":"","original":"Bist du wirklich so klug, wie du glaubst","ipa":"/bɪst duː vˈɪɾklɪç zoː klˈuːk viː duː ɡlˈaʊpst/","en":"Are you really as smart as you think you are?","zh":"如此聪明的你难道真的相信","note":"","sourceLineIndex":19},{"id":"dracula-das-musical-19-020","lineIndex":20,"speaker":"","original":"Deine Bücher was nützen die","ipa":"/dˌaɪnə bˈyːçɜ vˈas nˈʏtsən diː/","en":"Your books, what use are they?","zh":"你那些破书上的陈词滥调","note":"","sourceLineIndex":20},{"id":"dracula-das-musical-19-021","lineIndex":21,"speaker":"","original":"Wenn die Dunkelheit siegt über‘s Licht","ipa":"/vˌɛn diː dˈʊnkəlhˌaɪt zˈiːkt ˈyːbeːɾs lˈɪçt/","en":"When darkness triumphs over light","zh":"睁眼看看，我的黑暗已经吞噬了一切","note":"","sourceLineIndex":21},{"id":"dracula-das-musical-19-022","lineIndex":22,"speaker":"","original":"Jeden Augenblick wirst du zu Staub","ipa":"/jˈeːdən ˈaʊɡənblˌɪk vˌɪɾst duː tsuː ʃtˈaʊp/","en":"Every moment you turn to dust","zh":"每一分钟你都更接近尘土","note":"","sourceLineIndex":22},{"id":"dracula-das-musical-19-023","lineIndex":23,"speaker":"","original":"Und deine Greueltaten sind fortan vorbei","ipa":"/ʊnt dˌaɪnə ɡɾˌɔøəltˈɑːtən zɪnt fɔɾtˈɑːn foːɾbˈaɪ/","en":"And your atrocities are now over","zh":"你的残暴将被历史遗忘","note":"","sourceLineIndex":23},{"id":"dracula-das-musical-19-024","lineIndex":24,"speaker":"","original":"Ich bin noch lange nicht tot","ipa":"/ɪç bɪn nɔx lˈaŋə nˈɪçt tˈoːt/","en":"I'm far from dead","zh":"我永远都不会死亡和毁灭","note":"","sourceLineIndex":24},{"id":"dracula-das-musical-19-025","lineIndex":25,"speaker":"","original":"Und vergeh mich am Blut eurer Kinderschar","ipa":"/ʊnt fɛɾɡˈeː mɪç am blˈuːt ˈɔørɜ kˈɪndɜʃˌɑːɾ/","en":"And commit the blood of your children","zh":"只要我从你们的子孙身上吸取血液","note":"","sourceLineIndex":25},{"id":"dracula-das-musical-19-026","lineIndex":26,"speaker":"","original":"Ihr schaut zu aus dem Grab wenn ich‘s tu","ipa":"/iːɾ ʃˈaʊt tsuː ˌaʊs deːm ɡɾˈɑːp vˌɛn ˈɪçs tˈuː/","en":"You watch from the grave when I do it","zh":"你们只能从坟墓里眼睁睁看着我做的一切","note":"","sourceLineIndex":26},{"id":"dracula-das-musical-19-027","lineIndex":27,"speaker":"","original":"Denn ihr lebt nur elendig kurz, in Demut und in Tugend","ipa":"/dɛn iːɾ lˈeːpt nˈuːɾ ˈeːlɛndˌɪç kˈʊɐts ɪn dˈeːmuːt ʊnt ɪn tˈuːɡənt/","en":"For your lives are miserably short, in humility and virtue","zh":"你们那仁慈和虔诚的生命是如此可悲地短暂","note":"","sourceLineIndex":27},{"id":"dracula-das-musical-19-028","lineIndex":28,"speaker":"","original":"Ich jedoch bin frei","ipa":"/ɪç jˈeːdɔx bɪn frˈaɪ/","en":"However, I am free","zh":"而我仍为所欲为","note":"","sourceLineIndex":28},{"id":"dracula-das-musical-19-029","lineIndex":29,"speaker":"","original":"Zu Ende","ipa":"/tsuː ˈɛndə/","en":"Over","zh":"都结束了","note":"","sourceLineIndex":29},{"id":"dracula-das-musical-19-030","lineIndex":30,"speaker":"","original":"Zu Ende","ipa":"/tsuː ˈɛndə/","en":"Over","zh":"都结束了","note":"","sourceLineIndex":30},{"id":"dracula-das-musical-19-031","lineIndex":31,"speaker":"","original":"Dein Spiel ist aus","ipa":"/daɪn ʃpˈiːl ɪst ˈaʊs/","en":"Your game is over","zh":"你的游戏已经结束","note":"","sourceLineIndex":31},{"id":"dracula-das-musical-19-032","lineIndex":32,"speaker":"","original":"Warum gibst du nicht freiwillig auf","ipa":"/vɑːrˈʊm ɡˈiːpst duː nˈɪçt frˈaɪvɪlˌɪç ˈaʊf/","en":"Why don't you give up voluntarily","zh":"你伤不了我，放弃吧","note":"","sourceLineIndex":32},{"id":"dracula-das-musical-19-033","lineIndex":33,"speaker":"","original":"Kommt auf‘s Selbe hinaus","ipa":"/kˈɔmt ˈaʊfs zˈɛlbə hɪnˈaʊs/","en":"It comes to the same thing","zh":"还不乖乖认输","note":"","sourceLineIndex":33},{"id":"dracula-das-musical-19-034","lineIndex":34,"speaker":"","original":"Zu Ende","ipa":"/tsuː ˈɛndə/","en":"Over","zh":"都结束了","note":"","sourceLineIndex":34},{"id":"dracula-das-musical-19-035","lineIndex":35,"speaker":"","original":"Das weißt du nur all zu gut","ipa":"/das vˈaɪst duː nˈuːɾ ˈal tsuː ɡˈuːt/","en":"You know that all too well","zh":"别再做你的美梦","note":"","sourceLineIndex":35},{"id":"dracula-das-musical-19-036","lineIndex":36,"speaker":"","original":"Denn der eine der siegen wird, ist des anderen Tod","ipa":"/dɛn dɛɾ ˌaɪnə dɛɾ zˈiːɡən vˌɪɾt ɪst dɛs ˈandərən tˈoːt/","en":"For the one who conquers is the death of the other","zh":"我们中的一个取得胜利之时，就是另一个的死期","note":"","sourceLineIndex":36},{"id":"dracula-das-musical-19-037","lineIndex":37,"speaker":"","original":"Gleich was du zu sagen hast, mach dich auf den Tod gefasst","ipa":"/ɡlˈaɪç vˈas duː tsuː zˈɑːɡən hast mˈax dɪç aʊf deːn tˈoːt ɡəfˈast/","en":"No matter what you have to say, prepare to die","zh":"那就是所你已经准备好等死了","note":"","sourceLineIndex":37},{"id":"dracula-das-musical-19-038","lineIndex":38,"speaker":"","original":"Hab dein Lebenswerk zerstört, weil der Sieg nun mir gehört","ipa":"/hˈɑːp daɪn lˈeːbənsvˌɛɾk tsɛɾʃtˈœɾt vˌaɪl dɛɾ zˈiːk nˈuːn miːɾ ɡəhˈœɾt/","en":"I destroyed your life's work because the victory is now mine","zh":"你所做的都是白费功夫，因为胜利只属于我","note":"","sourceLineIndex":38},{"id":"dracula-das-musical-19-039","lineIndex":39,"speaker":"","original":"Sag mir, wie du sterben willst","ipa":"/zˈɑːk mˈiːɾ viː duː ʃtˈɛɾbən vɪlst/","en":"Tell me how you want to die","zh":"说吧，你想要什么死法","note":"","sourceLineIndex":39},{"id":"dracula-das-musical-19-040","lineIndex":40,"speaker":"","original":"Bald schon seh‘ ich wie du zerfällst","ipa":"/bˈalt ʃˌoːn zˈeː ɪç viː duː tsɛɾfˈɛlst/","en":"Soon I'll see how you fall apart","zh":"那就让我先看到你的灭亡","note":"","sourceLineIndex":40},{"id":"dracula-das-musical-19-041","lineIndex":41,"speaker":"","original":"Zu Ende, zu Ende","ipa":"/tsuː ˈɛndə tsuː ˈɛndə/","en":"Over, over","zh":"都结束了，都结束了","note":"","sourceLineIndex":41},{"id":"dracula-das-musical-19-042","lineIndex":42,"speaker":"","original":"Dein Spiel ist aus","ipa":"/daɪn ʃpˈiːl ɪst ˈaʊs/","en":"Your game is over","zh":"你的游戏已经结束","note":"","sourceLineIndex":42},{"id":"dracula-das-musical-19-043","lineIndex":43,"speaker":"","original":"Warum gibst du nicht freiwillig auf","ipa":"/vɑːrˈʊm ɡˈiːpst duː nˈɪçt frˈaɪvɪlˌɪç ˈaʊf/","en":"Why don't you give up voluntarily","zh":"你伤不了我，放弃吧","note":"","sourceLineIndex":43},{"id":"dracula-das-musical-19-044","lineIndex":44,"speaker":"","original":"Kommt aufs selbe hinaus","ipa":"/kˈɔmt aʊfs zˈɛlbə hɪnˈaʊs/","en":"It comes to the same thing","zh":"还不乖乖认输","note":"","sourceLineIndex":44},{"id":"dracula-das-musical-19-045","lineIndex":45,"speaker":"","original":"Zu Ende, das weißt du nur all zu gut","ipa":"/tsuː ˈɛndə das vˈaɪst duː nˈuːɾ ˈal tsuː ɡˈuːt/","en":"Over, you know that all too well","zh":"都结束了，别再做你的美梦","note":"","sourceLineIndex":45},{"id":"dracula-das-musical-19-046","lineIndex":46,"speaker":"","original":"Denn der eine der siegen wird, ist des anderen Tod","ipa":"/dɛn dɛɾ ˌaɪnə dɛɾ zˈiːɡən vˌɪɾt ɪst dɛs ˈandərən tˈoːt/","en":"For the one who conquers is the death of the other","zh":"我们中的一个取得胜利之时，就是另一个的死期","note":"","sourceLineIndex":46},{"id":"dracula-das-musical-19-047","lineIndex":47,"speaker":"","original":"Und bald sieht alle Welt, wer gewinnt und wer fällt","ipa":"/ʊnt bˈalt zˈiːt ˈalə vˈɛlt vˈeːɾ ɡəvˈɪnt ʊnt vˈeːɾ fˈɛlt/","en":"And soon everyone will see who wins and who falls","zh":"这个世界很快就会明白，谁能够笑到最后！","note":"","sourceLineIndex":47}],"sourceOrder":19,"displayOrder":18},{"order":20,"id":"20-jonathans-versprechen","title":"Jonathans Versprechen","titleZh":"乔纳森的承诺","lines":[{"id":"dracula-das-musical-20-001","lineIndex":1,"speaker":"","original":"Es darf niemals geschehen und kame doch der Tag so schwore ich zu tun was du verlangst.","ipa":"/ɛs dˈaɾf nˈiːmɑːls ɡəʃˈeːən ʊnt kˌɑːmə dɔx dɛɾ tˈɑːk zoː ʃvˈoːrə ɪç tsuː tˈuːn vˈas duː fɛɾlˈaŋst/","en":"It must never happen and the day would come so I swore to do what you ask for.","zh":"这本绝不该发生但假使那一天来临我发誓我会这么做正如你所要求的一般","note":"","sourceLineIndex":1},{"id":"dracula-das-musical-20-005","lineIndex":2,"speaker":"","original":"Ich ließe dich nicht leiden so wahr ich leben mag.","ipa":"/ɪç lˈiːsə dɪç nˈɪçt lˈaɪdən zoː vˈɑːɾ ɪç lˈeːbən mˈɑːk/","en":"I wouldn't let you suffer as true as I may live.","zh":"我不会让你受苦我以我的生命起誓","note":"","sourceLineIndex":5},{"id":"dracula-das-musical-20-007","lineIndex":3,"speaker":"","original":"Du hast mein Wort!","ipa":"/duː hast maɪn vˈɔɾt/","en":"You have my word!","zh":"你得到了我的诺言！","note":"","sourceLineIndex":7}],"sourceOrder":20,"displayOrder":19},{"order":21,"id":"21-eh-du-verloren-bist","title":"Eh du verloren bist","titleZh":"在你迷失之前","lines":[{"id":"dracula-das-musical-21-001","lineIndex":1,"speaker":"","original":"Jetzt wo wir stehen vor der Höhle des Löwen","ipa":"/jˌɛtst vˌoː viːɾ ʃtˈeːən fˌɔɾ dɛɾ hˈøːlə dɛs lˈøːvən/","en":"Now that we are standing in front of the lion's den","zh":"现在我们站在虎穴（狮子洞）前","note":"","sourceLineIndex":1},{"id":"dracula-das-musical-21-002","lineIndex":2,"speaker":"","original":"Heißt es entschlossen zu sein","ipa":"/hˈaɪst ɛs ɛntʃlˈɔsən tsuː zaɪn/","en":"It means being determined","zh":"也就是说必须坚定信念","note":"","sourceLineIndex":2},{"id":"dracula-das-musical-21-003","lineIndex":3,"speaker":"","original":"Nur unser mut in der stunde der Wahrheit","ipa":"/nˈuːɾ ˌʊnzɜ mˈuːt ɪn dɛɾ ʃtˈʊndə dɛɾ vˈɑːɾhaɪt/","en":"Only our courage in the moment of truth","zh":"只有真理时刻我们的勇气","note":"","sourceLineIndex":3},{"id":"dracula-das-musical-21-004","lineIndex":4,"speaker":"","original":"vermag uns vom Feind zu befreien","ipa":"/fɛɾmˈɑːk ʊns fɔm fˈaɪnt tsuː bəfrˈaɪən/","en":"can free us from the enemy","zh":"可以把我们从敌人那里解救","note":"","sourceLineIndex":4},{"id":"dracula-das-musical-21-005","lineIndex":5,"speaker":"","original":"Wir sind wie türme auf mächtigen Klippen","ipa":"/viːɾ zɪnt viː tˈʏɾmə aʊf mˈɛçtɪɡən klˈɪpən/","en":"We are like towers on mighty cliffs","zh":"我们像悬崖边的灯塔","note":"","sourceLineIndex":5},{"id":"dracula-das-musical-21-006","lineIndex":6,"speaker":"","original":"Wie Feuer in der Nacht","ipa":"/viː fˈɔøɜ ɪn dɛɾ nˈaxt/","en":"Like fire in the night","zh":"像夜晚的火","note":"","sourceLineIndex":6},{"id":"dracula-das-musical-21-007","lineIndex":7,"speaker":"","original":"Wir sind das licht","ipa":"/viːɾ zɪnt das lˈɪçt/","en":"We are the light","zh":"我们是光","note":"","sourceLineIndex":7},{"id":"dracula-das-musical-21-008","lineIndex":8,"speaker":"","original":"Es werde licht","ipa":"/ɛs vˌɛɾdə lˈɪçt/","en":"Let there be light","zh":"会有光明","note":"","sourceLineIndex":8},{"id":"dracula-das-musical-21-009","lineIndex":9,"speaker":"","original":"In diesem Kampf darf man nicht unterliegen","ipa":"/ɪn dˌiːzəm kˈampf dˈaɾf man nˈɪçt ˌʊntɜlˈiːɡən/","en":"You cannot lose in this fight","zh":"这场战斗不能输","note":"","sourceLineIndex":9},{"id":"dracula-das-musical-21-010","lineIndex":10,"speaker":"","original":"Heute geht es um leben und tot","ipa":"/hˈɔøtə ɡˈeːt ɛs ʊm lˈeːbən ʊnt tˈoːt/","en":"Today it's about living and dead","zh":"生死攸关","note":"","sourceLineIndex":10},{"id":"dracula-das-musical-21-011","lineIndex":11,"speaker":"","original":"Wir sind wie Ritter von edler Gesinnung","ipa":"/viːɾ zɪnt viː rˈɪtɜ fɔn ˈɛdlɜ ɡəzˈɪnʊŋ/","en":"We are like knights of noble spirit","zh":"我们是情感高尚的骑士","note":"","sourceLineIndex":11},{"id":"dracula-das-musical-21-012","lineIndex":12,"speaker":"","original":"Helfer in elend und Not","ipa":"/hˈɛlfɜ ɪn ˈeːlɛnt ʊnt nˈoːt/","en":"Helpers in misery and need","zh":"救人于不幸和苦难","note":"","sourceLineIndex":12},{"id":"dracula-das-musical-21-013","lineIndex":13,"speaker":"","original":"Wir sind der funke auf trockenen Zunder","ipa":"/viːɾ zɪnt dɛɾ fˈʊŋkə aʊf tɾˈɔkənən tsˈʊndɜ/","en":"We are the spark on dry tinder","zh":"我们是干燥火种上的火星","note":"","sourceLineIndex":13},{"id":"dracula-das-musical-21-014","lineIndex":14,"speaker":"","original":"Die Asche die noch glüht","ipa":"/diː ˈaʃə diː nɔx ɡlˈyːt/","en":"The ashes that still glow","zh":"仍在发光的灰烬","note":"","sourceLineIndex":14},{"id":"dracula-das-musical-21-015","lineIndex":15,"speaker":"","original":"Wir wollen stark sein und","ipa":"/viːɾ vɔlən ʃtˈaɾk zaɪn ˈʊnt/","en":"We want to be strong and","zh":"我们要坚强","note":"","sourceLineIndex":15},{"id":"dracula-das-musical-21-016","lineIndex":16,"speaker":"","original":"beten das Gott uns behüt","ipa":"/bˈeːtən das ɡˈɔt ʊns bəhˈyːt/","en":"pray that God protects us","zh":"请求上帝保护我们","note":"","sourceLineIndex":16},{"id":"dracula-das-musical-21-017","lineIndex":17,"speaker":"","original":"Eh du verloren bist in der Gefahr der Nacht","ipa":"/ˈeː duː fɛɾlˈoːrən bɪst ɪn dɛɾ ɡəfˈɑːɾ dɛɾ nˈaxt/","en":"Before you are lost in the danger of the night","zh":"假若你在夜晚的危险中迷失","note":"","sourceLineIndex":17},{"id":"dracula-das-musical-21-018","lineIndex":18,"speaker":"","original":"Zünde ein Feuer an hell wie die Sterne","ipa":"/tsˈʏndə aɪn fˈɔøɜ an hˈɛl viː diː ʃtˈɛɾnə/","en":"Light a fire bright as the stars","zh":"点一支火，明亮如星","note":"","sourceLineIndex":18},{"id":"dracula-das-musical-21-019","lineIndex":19,"speaker":"","original":"Und aus dem schattenreich hebt sich ein Lichtermeer","ipa":"/ʊnt ˌaʊs deːm ʃˈatənrˌaɪç hˈeːpt zɪç aɪn lˈɪçtɜmˌeːɾ/","en":"And out of the shadows a sea of lights emerges","zh":"黑暗的世界中升起一片光","note":"","sourceLineIndex":19},{"id":"dracula-das-musical-21-020","lineIndex":20,"speaker":"","original":"Derer die aufrecht stehen deutlich und klar","ipa":"/dɛrɜ diː ˈaʊfrˌɛçt ʃtˈeːən dˈɔøtlɪç ʊnt klˈɑːɾ/","en":"Those who stand upright clearly and clearly","zh":"笔直而上，清楚明亮","note":"","sourceLineIndex":20},{"id":"dracula-das-musical-21-021","lineIndex":21,"speaker":"","original":"Siehst du den weg aus Tod und Gefahr","ipa":"/zˈiːst duː deːn vˈɛk ˌaʊs tˈoːt ʊnt ɡəfˈɑːɾ/","en":"Do you see the way out of death and danger","zh":"你就能从死神和危险中找到出路","note":"","sourceLineIndex":21},{"id":"dracula-das-musical-21-022","lineIndex":22,"speaker":"","original":"Soll die Entscheidung nun fallen","ipa":"/zˌɔl diː ɛntʃˈaɪdʊŋ nˈuːn fˈalən/","en":"The decision should now be made","zh":"如果要裁决","note":"","sourceLineIndex":22},{"id":"dracula-das-musical-21-023","lineIndex":23,"speaker":"","original":"Finster in feindlicher Welt","ipa":"/fˈiːnstɜ ɪn fˈaɪntlɪçɜ vˈɛlt/","en":"Dark in a hostile world","zh":"充满敌意的世界里的阴暗","note":"","sourceLineIndex":23},{"id":"dracula-das-musical-21-024","lineIndex":24,"speaker":"","original":"Hell brennt das licht in uns allen","ipa":"/hˈɛl bɾˈɛnt das lˈɪçt ɪn ʊns ˈalən/","en":"The light burns brightly in all of us","zh":"我们心里燃着明亮的光","note":"","sourceLineIndex":24},{"id":"dracula-das-musical-21-025","lineIndex":25,"speaker":"","original":"Wenn er fällt geht die sonne auf","ipa":"/vˌɛn ɛɾ fˈɛlt ɡˈeːt diː zˈɔnə ˈaʊf/","en":"When it falls the sun rises","zh":"当他倒下，太阳会升起","note":"","sourceLineIndex":25},{"id":"dracula-das-musical-21-026","lineIndex":26,"speaker":"","original":"Eh du verloren bist in der Gefahr der Nacht","ipa":"/ˈeː duː fɛɾlˈoːrən bɪst ɪn dɛɾ ɡəfˈɑːɾ dɛɾ nˈaxt/","en":"Before you are lost in the danger of the night","zh":"假若你在夜晚的危险中迷失","note":"","sourceLineIndex":26},{"id":"dracula-das-musical-21-027","lineIndex":27,"speaker":"","original":"Zünde ein Feuer an hell wie die Sterne","ipa":"/tsˈʏndə aɪn fˈɔøɜ an hˈɛl viː diː ʃtˈɛɾnə/","en":"Light a fire bright as the stars","zh":"点一支火，明亮如星","note":"","sourceLineIndex":27},{"id":"dracula-das-musical-21-028","lineIndex":28,"speaker":"","original":"Und aus dem schattenreich hebt sich ein Lichtermeer","ipa":"/ʊnt ˌaʊs deːm ʃˈatənrˌaɪç hˈeːpt zɪç aɪn lˈɪçtɜmˌeːɾ/","en":"And out of the shadows a sea of lights emerges","zh":"黑暗的世界中升起一片光","note":"","sourceLineIndex":28},{"id":"dracula-das-musical-21-029","lineIndex":29,"speaker":"","original":"Derer die aufrecht stehen deutlich und klar","ipa":"/dɛrɜ diː ˈaʊfrˌɛçt ʃtˈeːən dˈɔøtlɪç ʊnt klˈɑːɾ/","en":"Those who stand upright clearly and clearly","zh":"笔直而上，清楚明亮","note":"","sourceLineIndex":29},{"id":"dracula-das-musical-21-030","lineIndex":30,"speaker":"","original":"Siehst du den weg","ipa":"/zˈiːst duː deːn vˈɛk/","en":"Do you see it gone?","zh":"你就能找到出路","note":"","sourceLineIndex":30},{"id":"dracula-das-musical-21-031","lineIndex":31,"speaker":"","original":"Eh du verloren bist in der Gefahr der Nacht","ipa":"/ˈeː duː fɛɾlˈoːrən bɪst ɪn dɛɾ ɡəfˈɑːɾ dɛɾ nˈaxt/","en":"Before you are lost in the danger of the night","zh":"假若你在夜晚的危险中迷失","note":"","sourceLineIndex":31},{"id":"dracula-das-musical-21-032","lineIndex":32,"speaker":"","original":"Zünde ein Feuer an hell wie die Sterne","ipa":"/tsˈʏndə aɪn fˈɔøɜ an hˈɛl viː diː ʃtˈɛɾnə/","en":"Light a fire bright as the stars","zh":"点一支火，明亮如星","note":"","sourceLineIndex":32},{"id":"dracula-das-musical-21-033","lineIndex":33,"speaker":"","original":"Und aus dem schattenreich hebt sich ein Lichtermeer","ipa":"/ʊnt ˌaʊs deːm ʃˈatənrˌaɪç hˈeːpt zɪç aɪn lˈɪçtɜmˌeːɾ/","en":"And out of the shadows a sea of lights emerges","zh":"黑暗的世界中升起一片光","note":"","sourceLineIndex":33},{"id":"dracula-das-musical-21-034","lineIndex":34,"speaker":"","original":"Derer die aufrecht stehen deutlich und klar","ipa":"/dɛrɜ diː ˈaʊfrˌɛçt ʃtˈeːən dˈɔøtlɪç ʊnt klˈɑːɾ/","en":"Those who stand upright clearly and clearly","zh":"笔直而上，清楚明亮","note":"","sourceLineIndex":34},{"id":"dracula-das-musical-21-035","lineIndex":35,"speaker":"","original":"Siehst du den weg aus Tod und Gefahr","ipa":"/zˈiːst duː deːn vˈɛk ˌaʊs tˈoːt ʊnt ɡəfˈɑːɾ/","en":"Do you see the way out of death and danger","zh":"你就能从死神和危险中找到出路","note":"","sourceLineIndex":35}],"sourceOrder":21,"displayOrder":20},{"order":22,"id":"22-die-zugsequenz","title":"Die Zugsequenz","titleZh":"列车场景","lines":[{"id":"dracula-das-musical-22-001","lineIndex":1,"speaker":"","original":"Nun, Augen zu","ipa":"/nˈuːn ˈaʊɡən tsˈuː/","en":"Well, close your eyes","zh":"现在闭上眼睛","note":"","sourceLineIndex":1},{"id":"dracula-das-musical-22-002","lineIndex":2,"speaker":"","original":"mein schönes Kind","ipa":"/maɪn ʃˈøːnəs kˈɪnt/","en":"my beautiful child","zh":"我美丽的小姐","note":"","sourceLineIndex":2},{"id":"dracula-das-musical-22-003","lineIndex":3,"speaker":"","original":"Die Sonne geht bald unter","ipa":"/diː zˈɔnə ɡˈeːt bˈalt ˈʊntɜ/","en":"The sun will soon set","zh":"太阳马上落山","note":"","sourceLineIndex":3},{"id":"dracula-das-musical-22-004","lineIndex":4,"speaker":"","original":"Sie fühlen jetzt","ipa":"/ziː fˈyːlən jˈɛtst/","en":"You feel now","zh":"你现在会感觉到","note":"","sourceLineIndex":4},{"id":"dracula-das-musical-22-005","lineIndex":5,"speaker":"","original":"das was er fühlt","ipa":"/das vˈas ɛɾ fˈyːlt/","en":"what he feels","zh":"他所感觉到的一切","note":"","sourceLineIndex":5},{"id":"dracula-das-musical-22-006","lineIndex":6,"speaker":"","original":"und sprechen mit der Stimme","ipa":"/ʊnt ʃpɾˈɛçən mɪt dɛɾ ʃtˈɪmə/","en":"and speak with the voice","zh":"请用心感受","note":"","sourceLineIndex":6},{"id":"dracula-das-musical-22-007","lineIndex":7,"speaker":"","original":"die sich erhebt im Gemüt","ipa":"/diː zɪç ɛɾhˈeːpt ɪm ɡəmˈyːt/","en":"which rises in the mind","zh":"描述出","note":"","sourceLineIndex":7},{"id":"dracula-das-musical-22-008","lineIndex":8,"speaker":"","original":"wenn der Untote lebt","ipa":"/vˌɛn dɛɾ ˈʊntˌoːtə lˈeːpt/","en":"if the undead is alive","zh":"那不死之物的踪迹","note":"","sourceLineIndex":8},{"id":"dracula-das-musical-22-009","lineIndex":9,"speaker":"","original":"Dracula (Mina): Dunkelheit, ich höre wie das Wasser rauscht","ipa":"/dɾˈɑkuːlˌɑː mˈiːnɑː dˈʊnkəlhˌaɪt ɪç hˈøːrə viː das vˈasɜ rˈaʊʃt/","en":"Dracula (Mina): Darkness, I hear the water rushing","zh":"德古拉（米娅）：黑暗，我听见水流动的声音","note":"","sourceLineIndex":9},{"id":"dracula-das-musical-22-010","lineIndex":10,"speaker":"","original":"ich höre wie das Wasser rauscht","ipa":"/ɪç hˈøːrə viː das vˈasɜ rˈaʊʃt/","en":"I hear the water rushing","zh":"我听见水流动的声音","note":"","sourceLineIndex":10},{"id":"dracula-das-musical-22-011","lineIndex":11,"speaker":"","original":"ein ruhiger Fluss im Hinterland","ipa":"/aɪn rˈuːɪɡɜ flˈʊs ɪm hˌɪntɜlˈant/","en":"a quiet river in the hinterland","zh":"后方有一条安静的河流","note":"","sourceLineIndex":11},{"id":"dracula-das-musical-22-012","lineIndex":12,"speaker":"","original":"Viehgebrüll (Viehgebrüll)","ipa":"/fˈiːhɡɛbɾˌʏl fˈiːhɡɛbɾˌʏl/","en":"cattle roar (cattle roar)","zh":"牲畜的吼叫声（牲畜的吼叫声）","note":"","sourceLineIndex":12},{"id":"dracula-das-musical-22-013","lineIndex":13,"speaker":"","original":"vermischt sich (mit der Wellen Klang)","ipa":"/fɛɾmˈɪʃt zɪç mɪt dɛɾ vˈɛlən klˈaŋ/","en":"mixes (with the waves sound)","zh":"混合着（水声）","note":"","sourceLineIndex":13},{"id":"dracula-das-musical-22-014","lineIndex":14,"speaker":"","original":"mit der Wellen Klang","ipa":"/mɪt dɛɾ vˈɛlən klˈaŋ/","en":"with the waves sound","zh":"水声","note":"","sourceLineIndex":14},{"id":"dracula-das-musical-22-015","lineIndex":15,"speaker":"","original":"Fremde Stimmen ziehn den Flur entlang","ipa":"/frˈɛmdə ʃtˈɪmən tsˈiːn deːn flˈuːɾ ɛntlˈaŋ/","en":"Strange voices move down the hallway","zh":"陌生的话语顺着走廊进入我的脑海","note":"","sourceLineIndex":15},{"id":"dracula-das-musical-22-016","lineIndex":16,"speaker":"","original":"doch verstehe ich nicht was man spricht","ipa":"/dɔx fɛɾʃtˈeːə ɪç nˈɪçt vˈas man ʃpɾˈɪçt/","en":"but I don't understand what they're saying","zh":"但我却不明白他们在说什么","note":"","sourceLineIndex":16},{"id":"dracula-das-musical-22-017","lineIndex":17,"speaker":"","original":"Eines noch","ipa":"/ˈaɪnəs nɔx/","en":"One more thing","zh":"又一次响起","note":"","sourceLineIndex":17},{"id":"dracula-das-musical-22-018","lineIndex":18,"speaker":"","original":"es flüstert und es spricht mit mir","ipa":"/ɛs flˈʏstɜt ʊnt ɛs ʃpɾˈɪçt mɪt mˈiːɾ/","en":"it whispers and it speaks to me","zh":"在我的耳边絮语，对着我说","note":"","sourceLineIndex":18},{"id":"dracula-das-musical-22-019","lineIndex":19,"speaker":"","original":"Dracula (Mina): Ich warte sag wann kommst du her?","ipa":"/dɾˈɑkuːlˌɑː mˈiːnɑː ɪç vˈaɾtə zˈɑːk vˈan kˈɔmst duː hˈeːɾ/","en":"Dracula (Mina): I'm waiting, tell me when are you coming here?","zh":"我在等你，你什么时候会来","note":"","sourceLineIndex":19},{"id":"dracula-das-musical-22-020","lineIndex":20,"speaker":"","original":"Ich verzehre mich nach dir","ipa":"/ɪç fɛɾtsˈeːrə mɪç nɑːx dˈiːɾ/","en":"I long for you","zh":"我强烈的渴望你","note":"","sourceLineIndex":20},{"id":"dracula-das-musical-22-021","lineIndex":21,"speaker":"","original":"Jung und schön (jung und schön)","ipa":"/jˈʊŋ ʊnt ʃˈøːn jˈʊŋ ʊnt ʃˈøːn/","en":"Young and beautiful (young and beautiful)","zh":"年轻貌美（年轻貌美）","note":"","sourceLineIndex":21},{"id":"dracula-das-musical-22-022","lineIndex":22,"speaker":"","original":"Du bleibst für immer jung und schön (jung und schön)","ipa":"/duː blˈaɪbst fyːɾ ˈɪmɜ jˈʊŋ ʊnt ʃˈøːn jˈʊŋ ʊnt ʃˈøːn/","en":"You stay young and beautiful forever (young and beautiful)","zh":"你将永久年轻貌美（年轻貌美）","note":"","sourceLineIndex":22},{"id":"dracula-das-musical-22-023","lineIndex":23,"speaker":"","original":"Soll dieses Glück zu Ende gehn?","ipa":"/zˌɔl dˌiːzəs ɡlˈʏk tsuː ˈɛndə ɡˈeːn/","en":"Should this happiness come to an end?","zh":"难道这种幸福要被收回？","note":"","sourceLineIndex":23},{"id":"dracula-das-musical-22-024","lineIndex":24,"speaker":"","original":"Dracula (Mina): Wie das der ganzen Christenheit?","ipa":"/dɾˈɑkuːlˌɑː mˈiːnɑː viː das dɛɾ ɡˈantsən kɾˈɪstənhˌaɪt/","en":"Dracula (Mina): Like the whole of Christianity?","zh":"德古拉（米娅）：这就是基督的恩泽？","note":"","sourceLineIndex":24},{"id":"dracula-das-musical-22-025","lineIndex":25,"speaker":"","original":"Totgeweiht (totgeweiht)","ipa":"/tˈɔtɡeːvˌaɪht tˈɔtɡeːvˌaɪht/","en":"Doomed (Doomed)","zh":"濒临死亡（濒临死亡）","note":"","sourceLineIndex":25},{"id":"dracula-das-musical-22-026","lineIndex":26,"speaker":"","original":"Das soll nicht unser Schicksal sein","ipa":"/das zˌɔl nˈɪçt ˌʊnzɜ ʃˈɪkzɑːl zaɪn/","en":"That shouldn't be our fate","zh":"将不会是我们的命运","note":"","sourceLineIndex":26},{"id":"dracula-das-musical-22-027","lineIndex":27,"speaker":"","original":"Denn wir gehn in neue Sphären ein","ipa":"/dɛn viːɾ ɡˈeːn ɪn nˈɔøə sfˈɛːrən ˈaɪn/","en":"Because we are entering new spheres","zh":"因为我们已进入新的领域","note":"","sourceLineIndex":27},{"id":"dracula-das-musical-22-028","lineIndex":28,"speaker":"","original":"wo der Mensch sich von Gott befreit","ipa":"/vˌoː dɛɾ mˈɛnʃ zɪç fɔn ɡˈɔt bəfrˈaɪt/","en":"where man frees himself from God","zh":"在那里，人类会彻底从上帝手中解放","note":"","sourceLineIndex":28},{"id":"dracula-das-musical-22-029","lineIndex":29,"speaker":"","original":"Seelenheil","ipa":"/zˈeːlənhˌaɪl/","en":"salvation","zh":"灵魂救赎","note":"","sourceLineIndex":29},{"id":"dracula-das-musical-22-030","lineIndex":30,"speaker":"","original":"Und Gut und Böse kämpfen nicht","ipa":"/ʊnt ɡˈuːt ʊnt bˈøːzə kˈɛmpfən nˈɪçt/","en":"And good and evil don't fight","zh":"好与恶都不再斗争","note":"","sourceLineIndex":30},{"id":"dracula-das-musical-22-031","lineIndex":31,"speaker":"","original":"In meiner Welt und zögre nicht","ipa":"/ɪn mˌaɪnɜ vˈɛlt ʊnt tsˈœɡɾə nˈɪçt/","en":"In my world and don't hesitate","zh":"在我的世界里不要犹豫","note":"","sourceLineIndex":31},{"id":"dracula-das-musical-22-032","lineIndex":32,"speaker":"","original":"und geh ein in mein Reich","ipa":"/ʊnt ɡˈeː aɪn ɪn maɪn rˈaɪç/","en":"and enter my kingdom","zh":"进入我的王国吧","note":"","sourceLineIndex":32},{"id":"dracula-das-musical-22-033","lineIndex":33,"speaker":"","original":"Ein Leben mehr","ipa":"/aɪn lˈeːbən mˈeːɾ/","en":"One more life","zh":"超越此生","note":"","sourceLineIndex":33},{"id":"dracula-das-musical-22-034","lineIndex":34,"speaker":"","original":"und du entkommst dem kühlen Grab","ipa":"/ʊnt duː ɛntkˈɔmst deːm kˈyːlən ɡɾˈɑːp/","en":"and you escape the cool grave","zh":"走出那冰冷的坟墓","note":"","sourceLineIndex":34},{"id":"dracula-das-musical-22-035","lineIndex":35,"speaker":"","original":"Brauchst kein Gebet","ipa":"/bɾˈaʊxst kˈaɪn ɡeːbˈeːt/","en":"Don't need prayer","zh":"无需祈祷","note":"","sourceLineIndex":35},{"id":"dracula-das-musical-22-036","lineIndex":36,"speaker":"","original":"steigst nicht ins Totenreich hinab","ipa":"/ʃtˈaɪkst nˈɪçt ɪns tˈoːtənrˌaɪç hɪnˈap/","en":"do not descend into the realm of the dead","zh":"你再也不会死亡","note":"","sourceLineIndex":36},{"id":"dracula-das-musical-22-037","lineIndex":37,"speaker":"","original":"Spart euch den Psalm","ipa":"/ʃpˈaɾt ɔøç deːn psˈalm/","en":"Save the psalm","zh":"省省那些祷告","note":"","sourceLineIndex":37},{"id":"dracula-das-musical-22-038","lineIndex":38,"speaker":"","original":"Weint einem andern hinterher","ipa":"/vˈaɪnt ˌaɪnəm ˈandɜn hˈɪntɜhɜ/","en":"Cry after someone else","zh":"也别在事后哭泣","note":"","sourceLineIndex":38},{"id":"dracula-das-musical-22-039","lineIndex":39,"speaker":"","original":"Dracula (Mina): Denn die Gnade (die du gewährst) ich gewähr","ipa":"/dɾˈɑkuːlˌɑː mˈiːnɑː dɛn diː ɡənˈɑːdə diː duː ɡəvˈɛːɾst ɪç ɡəvˈɛːɾ/","en":"Dracula (Mina): For the grace (that you grant) I grant","zh":"德古拉（米娅）：我（你）所赐予的恩赐","note":"","sourceLineIndex":39},{"id":"dracula-das-musical-22-040","lineIndex":40,"speaker":"","original":"wiegt unendlich schwer","ipa":"/vˈiːkt ˈʊnˌɛntlɪç ʃvˈeːɾ/","en":"weighs infinitely heavy","zh":"将是无尽的沉重","note":"","sourceLineIndex":40},{"id":"dracula-das-musical-22-041","lineIndex":41,"speaker":"","original":"Ein Leben mehr","ipa":"/aɪn lˈeːbən mˈeːɾ/","en":"One more life","zh":"超越此生","note":"","sourceLineIndex":41},{"id":"dracula-das-musical-22-042","lineIndex":42,"speaker":"","original":"Weiter, nun los","ipa":"/vˈaɪtɜ nˈuːn lˈoːs/","en":"Go on, let's go","zh":"继续","note":"","sourceLineIndex":42},{"id":"dracula-das-musical-22-043","lineIndex":43,"speaker":"","original":"Ihr müsst reden!","ipa":"/iːɾ mˈʏst rˈeːdən/","en":"You have to talk!","zh":"您必须说下去","note":"","sourceLineIndex":43},{"id":"dracula-das-musical-22-044","lineIndex":44,"speaker":"","original":"Gibt es noch mehr zu erfahrn?","ipa":"/ɡˈiːpt ɛs nɔx mˈeːɾ tsuː ɛɾfˈɑːɾn/","en":"Is there more to learn?","zh":"还有更多信息吗","note":"","sourceLineIndex":44},{"id":"dracula-das-musical-22-045","lineIndex":45,"speaker":"","original":"Was ist geschehen? Wo bin ich?","ipa":"/vˈas ɪst ɡəʃˈeːən vˈoː bɪn ɪç/","en":"What happened? Where am I?","zh":"发生了什么，我在哪","note":"","sourceLineIndex":45},{"id":"dracula-das-musical-22-046","lineIndex":46,"speaker":"","original":"Sind sie böse?","ipa":"/zɪnt ziː bˈøːzə/","en":"Are they evil?","zh":"您生气了吗","note":"","sourceLineIndex":46},{"id":"dracula-das-musical-22-047","lineIndex":47,"speaker":"","original":"Was tat ich denn?","ipa":"/vˈas tˈɑːt ɪç dˈɛn/","en":"What was I doing then?","zh":"我到底做了什么","note":"","sourceLineIndex":47},{"id":"dracula-das-musical-22-048","lineIndex":48,"speaker":"","original":"Es fühlt sich an als wär's ein Traum","ipa":"/ɛs fˈyːlt zɪç an als vˈɛːɾs aɪn tɾˈaʊm/","en":"It feels like it's a dream","zh":"一切都仿佛是一场梦","note":"","sourceLineIndex":48},{"id":"dracula-das-musical-22-049","lineIndex":49,"speaker":"","original":"Es tut mir leid","ipa":"/ɛs tˈuːt miːɾ lˈaɪt/","en":"I'm sorry","zh":"非常抱歉","note":"","sourceLineIndex":49},{"id":"dracula-das-musical-22-050","lineIndex":50,"speaker":"","original":"Doch allzu kurz","ipa":"/dɔx ˈaltsuː kˈʊɐts/","en":"But all too short","zh":"但一切都太快了","note":"","sourceLineIndex":50},{"id":"dracula-das-musical-22-051","lineIndex":51,"speaker":"","original":"ist unsre Zeit der Wahrheit","ipa":"/ɪst ˌʊnzrə tsˈaɪt dɛɾ vˈɑːɾhaɪt/","en":"is our time of truth","zh":"现在是我们说出真相的时间了","note":"","sourceLineIndex":51},{"id":"dracula-das-musical-22-052","lineIndex":52,"speaker":"","original":"Die Sonne sinkt","ipa":"/diː zˈɔnə zˈɪŋkt/","en":"The sun is setting","zh":"太阳落山","note":"","sourceLineIndex":52},{"id":"dracula-das-musical-22-053","lineIndex":53,"speaker":"","original":"und schon verstummt","ipa":"/ʊnt ʃˌoːn fɛɾʃtˈʊmt/","en":"and already fell silent","zh":"万物寂静","note":"","sourceLineIndex":53},{"id":"dracula-das-musical-22-054","lineIndex":54,"speaker":"","original":"das Medium, die Stimme, die alles ahnt","ipa":"/das mˈeːdiːˌʊm diː ʃtˈɪmə diː ˈaləs ˈɑːnt/","en":"the medium, the voice that suspects everything","zh":"媒介，声音，一切能想到的东西","note":"","sourceLineIndex":54},{"id":"dracula-das-musical-22-055","lineIndex":55,"speaker":"","original":"und uns sagt was der Untote plant","ipa":"/ʊnt ʊns zˈɑːkt vˈas dɛɾ ˈʊntˌoːtə plˈant/","en":"and tells us what the undead is planning","zh":"都能告诉我们那个不死的怪物的阴谋","note":"","sourceLineIndex":55}],"sourceOrder":22,"displayOrder":21},{"order":23,"id":"23-je-langer-ich-lebe","title":"Je länger ich lebe","titleZh":"我活得越久","lines":[{"id":"dracula-das-musical-23-001","lineIndex":1,"speaker":"","original":"Ich sah so oft die Sonne untergehen.","ipa":"/ɪç zˈɑː zoː ˈɔft diː zˈɔnə ˌʊntɜɡˈeːən/","en":"I watched the sun go down so many times.","zh":"日复一日 那太阳落于我眼前","note":"","sourceLineIndex":1},{"id":"dracula-das-musical-23-002","lineIndex":2,"speaker":"","original":"Was sich bot in der Welt, ich habs bekommen","ipa":"/vˈas zɪç bˈoːt ɪn dɛɾ vˈɛlt ɪç hˈɑːps bəkˈɔmən/","en":"Whatever was in the world, I got it","zh":"我以为我已得到世间一切","note":"","sourceLineIndex":2},{"id":"dracula-das-musical-23-003","lineIndex":3,"speaker":"","original":"doch seit dem ich dich traf weiß ich nicht ein noch aus.","ipa":"/dɔx zaɪt deːm ɪç dɪç tɾˈɑːf vˈaɪs ɪç nˈɪçt aɪn nɔx ˈaʊs/","en":"but since I met you I don't know what to do next.","zh":"而自从你的出现 我便不知所措","note":"","sourceLineIndex":3},{"id":"dracula-das-musical-23-004","lineIndex":4,"speaker":"","original":"Bin vom Weg den ich kannte abgekommen.","ipa":"/bɪn fɔm vˈeːk deːn ɪç kˈantə ˈapɡəkˌɔmən/","en":"I strayed from the path I knew.","zh":"我从早已熟知的道路上迷失","note":"","sourceLineIndex":4},{"id":"dracula-das-musical-23-005","lineIndex":5,"speaker":"","original":"Je länger ich lebe desto eher stell ich in Frage was ich wil.","ipa":"/jeː lˈɛŋɜ ɪç lˈeːbə dˈɛstoː ˈeːɜ ʃtˈɛl ɪç ɪn frˈɑːɡə vˈas ɪç vˈiːl/","en":"The longer I live the more I question what I want.","zh":"越是永生越欲知生之所往","note":"","sourceLineIndex":5},{"id":"dracula-das-musical-23-007","lineIndex":6,"speaker":"","original":"Ich frag mich war je so viel Gefühl im Spiel.","ipa":"/ɪç frˈɑːk mɪç vɑːɾ jeː zoː fˈiːl ɡəfˈyːl ɪm ʃpˈiːl/","en":"I wonder, was there ever so much emotion involved?","zh":"欲知为何生如游戏","note":"","sourceLineIndex":7},{"id":"dracula-das-musical-23-008","lineIndex":7,"speaker":"","original":"Je länger ich lebe desto tiefer wag ich mich vor ins fremde Land.","ipa":"/jeː lˈɛŋɜ ɪç lˈeːbə dˈɛstoː tˈiːfɜ vˈɑːk ɪç mɪç fˌɔɾ ɪns frˈɛmdə lˈant/","en":"The longer I live, the deeper I venture into a foreign country.","zh":"越是永生 越是勇于向更深的未知前行","note":"","sourceLineIndex":8},{"id":"dracula-das-musical-23-009","lineIndex":8,"speaker":"","original":"Geb auf alle Herrlichkeit für deine Hand.","ipa":"/ɡˈeːp aʊf ˈalə hˈɛɾlɪçkˌaɪt fyːɾ dˌaɪnə hˈant/","en":"Give up all glory for your hand.","zh":"将所遇之美丽全部交于你手","note":"","sourceLineIndex":9},{"id":"dracula-das-musical-23-010","lineIndex":9,"speaker":"","original":"Auf mich allein gestellt verliert die Welt an Wert dass habe ich von dir gelernt.","ipa":"/aʊf mɪç alˈaɪn ɡəʃtˈɛlt fɛɾlˈiːɾt diː vˈɛlt an vˈɛɾt das hɑːbə ɪç fɔn diːɾ ɡəlˈɛɾnt/","en":"Left to my own devices, the world loses its value I learned that from you.","zh":"是你让我明白我孤身一人的世界失去了意义","note":"","sourceLineIndex":10},{"id":"dracula-das-musical-23-012","lineIndex":10,"speaker":"","original":"Je länger ich lebe desto größer die Sehnsucht die du heruaf beschwört..","ipa":"/jeː lˈɛŋɜ ɪç lˈeːbə dˈɛstoː ɡɾˈøːsɜ diː zˈeːnzuːxt diː duː hˈeːruːˌɑːf bəʃvˈœɾt/","en":"The longer I live, the greater the longing you conjure up.","zh":"越是永生 那由你而生的思念越加深沉","note":"","sourceLineIndex":12},{"id":"dracula-das-musical-23-013","lineIndex":11,"speaker":"","original":"Ich leb für den Tag an dem du mir gehörst.","ipa":"/ɪç lˈeːp fyːɾ deːn tˈɑːk an deːm duː miːɾ ɡəhˈøːɾst/","en":"I live for the day when you are mine.","zh":"我为你而存在","note":"","sourceLineIndex":13},{"id":"dracula-das-musical-23-014","lineIndex":12,"speaker":"","original":"Ich leb für den Tag an dem du mir gehörst.","ipa":"/ɪç lˈeːp fyːɾ deːn tˈɑːk an deːm duː miːɾ ɡəhˈøːɾst/","en":"I live for the day when you are mine.","zh":"得到你是我永生的意义","note":"","sourceLineIndex":14},{"id":"dracula-das-musical-23-015","lineIndex":13,"speaker":"","original":"Ich leb für den Tag an dem du mir gehörst!!!","ipa":"/ɪç lˈeːp fyːɾ deːn tˈɑːk an deːm duː miːɾ ɡəhˈøːɾst/","en":"I live for the day you're mine!!!","zh":"得到你是我永生的意义","note":"","sourceLineIndex":15}],"sourceOrder":23,"displayOrder":22},{"order":24,"id":"24-finale","title":"Finale","titleZh":"终曲","lines":[{"id":"dracula-das-musical-24-001","lineIndex":1,"speaker":"","original":"Ich folge dir in deine Welt ins Feuer deiner Leidenschaft.","ipa":"/ɪç fˈɔlɡə diːɾ ɪn dˌaɪnə vˈɛlt ɪns fˈɔøɜ dˌaɪnɜ lˈaɪdənʃˌaft/","en":"I follow you into your world into the fire of your passion.","zh":"我跟随你去你的世界投入你那激情的火焰。","note":"","sourceLineIndex":1},{"id":"dracula-das-musical-24-003","lineIndex":2,"speaker":"","original":"Mach mich zu deiner Braut im schwarzen Kleid","ipa":"/mˈax mɪç tsuː dˌaɪnɜ bɾˈaʊt ɪm ʃvˈaɾtsən klˈaɪt/","en":"Make me your bride in a black dress","zh":"让我成为你的黑衣新娘","note":"","sourceLineIndex":3},{"id":"dracula-das-musical-24-004","lineIndex":3,"speaker":"","original":"und gib mir deine Hand in Ewigkeit","ipa":"/ʊnt ɡˈiːp miːɾ dˌaɪnə hˈant ɪn ˈeːvɪçkˌaɪt/","en":"and give me your hand forever","zh":"永远抓紧你的手","note":"","sourceLineIndex":4},{"id":"dracula-das-musical-24-005","lineIndex":4,"speaker":"","original":"die Liebe macht uns blind","ipa":"/diː lˈiːbə mˈaxt ʊns blˈɪnt/","en":"love makes us blind","zh":"爱让我们盲目","note":"","sourceLineIndex":5},{"id":"dracula-das-musical-24-006","lineIndex":5,"speaker":"","original":"wie schuldig wir auch sind","ipa":"/viː ʃˈʊldɪç viːɾ ˌaʊx zɪnt/","en":"no matter how guilty we are","zh":"看不见我们的罪恶","note":"","sourceLineIndex":6},{"id":"dracula-das-musical-24-007","lineIndex":6,"speaker":"","original":"doch lieber diese Schuld","ipa":"/dɔx lˈiːbɜ dˌiːzə ʃˈʊlt/","en":"but rather this guilt","zh":"但是即使是罪恶","note":"","sourceLineIndex":7},{"id":"dracula-das-musical-24-008","lineIndex":7,"speaker":"","original":"als niemals so entflammt","ipa":"/als nˈiːmɑːls zoː ɛntflˈamt/","en":"as never so inflamed","zh":"也从未如此燃烧着我","note":"","sourceLineIndex":8},{"id":"dracula-das-musical-24-009","lineIndex":8,"speaker":"","original":"Wir folgen unsrem Stern und werden neu geboren.","ipa":"/viːɾ fˈɔlɡən ˈʊnsrəm ʃtˈɛɾn ʊnt vˌɛɾdən nˈɔø ɡəbˈoːrən/","en":"We follow our star and are born again.","zh":"我们追寻我们的星星获得了重生。","note":"","sourceLineIndex":9},{"id":"dracula-das-musical-24-011","lineIndex":9,"speaker":"","original":"Der Stern wird niemals sinken der Stern wird niemals sinken der Stern wird nie vergehn.","ipa":"/dɛɾ ʃtˈɛɾn vˌɪɾt nˈiːmɑːls zˈɪŋkən dɛɾ ʃtˈɛɾn vˌɪɾt nˈiːmɑːls zˈɪŋkən dɛɾ ʃtˈɛɾn vˌɪɾt nˈiː fɛɾɡˈeːn/","en":"The star will never sink the star will never sink the star will never fade.","zh":"星星永远不会沉没星星永远不会沉没星星永远不会消逝。","note":"","sourceLineIndex":11},{"id":"dracula-das-musical-24-014","lineIndex":10,"speaker":"","original":"Ich hoer dich bevor du sprichst bin bei dir wo immer du bist.","ipa":"/ɪç hˈøːɾ dɪç bəfˈoːɾ duː ʃpɾˈɪkst bɪn baɪ diːɾ vˌoː ˈɪmɜ duː bɪst/","en":"I hear you before you speak am with you wherever you are.","zh":"即使你不开口，我也能听见你让我跟随你去天涯海角。","note":"","sourceLineIndex":14},{"id":"dracula-das-musical-24-016","lineIndex":11,"speaker":"","original":"Ich bin da, in deinem Traum und ich weiss, dass du mich vermisst.","ipa":"/ɪç bɪn dˈɑː ɪn dˌaɪnəm tɾˈaʊm ʊnt ɪç vˈaɪs das duː mɪç fɛɾmˈɪst/","en":"I'm there, in your dream and I know that you miss me.","zh":"我在这里，在你的梦里我知道，你在想念我。","note":"","sourceLineIndex":16},{"id":"dracula-das-musical-24-018","lineIndex":12,"speaker":"","original":"Ich sah dich und wusste gleich diese Frau wird mir gehoeren","ipa":"/ɪç zˈɑː dɪç ʊnt vˈʊstə ɡlˈaɪç dˌiːzə frˈaʊ vˌɪɾt miːɾ ɡəhˈøːrən/","en":"I saw you and immediately knew this woman would be mine","zh":"自从第一眼见你，我就知道你属于我","note":"","sourceLineIndex":18},{"id":"dracula-das-musical-24-019","lineIndex":13,"speaker":"","original":"wie hat dein Wesen mich beruehrt","ipa":"/viː hat daɪn vˈeːzən mɪç bərˈuːeːɾt/","en":"how did your being touch me","zh":"你的灵魂激荡着我","note":"","sourceLineIndex":19},{"id":"dracula-das-musical-24-020","lineIndex":14,"speaker":"","original":"kaum noch faehig mich zu wehren.","ipa":"/kˈaʊm nɔx fˈɛːhɪç mɪç tsuː vˈeːrən/","en":"barely able to defend myself.","zh":"我难以控制自己。","note":"","sourceLineIndex":20},{"id":"dracula-das-musical-24-021","lineIndex":15,"speaker":"","original":"Mina du bist auserwaehlt und von allen dieser Welt bist du die Einzige die zaehlt.","ipa":"/mˈiːnɑː duː bɪst ˈaʊsɛɾvˌɛhlt ʊnt fɔn ˈalən dˌiːzɜ vˈɛlt bɪst duː diː ˈaɪntsɪɡə diː tsˈɛhlt/","en":"Mina you are chosen and of all this world you are the only one who counts.","zh":"米娜你是被选中的人在这个世界上除了你再无他人。","note":"","sourceLineIndex":21},{"id":"dracula-das-musical-24-023","lineIndex":16,"speaker":"","original":"Ich sah dich und wollte nur","ipa":"/ɪç zˈɑː dɪç ʊnt vɔltə nˈuːɾ/","en":"I saw you and just wanted","zh":"我看见了你，我只想知道","note":"","sourceLineIndex":23},{"id":"dracula-das-musical-24-024","lineIndex":17,"speaker":"","original":"wollte nur, erkennen wer ich war","ipa":"/vɔltə nˈuːɾ ɛɾkˈɛnən vˈeːɾ ɪç vɑːɾ/","en":"just wanted to realize who I was","zh":"我只想知道，我存在的意义究竟是什么","note":"","sourceLineIndex":24},{"id":"dracula-das-musical-24-025","lineIndex":18,"speaker":"","original":"das ich verliebt war wie noch nie","ipa":"/das ɪç fɛɾlˈiːpt vɑːɾ viː nɔx nˈiː/","en":"that I was in love like never before","zh":"我从来没有这样爱过","note":"","sourceLineIndex":25},{"id":"dracula-das-musical-24-026","lineIndex":19,"speaker":"","original":"und ich liebte die Gefahr","ipa":"/ʊnt ɪç lˈiːptə diː ɡəfˈɑːɾ/","en":"and I loved the danger","zh":"迷恋这种危险","note":"","sourceLineIndex":26},{"id":"dracula-das-musical-24-027","lineIndex":20,"speaker":"","original":"doch nun gibt es kein Zurueck.","ipa":"/dɔx nˈuːn ɡˈiːpt ɛs kˈaɪn tsuːrˈuːɛk/","en":"but now there is no turning back.","zh":"但现在已经无路可退。","note":"","sourceLineIndex":27},{"id":"dracula-das-musical-24-028","lineIndex":21,"speaker":"","original":"Ich verlasse Raum und Zeit","ipa":"/ɪç fɛɾlˈasə rˈaʊm ʊnt tsˈaɪt/","en":"I leave space and time","zh":"我抛下所有的时空","note":"","sourceLineIndex":28},{"id":"dracula-das-musical-24-029","lineIndex":22,"speaker":"","original":"nur die Welt der Dunkelheit","ipa":"/nˈuːɾ diː vˈɛlt dɛɾ dˈʊnkəlhˌaɪt/","en":"only the world of darkness","zh":"只向往那黑暗世界","note":"","sourceLineIndex":29},{"id":"dracula-das-musical-24-030","lineIndex":23,"speaker":"","original":"unterwarf mich deiner Macht","ipa":"/ˌʊntɜvˈaɾf mɪç dˌaɪnɜ mˈaxt/","en":"submitted me to your power","zh":"把我吸纳入你的力量","note":"","sourceLineIndex":30},{"id":"dracula-das-musical-24-031","lineIndex":24,"speaker":"","original":"und umarme nur die Nacht.","ipa":"/ʊnt ˈʊmˌaɾmə nˈuːɾ diː nˈaxt/","en":"and just embrace the night.","zh":"让黑夜拥抱我。","note":"","sourceLineIndex":31},{"id":"dracula-das-musical-24-032","lineIndex":25,"speaker":"","original":"Ich bin da, in deinem Traeum und ich weiss, dass du mich vermisst.","ipa":"/ɪç bɪn dˈɑː ɪn dˌaɪnəm tɾˈɛːʊm ʊnt ɪç vˈaɪs das duː mɪç fɛɾmˈɪst/","en":"I am there, in your dream and I know you miss me.","zh":"我在这里，在你的梦里我知道，你在想念我。","note":"","sourceLineIndex":32},{"id":"dracula-das-musical-24-034","lineIndex":26,"speaker":"","original":"Doch immer wenn ich vor dir steh","ipa":"/dɔx ˈɪmɜ vˌɛn ɪç fˌɔɾ diːɾ ʃtˈeː/","en":"But whenever I stand in front of you","zh":"但每当我站在你面前","note":"","sourceLineIndex":34},{"id":"dracula-das-musical-24-035","lineIndex":27,"speaker":"","original":"nagen Zweifel tief in mir","ipa":"/nˈɑːʒən tsvˈaɪfəl tˈiːf ɪn mˈiːɾ/","en":"doubts gnaw deep within me","zh":"内心深处的犹疑都啃噬着我","note":"","sourceLineIndex":35},{"id":"dracula-das-musical-24-036","lineIndex":28,"speaker":"","original":"denn ich verhindere deinen Tod","ipa":"/dɛn ɪç fɛɾhˈɪndərə dˌaɪnən tˈoːt/","en":"because I will prevent your death","zh":"因为我会给你永生","note":"","sourceLineIndex":36},{"id":"dracula-das-musical-24-037","lineIndex":29,"speaker":"","original":"und geb dir Einsamkeit dafuer.","ipa":"/ʊnt ɡˈeːp diːɾ ˈaɪnzˌɑːmkaɪt dˈɑfuːɜ/","en":"and give yourself solitude in return.","zh":"让你因此永远孤独。","note":"","sourceLineIndex":37},{"id":"dracula-das-musical-24-038","lineIndex":30,"speaker":"","original":"Warum lass ich dich nicht frei","ipa":"/vɑːrˈʊm lˈas ɪç dɪç nˈɪçt frˈaɪ/","en":"Why don't I set you free","zh":"为什么我不让你自由","note":"","sourceLineIndex":38},{"id":"dracula-das-musical-24-039","lineIndex":31,"speaker":"","original":"gebe auf und rette dich","ipa":"/ɡˈeːbə aʊf ʊnt rˈɛtə dˈɪç/","en":"give up and save yourself","zh":"放弃这一切，拯救你","note":"","sourceLineIndex":39},{"id":"dracula-das-musical-24-040","lineIndex":32,"speaker":"","original":"und bitt dich, tu das auch fuer mich.","ipa":"/ʊnt bˈɪt dˈɪç tˈuː das ˌaʊx fyːɾ mɪç/","en":"and ask you to do the same for me.","zh":"请你也这样放弃我。","note":"","sourceLineIndex":40},{"id":"dracula-das-musical-24-041","lineIndex":33,"speaker":"","original":"Nur um dich zu lieben wurde ich geboren das allein ist wahr und ich wollt es nicht sehn.","ipa":"/nˈuːɾ ʊm dɪç tsuː lˈiːbən vˌʊɐdə ɪç ɡəbˈoːrən das alˈaɪn ɪst vˈɑːɾ ʊnt ɪç vɔlt ɛs nˈɪçt zˈeːn/","en":"I was born just to love you That alone is true and I didn't want to see it.","zh":"爱你就是我生命的全部即使永生孤独我也在所不惜。","note":"","sourceLineIndex":41},{"id":"dracula-das-musical-24-043","lineIndex":34,"speaker":"","original":"Ist es wirklich Liebe zeig mir deine Liebe hilf mir meinen Weg nur zu Ende zu gehen.","ipa":"/ɪst ɛs vˈɪɾklɪç lˈiːbə tsˈaɪk miːɾ dˌaɪnə lˈiːbə hˈɪlf miːɾ mˌaɪnən vˈeːk nˈuːɾ tsuː ˈɛndə tsuː ɡˈeːən/","en":"Is it really love show me your love help me just to complete my journey.","zh":"这真的是爱吗如果你爱我帮我走向我注定的毁灭吧。","note":"","sourceLineIndex":43},{"id":"dracula-das-musical-24-046","lineIndex":35,"speaker":"","original":"Wie ein Gift wirkt mein Kuss meine Welt ist brutal.","ipa":"/viː aɪn ɡˈɪft vˈɪɾkt maɪn kˈʊs mˌaɪnə vˈɛlt ɪst bɾuːtˈɑːl/","en":"My kiss acts like a poison my world is brutal.","zh":"我的吻就像是毒药我的世界残忍血腥。","note":"","sourceLineIndex":46},{"id":"dracula-das-musical-24-048","lineIndex":36,"speaker":"","original":"Ich will nicht, das du verendest im Blutrausch und Qual.","ipa":"/ɪç vɪl nˈɪçt das duː fɛɾˈɛndəst ɪm blˈʊtɾaʊʃ ʊnt kvˈɑːl/","en":"I don't want you to die in bloodlust and torment.","zh":"我不愿你在血腥和悲伤中消亡。","note":"","sourceLineIndex":48},{"id":"dracula-das-musical-24-049","lineIndex":37,"speaker":"","original":"Alles was du Leben nennst ging bald in dir verloren jede Nacht in Blut getraenkt verbissen voller Gier.","ipa":"/ˈaləs vˈas duː lˈeːbən nˈɛnst ɡˈɪŋ bˈalt ɪn diːɾ fɛɾlˈoːrən jˈeːdə nˈaxt ɪn blˈuːt ɡətɾˈɛŋkt fɛɾbˈɪsən fˈɔlɜ ɡˈiːɾ/","en":"Everything you call life soon got lost in you soaked in blood every night doggedly full of greed.","zh":"所有鲜活的生命都在手中流走夜夜浸满鲜血盛满贪欲。","note":"","sourceLineIndex":49},{"id":"dracula-das-musical-24-053","lineIndex":38,"speaker":"","original":"Was soll all die Ewigkeit wenn wir nur vegetieren?","ipa":"/vˈas zˌɔl ˈal diː ˈeːvɪçkˌaɪt vˌɛn viːɾ nˈuːɾ vˌeːɡeːtˈiːrən/","en":"What's the point of all eternity if we just vegetate?","zh":"永生又有什么意义如果活得如同行尸走肉？","note":"","sourceLineIndex":53},{"id":"dracula-das-musical-24-055","lineIndex":39,"speaker":"","original":"Liebst du mich, dann lass mich frei erloese mich von mir.","ipa":"/lˈiːpst duː mɪç dan lˈas mɪç frˈaɪ ɛɾlˈøːzə mɪç fɔn mˈiːɾ/","en":"If you love me, then set me free release me from myself.","zh":"如果你爱我，就让我自由让我从这种生活中解脱。","note":"","sourceLineIndex":55},{"id":"dracula-das-musical-24-057","lineIndex":40,"speaker":"","original":"Lass mich nicht beenden was grad erst begann.","ipa":"/lˈas mɪç nˈɪçt bəˈɛndən vˈas ɡɾˈɑːt ˈeːɾst bəɡˈan/","en":"Don't let me finish what was just beginning.","zh":"不要让我放弃这一切才刚刚开始。","note":"","sourceLineIndex":57},{"id":"dracula-das-musical-24-059","lineIndex":41,"speaker":"","original":"Zeig mir wie es Nacht wird schenk mir dunklen Frieden rette, wenn du kannst diese Seele in Not.","ipa":"/tsˈaɪk miːɾ viː ɛs nˈaxt vˌɪɾt ʃˈɛŋk miːɾ dˈʊŋklən frˈiːdən rˈɛtə vˌɛn duː kˌanst dˌiːzə zˈeːlə ɪn nˈoːt/","en":"Show me how night falls give me dark peace save, if you can, this soul in need.","zh":"让我看看真正的黑夜让我得到最终的平静你能拯救我灵魂的渴求。","note":"","sourceLineIndex":59},{"id":"dracula-das-musical-24-062","lineIndex":42,"speaker":"Dracula & Mina","original":"Nur fuer deine Liebe werde ich jetzt sterben.","ipa":"/nˈuːɾ fyːɾ dˌaɪnə lˈiːbə vˌɛɾdə ɪç jˌɛtst ʃtˈɛɾbən/","en":"Only for your love I will die now.","zh":"只为了你的真爱我将死去。","note":"","sourceLineIndex":62},{"id":"dracula-das-musical-24-064","lineIndex":43,"speaker":"Dracula & Mina","original":"Du bist meine Lieben mein Lieben in Leben und Tod.","ipa":"/duː bɪst mˌaɪnə lˈiːbən maɪn lˈiːbən ɪn lˈeːbən ʊnt tˈoːt/","en":"You are my loves my love in life and death.","zh":"你是我的真爱无论生死我都爱着你。","note":"","sourceLineIndex":64}],"sourceOrder":24,"displayOrder":23}];
